    def _blend_ellipse(
        self,
        frame,
        center_pixel,
        color,
        radius_x,
        radius_y,
        axis_pixel=None,
        blend=0.50,
    ):
        height, width = frame.shape[:2]
        center_x = float(center_pixel[0].item())
        center_y = float(center_pixel[1].item())
        if center_x < 0.0 or center_x >= width or center_y < 0.0 or center_y >= height:
            return

        if axis_pixel is None:
            axis = frame.new_tensor([1.0, 0.0], dtype=torch.float32)
        else:
            axis = axis_pixel - center_pixel
            axis_norm = torch.linalg.norm(axis)
            if float(axis_norm.item()) < 1e-6:
                axis = frame.new_tensor([1.0, 0.0], dtype=torch.float32)
            else:
                axis = axis / axis_norm
        perp = frame.new_tensor([-axis[1].item(), axis[0].item()], dtype=torch.float32)

        max_radius = max(radius_x, radius_y)
        x0 = max(0, int(np.floor(center_x - max_radius - 1)))
        x1 = min(width, int(np.ceil(center_x + max_radius + 2)))
        y0 = max(0, int(np.floor(center_y - max_radius - 1)))
        y1 = min(height, int(np.ceil(center_y + max_radius + 2)))
        if x0 >= x1 or y0 >= y1:
            return

        ys = torch.arange(y0, y1, device=frame.device, dtype=torch.float32)
        xs = torch.arange(x0, x1, device=frame.device, dtype=torch.float32)
        grid_y, grid_x = torch.meshgrid(ys, xs, indexing="ij")
        delta_x = grid_x - center_x
        delta_y = grid_y - center_y
        along = delta_x * axis[0] + delta_y * axis[1]
        across = delta_x * perp[0] + delta_y * perp[1]
        ellipse_mask = ((along / float(radius_x)) ** 2 + (across / float(radius_y)) ** 2) <= 1.0
        if not bool(ellipse_mask.any().item()):
            return

        rgb_frame = frame[..., :3]
        patch = rgb_frame[y0:y1, x0:x1]
        self._blend_rgb_patch_masked_inplace(
            patch,
            ellipse_mask,
            color,
            blend=blend,
        )

    def _draw_marker_line(self, frame, start_pixel, end_pixel, color, radius=1, blend=0.45):
        height, width = frame.shape[:2]
        start_x = float(start_pixel[0].item())
        start_y = float(start_pixel[1].item())
        end_x = float(end_pixel[0].item())
        end_y = float(end_pixel[1].item())

        min_x = max(0, int(np.floor(min(start_x, end_x) - radius - 1)))
        max_x = min(width, int(np.ceil(max(start_x, end_x) + radius + 2)))
        min_y = max(0, int(np.floor(min(start_y, end_y) - radius - 1)))
        max_y = min(height, int(np.ceil(max(start_y, end_y) + radius + 2)))
        if min_x >= max_x or min_y >= max_y:
            return

        seg_x = end_x - start_x
        seg_y = end_y - start_y
        seg_len_sq = seg_x * seg_x + seg_y * seg_y
        if seg_len_sq < 1e-6:
            self._blend_marker(frame, start_pixel, color, radius=radius, blend=blend)
            return

        ys = torch.arange(min_y, max_y, device=frame.device, dtype=torch.float32)
        xs = torch.arange(min_x, max_x, device=frame.device, dtype=torch.float32)
        grid_y, grid_x = torch.meshgrid(ys, xs, indexing="ij")
        rel_x = grid_x - start_x
        rel_y = grid_y - start_y
        t = (rel_x * seg_x + rel_y * seg_y) / seg_len_sq
        t = torch.clamp(t, 0.0, 1.0)
        closest_x = start_x + t * seg_x
        closest_y = start_y + t * seg_y
        dist_x = torch.abs(grid_x - closest_x)
        dist_y = torch.abs(grid_y - closest_y)
        line_mask = torch.maximum(dist_x, dist_y) <= (float(radius) + 0.5)
        if not bool(line_mask.any().item()):
            return

        rgb_frame = frame[..., :3]
        patch = rgb_frame[min_y:max_y, min_x:max_x]
        self._blend_rgb_patch_masked_inplace(
            patch,
            line_mask,
            color,
            blend=blend,
        )

    def _blend_rgba_patch_masked_inplace(
        self,
        rgba_patch,
        mask,
        color,
        *,
        alpha=255.0,
        blend=1.0,
    ):
        if rgba_patch is None or rgba_patch.numel() == 0 or mask is None:
            return
        mask_t = mask.to(device=rgba_patch.device)
        if mask_t.dtype != torch.bool:
            mask_t = mask_t != 0
        if not bool(mask_t.any().item()):
            return
        self._blend_rgb_patch_masked_inplace(
            rgba_patch[..., :3],
            mask_t,
            color,
            blend=blend,
        )
        alpha_patch = rgba_patch[..., 3]
        alpha_value = float(alpha) * float(max(blend, 0.0))
        if torch.is_floating_point(alpha_patch):
            alpha_patch[mask_t] = torch.maximum(
                alpha_patch[mask_t],
                alpha_patch.new_full(alpha_patch[mask_t].shape, alpha_value),
            )
            return
        if alpha_patch.dtype == torch.uint8:
            alpha_patch[mask_t] = torch.maximum(
                alpha_patch[mask_t],
                alpha_patch.new_full(
                    alpha_patch[mask_t].shape,
                    int(round(max(0.0, min(255.0, alpha_value)))),
                    dtype=torch.uint8,
                ),
            )
            return
        dtype_info = torch.iinfo(alpha_patch.dtype)
        alpha_patch[mask_t] = torch.maximum(
            alpha_patch[mask_t],
            alpha_patch.new_full(
                alpha_patch[mask_t].shape,
                int(
                    round(
                        max(
                            float(dtype_info.min),
                            min(float(dtype_info.max), alpha_value),
                        )
                    )
                ),
                dtype=alpha_patch.dtype,
            ),
        )

    def _draw_marker_line_rgba(
        self,
        rgba_patch,
        start_pixel,
        end_pixel,
        color,
        *,
        radius=1,
        alpha=255.0,
        blend=1.0,
    ):
        height, width = rgba_patch.shape[:2]
        start_x = float(start_pixel[0].item())
        start_y = float(start_pixel[1].item())
        end_x = float(end_pixel[0].item())
        end_y = float(end_pixel[1].item())

        min_x = max(0, int(np.floor(min(start_x, end_x) - radius - 1)))
        max_x = min(width, int(np.ceil(max(start_x, end_x) + radius + 2)))
        min_y = max(0, int(np.floor(min(start_y, end_y) - radius - 1)))
        max_y = min(height, int(np.ceil(max(start_y, end_y) + radius + 2)))
        if min_x >= max_x or min_y >= max_y:
            return

        seg_x = end_x - start_x
        seg_y = end_y - start_y
        seg_len_sq = seg_x * seg_x + seg_y * seg_y
        if seg_len_sq < 1e-6:
            ys = torch.arange(min_y, max_y, device=rgba_patch.device, dtype=torch.float32)
            xs = torch.arange(min_x, max_x, device=rgba_patch.device, dtype=torch.float32)
            grid_y, grid_x = torch.meshgrid(ys, xs, indexing="ij")
            point_mask = torch.maximum(
                torch.abs(grid_x - start_x),
                torch.abs(grid_y - start_y),
            ) <= (float(radius) + 0.5)
            self._blend_rgba_patch_masked_inplace(
                rgba_patch[min_y:max_y, min_x:max_x],
                point_mask,
                color,
                alpha=alpha,
                blend=blend,
            )
            return

        ys = torch.arange(min_y, max_y, device=rgba_patch.device, dtype=torch.float32)
        xs = torch.arange(min_x, max_x, device=rgba_patch.device, dtype=torch.float32)
        grid_y, grid_x = torch.meshgrid(ys, xs, indexing="ij")
        rel_x = grid_x - start_x
        rel_y = grid_y - start_y
        t = (rel_x * seg_x + rel_y * seg_y) / seg_len_sq
        t = torch.clamp(t, 0.0, 1.0)
        closest_x = start_x + t * seg_x
        closest_y = start_y + t * seg_y
        dist_x = torch.abs(grid_x - closest_x)
        dist_y = torch.abs(grid_y - closest_y)
        line_mask = torch.maximum(dist_x, dist_y) <= (float(radius) + 0.5)
        self._blend_rgba_patch_masked_inplace(
            rgba_patch[min_y:max_y, min_x:max_x],
            line_mask,
            color,
            alpha=alpha,
            blend=blend,
        )

    def _alpha_composite_rgba_patch_into_frame(
        self,
        frame,
        overlay_color_rgba,
        x0,
        y0,
        *,
        coverage_mask=None,
    ):
        if frame is None or overlay_color_rgba is None or overlay_color_rgba.numel() == 0:
            return
        x0 = int(x0)
        y0 = int(y0)
        height, width = frame.shape[:2]
        patch_h = int(overlay_color_rgba.shape[0])
        patch_w = int(overlay_color_rgba.shape[1])
        if patch_h <= 0 or patch_w <= 0:
            return
        x1 = min(width, x0 + patch_w)
        y1 = min(height, y0 + patch_h)
        if x0 >= x1 or y0 >= y1:
            return
        overlay_patch = overlay_color_rgba[: y1 - y0, : x1 - x0]
        alpha = overlay_patch[..., 3:4].to(torch.float32).clamp(0.0, 255.0) / 255.0
        if coverage_mask is not None:
            coverage_t = coverage_mask[: y1 - y0, : x1 - x0].to(
                device=frame.device,
                dtype=torch.float32,
            )
            alpha = alpha * coverage_t.unsqueeze(-1)
        if not bool((alpha > 0.0).any().item()):
            return
        frame_rgb = frame[y0:y1, x0:x1, :3]
        overlay_rgb = overlay_patch[..., :3].to(torch.float32)
        blended = frame_rgb.to(torch.float32).mul(1.0 - alpha).add(overlay_rgb * alpha)
        if torch.is_floating_point(frame_rgb):
            frame_rgb.copy_(blended.to(frame_rgb.dtype))
            return
        if frame_rgb.dtype == torch.uint8:
            frame_rgb.copy_(blended.round().clamp(0.0, 255.0).to(torch.uint8))
            return
        dtype_info = torch.iinfo(frame_rgb.dtype)
        frame_rgb.copy_(
            blended.round()
            .clamp(float(dtype_info.min), float(dtype_info.max))
            .to(frame_rgb.dtype)
        )

    def _render_rope_game_supersampled_outline_roi(
        self,
        frame,
        quad_pixels,
        color,
    ):
        if frame is None or quad_pixels is None:
            return None
        quad_pixels_t = torch.as_tensor(
            quad_pixels,
            dtype=torch.float32,
            device=frame.device,
        )
        if quad_pixels_t.ndim != 2 or quad_pixels_t.shape != (4, 2):
            return None
        height, width = frame.shape[:2]
        padding = int(
            max(
                self.ROPE_GAME_OUTLINE_ROI_PADDING_PX,
                self.ROPE_GAME_PAD_OUTLINE_RADIUS + 2,
            )
        )
        x0 = max(0, int(torch.floor(quad_pixels_t[:, 0].min()).item()) - padding)
        x1 = min(width, int(torch.ceil(quad_pixels_t[:, 0].max()).item()) + padding + 1)
        y0 = max(0, int(torch.floor(quad_pixels_t[:, 1].min()).item()) - padding)
        y1 = min(height, int(torch.ceil(quad_pixels_t[:, 1].max()).item()) + padding + 1)
        if x0 >= x1 or y0 >= y1:
            return None

        target_w = int(x1 - x0)
        target_h = int(y1 - y0)
        supersample_scale = int(max(1, self.ROPE_GAME_OUTLINE_SUPERSAMPLE_SCALE))
        sup_w = int(target_w * supersample_scale)
        sup_h = int(target_h * supersample_scale)
        overlay_color_rgba = torch.zeros(
            (sup_h, sup_w, 4),
            dtype=torch.float32,
            device=frame.device,
        )
        overlay_depth = torch.zeros(
            (sup_h, sup_w),
            dtype=torch.float32,
            device=frame.device,
        )

        local_quad_pixels = (
            quad_pixels_t
            - quad_pixels_t.new_tensor([float(x0), float(y0)])
        ) * float(supersample_scale)
        line_radius = max(
            1,
            int(round(float(self.ROPE_GAME_PAD_OUTLINE_RADIUS) * float(supersample_scale))),
        )
        for start_idx in range(4):
            end_idx = (start_idx + 1) % 4
            self._draw_marker_line_rgba(
                overlay_color_rgba,
                local_quad_pixels[start_idx],
                local_quad_pixels[end_idx],
                color,
                radius=line_radius,
                alpha=255.0,
                blend=1.0,
            )
        overlay_coverage = overlay_color_rgba[..., 3] >= 1.0
        if not bool(overlay_coverage.any().item()):
            return None
        overlay_depth[overlay_coverage] = 1.0
        color_down, _, coverage_down = self._downsample_immersive_supersampled_overlay_patch(
            overlay_color_rgba,
            overlay_depth,
            target_h,
            target_w,
        )
        return {
            "x0": int(x0),
            "y0": int(y0),
            "color_rgba": color_down,
            "coverage_mask": coverage_down,
        }

    def _get_rope_game_pad_texture_cache(self):
        cache = getattr(self, "_rope_game_pad_texture_cache_data", None)
        if cache is None:
            cache = {}
            self._rope_game_pad_texture_cache_data = cache
        return cache

    def _build_rope_game_pad_texture_rgba(self, color):
        color_rgb = tuple(
            int(np.clip(round(float(channel)), 0, 255))
            for channel in list(color[:3])
        )
        cache = self._get_rope_game_pad_texture_cache()
        cached = cache.get(color_rgb)
        if cached is not None:
            return cached

        size_px = int(max(32, self.ROPE_GAME_PAD_TEXTURE_SIZE_PX))
        margin_px = int(max(2, self.ROPE_GAME_PAD_TEXTURE_MARGIN_PX))
        thickness_px = int(max(1, self.ROPE_GAME_PAD_TEXTURE_THICKNESS_PX))
        alpha_value = int(
            np.clip(
                round(float(self.ROPE_GAME_PAD_OUTLINE_BLEND) * 255.0),
                0,
                255,
            )
        )

        texture_bgra = np.zeros((size_px, size_px, 4), dtype=np.uint8)
        border_max = max(margin_px, size_px - margin_px - 1)
        top_left = (margin_px, margin_px)
        bottom_right = (border_max, border_max)
        draw_color = (
            int(color_rgb[2]),
            int(color_rgb[1]),
            int(color_rgb[0]),
            alpha_value,
        )
        cv2.rectangle(
            texture_bgra,
            top_left,
            bottom_right,
            draw_color,
            thickness=thickness_px,
            lineType=cv2.LINE_AA,
        )
        texture_rgba = cv2.cvtColor(texture_bgra, cv2.COLOR_BGRA2RGBA)
        texture_entry = {
            "texture_rgba": texture_rgba,
            "width_px": int(size_px),
            "height_px": int(size_px),
            "aspect_ratio": 1.0,
        }
        if len(cache) >= 8:
            cache.clear()
        cache[color_rgb] = texture_entry
        return texture_entry

    def _render_rope_game_outline_quad_roi(
        self,
        frame,
        quad_pixels,
        color,
        *,
        padding=4,
        max_projected_span_ratio=None,
    ):
        if frame is None or quad_pixels is None:
            return None
        quad_pixels_np = np.asarray(quad_pixels, dtype=np.float32)
        if quad_pixels_np.shape != (4, 2) or not np.all(np.isfinite(quad_pixels_np)):
            return None

        quad_area = float(abs(cv2.contourArea(quad_pixels_np.reshape(-1, 1, 2))))
        if quad_area < 4.0:
            return None

        height, width = frame.shape[:2]
        if max_projected_span_ratio is not None:
            max_projected_span_ratio = float(max_projected_span_ratio)
            raw_span_x = float(np.max(quad_pixels_np[:, 0]) - np.min(quad_pixels_np[:, 0]))
            raw_span_y = float(np.max(quad_pixels_np[:, 1]) - np.min(quad_pixels_np[:, 1]))
            if (
                raw_span_x > (float(width) * max_projected_span_ratio)
                or raw_span_y > (float(height) * max_projected_span_ratio)
            ):
                return None

        x0 = max(0, int(np.floor(np.min(quad_pixels_np[:, 0])) - int(padding)))
        x1 = min(width, int(np.ceil(np.max(quad_pixels_np[:, 0])) + int(padding) + 1))
        y0 = max(0, int(np.floor(np.min(quad_pixels_np[:, 1])) - int(padding)))
        y1 = min(height, int(np.ceil(np.max(quad_pixels_np[:, 1])) + int(padding) + 1))
        if x0 >= x1 or y0 >= y1:
            return None

        target_w = int(x1 - x0)
        target_h = int(y1 - y0)
        longest_edge = float(max(target_w, target_h))
        if longest_edge <= 0.0:
            return None

        if longest_edge <= 256.0:
            desired_scale = float(self.ROPE_GAME_OUTLINE_SUPERSAMPLE_MAX_SCALE)
        else:
            desired_scale = float(self.ROPE_GAME_OUTLINE_SUPERSAMPLE_SCALE)
        min_scale = float(self.ROPE_GAME_OUTLINE_SUPERSAMPLE_MIN_SCALE)
        max_edge_scale = float(self.ROPE_GAME_OUTLINE_SUPERSAMPLE_MAX_EDGE_PX) / longest_edge
        supersample_scale = min(desired_scale, max_edge_scale)
        if max_edge_scale >= min_scale:
            supersample_scale = max(supersample_scale, min_scale)
        supersample_scale = max(1.0, supersample_scale)

        sup_w = max(1, int(round(float(target_w) * supersample_scale)))
        sup_h = max(1, int(round(float(target_h) * supersample_scale)))
        outline_bgra = np.zeros((sup_h, sup_w, 4), dtype=np.uint8)
        local_quad = (
            quad_pixels_np - np.array([float(x0), float(y0)], dtype=np.float32)
        ) * supersample_scale

        final_line_width_px = max(1, int(2 * int(self.ROPE_GAME_PAD_OUTLINE_RADIUS) - 1))
        supersampled_thickness = max(
            1,
            int(round(float(final_line_width_px) * supersample_scale)),
        )
        alpha_value = int(
            np.clip(
                round(float(self.ROPE_GAME_PAD_OUTLINE_BLEND) * 255.0),
                0,
                255,
            )
        )
        color_bgra = (
            int(np.clip(round(float(color[2])), 0, 255)),
            int(np.clip(round(float(color[1])), 0, 255)),
            int(np.clip(round(float(color[0])), 0, 255)),
            alpha_value,
        )
        fixed_point_shift = 8
        local_quad_fixed = np.round(
            local_quad * float(1 << fixed_point_shift)
        ).astype(np.int32)
        cv2.polylines(
            outline_bgra,
            [local_quad_fixed.reshape(-1, 1, 2)],
            isClosed=True,
            color=color_bgra,
            thickness=supersampled_thickness,
            lineType=cv2.LINE_AA,
            shift=fixed_point_shift,
        )
        if not np.any(outline_bgra[..., 3] > 0):
            return None

        outline_bgra_down = cv2.resize(
            outline_bgra,
            (target_w, target_h),
            interpolation=cv2.INTER_AREA,
        )
        if outline_bgra_down.size == 0 or not np.any(outline_bgra_down[..., 3] > 0):
            return None
        outline_rgba_down = cv2.cvtColor(outline_bgra_down, cv2.COLOR_BGRA2RGBA)
        return {
            "x0": int(x0),
            "y0": int(y0),
            "color_rgba": torch.from_numpy(outline_rgba_down).to(
                device=frame.device,
                dtype=torch.float32,
            ),
            "coverage_mask": torch.from_numpy(outline_rgba_down[..., 3] > 0).to(
                device=frame.device,
            ),
        }

    def _get_rope_game_finish_modal_texture_cache(self):
        cache = getattr(self, "_rope_game_finish_modal_texture_cache_data", None)
        if cache is None:
            cache = {}
            self._rope_game_finish_modal_texture_cache_data = cache
        return cache

    def _build_rope_game_finish_modal_texture_rgba(
        self,
        finish_modal_lines,
    ):
        if not finish_modal_lines:
            return None
        finish_modal_key = tuple(str(line) for line in finish_modal_lines)
        cache = self._get_rope_game_finish_modal_texture_cache()
        cached = cache.get(finish_modal_key)
        if cached is not None:
            return cached

        scale_multiplier = float(self.ROPE_GAME_FINISH_MODAL_TEXTURE_SCALE_MULTIPLIER)
        body_scale = float(
            np.clip(
                float(self.ROPE_GAME_FINISH_MODAL_SCALE) * scale_multiplier,
                float(self.ROPE_GAME_FINISH_MODAL_MIN_SCALE) * scale_multiplier,
                float(self.ROPE_GAME_FINISH_MODAL_MAX_SCALE) * scale_multiplier,
            )
        )
        title_scale = body_scale * float(
            self.ROPE_GAME_FINISH_MODAL_TITLE_SCALE_MULTIPLIER
        )
        font_face = cv2.FONT_HERSHEY_DUPLEX
        body_thickness = 2 if body_scale < 1.6 else 3
        title_thickness = max(2, body_thickness)
        line_gap = max(16, int(round(18.0 * body_scale)))
        pad_x = max(28, int(round(28.0 * body_scale)))
        pad_y = max(22, int(round(22.0 * body_scale)))
        shadow_offset = max(2, int(round(2.0 * body_scale)))

        line_specs = []
        for line_idx, line in enumerate(finish_modal_lines):
            line_scale = title_scale if line_idx == 0 else body_scale
            line_thickness = title_thickness if line_idx == 0 else body_thickness
            (text_w, text_h), baseline = cv2.getTextSize(
                str(line),
                font_face,
                line_scale,
                line_thickness,
            )
            line_specs.append(
                {
                    "text": str(line),
                    "scale": float(line_scale),
                    "thickness": int(line_thickness),
                    "text_w": int(text_w),
                    "text_h": int(text_h),
                    "baseline": int(baseline),
                }
            )
        if not line_specs:
            return None

        content_width = max(spec["text_w"] for spec in line_specs)
        content_height = sum(
            spec["text_h"] + spec["baseline"] for spec in line_specs
        ) + max(0, len(line_specs) - 1) * line_gap
        box_width = int(content_width + 2 * pad_x)
        box_height = int(content_height + 2 * pad_y)
        if box_width <= 0 or box_height <= 0:
            return None

        modal_patch = np.zeros((box_height, box_width, 4), dtype=np.uint8)
        bg_alpha = int(
            np.clip(round(float(self.ROPE_GAME_FINISH_MODAL_BG_BLEND) * 255.0), 0, 255)
        )
        text_alpha = int(
            np.clip(
                round(float(self.ROPE_GAME_FINISH_MODAL_TEXT_BLEND) * 255.0),
                0,
                255,
            )
        )
        shadow_alpha = int(
            np.clip(
                round(float(self.ROPE_GAME_FINISH_MODAL_SHADOW_BLEND) * 255.0),
                0,
                255,
            )
        )
        modal_patch[..., 3] = bg_alpha

        cursor_y = int(pad_y)
        for spec in line_specs:
            text_x = max(0, (box_width - spec["text_w"]) // 2)
            baseline_y = int(cursor_y + spec["text_h"])
            if shadow_alpha > 0:
                cv2.putText(
                    modal_patch,
                    spec["text"],
                    (text_x + shadow_offset, baseline_y + shadow_offset),
                    font_face,
                    spec["scale"],
                    (0, 0, 0, shadow_alpha),
                    max(2, spec["thickness"] + 1),
                    lineType=cv2.LINE_AA,
                )
            cv2.putText(
                modal_patch,
                spec["text"],
                (text_x, baseline_y),
                font_face,
                spec["scale"],
                (255, 255, 255, text_alpha),
                spec["thickness"],
                lineType=cv2.LINE_AA,
            )
            cursor_y += spec["text_h"] + spec["baseline"] + line_gap

        texture_entry = {
            "texture_rgba": modal_patch,
            "width_px": int(box_width),
            "height_px": int(box_height),
            "aspect_ratio": float(box_height) / max(float(box_width), 1.0),
        }
        if len(cache) >= 8:
            cache.clear()
        cache[finish_modal_key] = texture_entry
        return texture_entry

    def _render_rope_game_textured_quad_roi(
        self,
        frame,
        texture_entry,
        quad_pixels,
        *,
        padding=4,
        max_projected_span_ratio=None,
    ):
        if frame is None or texture_entry is None or quad_pixels is None:
            return None
        texture_rgba = texture_entry.get("texture_rgba")
        if texture_rgba is None or int(texture_rgba.size) == 0:
            return None
        quad_pixels_np = np.asarray(quad_pixels, dtype=np.float32)
        if quad_pixels_np.shape != (4, 2) or not np.all(np.isfinite(quad_pixels_np)):
            return None

        quad_area = float(abs(cv2.contourArea(quad_pixels_np.reshape(-1, 1, 2))))
        if quad_area < 4.0:
            return None

        height, width = frame.shape[:2]
        if max_projected_span_ratio is not None:
            max_projected_span_ratio = float(max_projected_span_ratio)
            raw_span_x = float(np.max(quad_pixels_np[:, 0]) - np.min(quad_pixels_np[:, 0]))
            raw_span_y = float(np.max(quad_pixels_np[:, 1]) - np.min(quad_pixels_np[:, 1]))
            if (
                raw_span_x > (float(width) * max_projected_span_ratio)
                or raw_span_y > (float(height) * max_projected_span_ratio)
            ):
                return None

        x0 = max(0, int(np.floor(np.min(quad_pixels_np[:, 0])) - int(padding)))
        x1 = min(width, int(np.ceil(np.max(quad_pixels_np[:, 0])) + int(padding) + 1))
        y0 = max(0, int(np.floor(np.min(quad_pixels_np[:, 1])) - int(padding)))
        y1 = min(height, int(np.ceil(np.max(quad_pixels_np[:, 1])) + int(padding) + 1))
        if x0 >= x1 or y0 >= y1:
            return None

        local_quad = quad_pixels_np - np.array([float(x0), float(y0)], dtype=np.float32)
        tex_h, tex_w = texture_rgba.shape[:2]
        src_quad = np.array(
            [
                [0.0, 0.0],
                [float(tex_w - 1), 0.0],
                [float(tex_w - 1), float(tex_h - 1)],
                [0.0, float(tex_h - 1)],
            ],
            dtype=np.float32,
        )
        warp_matrix = cv2.getPerspectiveTransform(src_quad, local_quad.astype(np.float32))
        warped_rgba = cv2.warpPerspective(
            texture_rgba,
            warp_matrix,
            (int(x1 - x0), int(y1 - y0)),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_CONSTANT,
            borderValue=(0, 0, 0, 0),
        )
        if warped_rgba.size == 0 or not np.any(warped_rgba[..., 3] > 0):
            return None

        return {
            "x0": int(x0),
            "y0": int(y0),
            "color_rgba": torch.from_numpy(warped_rgba).to(
                device=frame.device,
                dtype=torch.float32,
            ),
            "coverage_mask": torch.from_numpy(warped_rgba[..., 3] > 0).to(
                device=frame.device,
            ),
        }

    def _make_rope_game_finish_modal_world_corners(
        self,
        finish_modal_lines,
        *,
        left_eye_pose_world,
        right_eye_pose_world,
        left_intrinsic,
        right_intrinsic,
    ):
        if not finish_modal_lines:
            return None
        if left_eye_pose_world is None and right_eye_pose_world is None:
            return None
        texture_entry = self._build_rope_game_finish_modal_texture_rgba(
            finish_modal_lines
        )
        if texture_entry is None:
            return None
        try:
            center_eye_pose_world, _ = self._build_immersive_center_scene_view(
                left_eye_pose_world,
                right_eye_pose_world,
                left_intrinsic,
                right_intrinsic,
            )
        except ValueError:
            return None

        card_width = float(self.ROPE_GAME_FINISH_MODAL_WORLD_WIDTH_M)
        card_height = min(
            card_width * float(texture_entry["aspect_ratio"]),
            float(self.ROPE_GAME_FINISH_MODAL_WORLD_MAX_HEIGHT_M),
        )
        if card_width <= 0.0 or card_height <= 0.0:
            return None

        card_center = (
            np.asarray(center_eye_pose_world[:3, 3], dtype=np.float32)
            + self._eye_forward_world(center_eye_pose_world).astype(np.float32)
            * float(self.ROPE_GAME_FINISH_MODAL_WORLD_DEPTH_M)
        )
        right_world = np.asarray(center_eye_pose_world[:3, 0], dtype=np.float32)
        up_world = np.asarray(center_eye_pose_world[:3, 1], dtype=np.float32)
        half_width = 0.5 * card_width
        half_height = 0.5 * card_height
        return np.stack(
            [
                card_center - right_world * half_width + up_world * half_height,
                card_center + right_world * half_width + up_world * half_height,
                card_center + right_world * half_width - up_world * half_height,
                card_center - right_world * half_width - up_world * half_height,
            ],
            axis=0,
        ).astype(np.float32)

    def _render_rope_game_finish_modal_quad_roi(
        self,
        frame,
        texture_entry,
        quad_pixels,
    ):
        return self._render_rope_game_textured_quad_roi(
            frame,
            texture_entry,
            quad_pixels,
            padding=4,
        )

    def _draw_rope_game_overlay(self, frame, rope_game_overlay_state, eye_render_state):
        if frame is None or rope_game_overlay_state is None or eye_render_state is None:
            return
        state_name = str(rope_game_overlay_state.get("state", "")).strip().lower()
        quad_world = rope_game_overlay_state.get("pad_corners_world")
        if quad_world is not None:
            quad_pixels, depth_valid = self._project_points_to_pixels(
                torch.as_tensor(
                    quad_world,
                    dtype=torch.float32,
                    device=frame.device,
                ),
                eye_render_state.get("intrinsic_t"),
                eye_render_state.get("w2c_cv_t"),
            )
            if bool(depth_valid.all().item()):
                pad_color = rope_game_overlay_state.get(
                    "pad_color",
                    self.ROPE_GAME_PAD_ACTIVE_COLOR,
                )
                overlay_roi = self._render_rope_game_outline_quad_roi(
                    frame,
                    quad_pixels.detach().cpu().numpy(),
                    pad_color,
                    padding=self.ROPE_GAME_OUTLINE_ROI_PADDING_PX,
                    max_projected_span_ratio=self.ROPE_GAME_PAD_MAX_PROJECTED_SPAN_RATIO,
                )
                if overlay_roi is not None:
                    self._alpha_composite_rgba_patch_into_frame(
                        frame,
                        overlay_roi["color_rgba"],
                        overlay_roi["x0"],
                        overlay_roi["y0"],
                        coverage_mask=overlay_roi.get("coverage_mask"),
                    )
        finish_modal_lines = rope_game_overlay_state.get("finish_modal_lines") or []
        finish_modal_world_corners = rope_game_overlay_state.get(
            "finish_modal_world_corners"
        )
        if (
            state_name == "course_finished"
            and finish_modal_lines
            and finish_modal_world_corners is not None
        ):
            quad_pixels, depth_valid = self._project_points_to_pixels(
                torch.as_tensor(
                    finish_modal_world_corners,
                    dtype=torch.float32,
                    device=frame.device,
                ),
                eye_render_state.get("intrinsic_t"),
                eye_render_state.get("w2c_cv_t"),
            )
            if bool(depth_valid.all().item()):
                texture_entry = self._build_rope_game_finish_modal_texture_rgba(
                    finish_modal_lines
                )
                finish_modal = self._render_rope_game_finish_modal_quad_roi(
                    frame,
                    texture_entry,
                    quad_pixels.detach().cpu().numpy(),
                )
                if finish_modal is not None:
                    self._alpha_composite_rgba_patch_into_frame(
                        frame,
                        finish_modal["color_rgba"],
                        finish_modal["x0"],
                        finish_modal["y0"],
                        coverage_mask=finish_modal.get("coverage_mask"),
                    )

    def _mirror_symbol_about_palm(self, projected):
        mirrored = {"palm": projected["palm"]}
        palm = projected["palm"]
        for key in ("thumb_tip", "index_tip", "middle_tip", "pinch_point"):
            point = projected.get(key)
            if point is None:
                mirrored[key] = None
            else:
                mirrored[key] = palm - (point - palm)
        return mirrored

    def _resolve_live_hand_overlay_colors(self, hand_overlays, width, side_memory):
        if not hand_overlays:
            return hand_overlays

        if len(hand_overlays) >= 2:
            ordered = sorted(hand_overlays, key=lambda entry: float(entry["palm_pixel"][0].item()))
            left_entry = ordered[0]
            right_entry = ordered[-1]
            left_entry["color"] = self.LIVE_HAND_LEFT_COLOR
            right_entry["color"] = self.LIVE_HAND_RIGHT_COLOR
            if side_memory[left_entry["source"]] is None:
                side_memory[left_entry["source"]] = "left"
            if side_memory[right_entry["source"]] is None:
                side_memory[right_entry["source"]] = "right"
            return hand_overlays

        entry = hand_overlays[0]
        remembered_side = side_memory[entry["source"]]
        if remembered_side is None:
            remembered_side = (
                "left"
                if float(entry["palm_pixel"][0].item()) < (0.5 * float(width))
                else "right"
            )
            side_memory[entry["source"]] = remembered_side

        entry["color"] = (
            self.LIVE_HAND_LEFT_COLOR
            if remembered_side == "left"
            else self.LIVE_HAND_RIGHT_COLOR
        )
        return hand_overlays

    def _draw_live_hand_overlay(self, frame, hand_overlays):
        for overlay in hand_overlays:
            color = overlay["color"]
            projected = self._mirror_symbol_about_palm(overlay["projected"])
            palm = projected["palm"]
            thumb_tip = projected.get("thumb_tip")
            index_tip = projected.get("index_tip")
            middle_tip = projected.get("middle_tip")
            pinch_point = projected.get("pinch_point")

            palm_axis = pinch_point
            if palm_axis is None:
                palm_axis = index_tip if index_tip is not None else thumb_tip

            self._blend_ellipse(
                frame,
                palm,
                color,
                radius_x=self.LIVE_HAND_PALM_RADIUS_X,
                radius_y=self.LIVE_HAND_PALM_RADIUS_Y,
                axis_pixel=palm_axis,
                blend=0.42,
            )

            for branch_tip, branch_blend in (
                (thumb_tip, 0.35),
                (index_tip, 0.42),
                (middle_tip, 0.24),
            ):
                if branch_tip is None:
                    continue
                self._draw_marker_line(
                    frame,
                    palm,
                    branch_tip,
                    color,
                    radius=self.LIVE_HAND_LINE_RADIUS,
                    blend=branch_blend,
                )

            if thumb_tip is not None:
                self._blend_marker(
                    frame,
                    thumb_tip,
                    color,
                    radius=self.LIVE_HAND_TIP_RADIUS,
                    blend=0.78,
                )
            if index_tip is not None:
                self._blend_marker(
                    frame,
                    index_tip,
                    color,
                    radius=self.LIVE_HAND_TIP_RADIUS,
                    blend=0.82,
                )
            if middle_tip is not None:
                self._blend_marker(
                    frame,
                    middle_tip,
                    color,
                    radius=1,
                    blend=0.55,
                )
            if pinch_point is not None:
                self._blend_marker(
                    frame,
                    pinch_point,
                    color,
                    radius=self.LIVE_HAND_PINCH_RADIUS,
                    blend=0.90,
                )
                self._blend_marker(frame, pinch_point, [255.0, 255.0, 255.0], radius=1, blend=0.95)

    def _controller_sample_has_position(self, controller_sample, pose_role="selected"):
        return controller_pose_position(controller_sample, pose_role) is not None

    def _controller_sample_is_renderable(self, controller_sample, pose_role="selected"):
        return (
            self._controller_sample_has_position(controller_sample, pose_role)
            and controller_pose_forward(controller_sample, pose_role) is not None
        )

    def _controller_world_ray_pose(self, controller_world):
        if controller_world is None:
            return None, None
        origin_world = controller_world.get("ray_origin", controller_world.get("position"))
        direction_world = controller_world.get("ray_direction", controller_world.get("direction"))
        if origin_world is None or direction_world is None:
            return origin_world, direction_world
        norm = torch.linalg.norm(direction_world)
        if float(norm.item()) < 1e-6:
            return origin_world, None
        return origin_world, direction_world / norm

    def _controller_camera_basis(self, w2c):
        if torch.is_tensor(w2c):
            w2c_np = w2c.detach().cpu().numpy()
        else:
            w2c_np = np.asarray(w2c, dtype=np.float32)

        camera_to_world = w2c_np[:3, :3].T
        screen_right_world = camera_to_world[:, 0]
        screen_up_world = -camera_to_world[:, 1]
        scene_forward_world = -camera_to_world[:, 2]
        basis = np.stack(
            [screen_right_world, screen_up_world, scene_forward_world],
            axis=1,
        ).astype(np.float32)
        return torch.as_tensor(basis, dtype=torch.float32, device=cfg.device)

    def _scene_world_up_vector_np(self):
        return np.array(
            [0.0, 0.0, -1.0 if cfg.reverse_z else 1.0],
            dtype=np.float32,
        )

    def _scene_world_up_vector_torch(self, device=None, dtype=torch.float32):
        if device is None:
            device = cfg.device
        return torch.as_tensor(
            self._scene_world_up_vector_np(),
            dtype=dtype,
            device=device,
        )

    def _scene_world_forward_vector_np(self):
        return np.array([0.0, 1.0, 0.0], dtype=np.float32)

    def _normalize_numpy_vector(self, vector, fallback):
        vector = np.asarray(vector, dtype=np.float32)
        norm = float(np.linalg.norm(vector))
        if norm < 1e-6:
            return np.asarray(fallback, dtype=np.float32).copy()
        return vector / norm

    def _normalize_torch_vector(self, vector, fallback):
        vector = torch.as_tensor(vector, dtype=torch.float32, device=cfg.device)
        fallback = torch.as_tensor(fallback, dtype=vector.dtype, device=vector.device)
        norm = torch.linalg.norm(vector)
        if float(norm.item()) < 1e-6:
            return fallback.clone()
        return vector / norm

    def _axis_angle_rotation_matrix_torch(self, axis, angle, device=None, dtype=torch.float32):
        if device is None:
            device = cfg.device
        axis = torch.as_tensor(axis, dtype=dtype, device=device)
        axis = axis / torch.linalg.norm(axis).clamp_min(1e-6)
        angle = torch.as_tensor(angle, dtype=dtype, device=device)
        x, y, z = axis.unbind()
        c = torch.cos(angle)
        s = torch.sin(angle)
        one_c = 1.0 - c
        return torch.stack(
            [
                torch.stack([c + x * x * one_c, x * y * one_c - z * s, x * z * one_c + y * s]),
                torch.stack([y * x * one_c + z * s, c + y * y * one_c, y * z * one_c - x * s]),
                torch.stack([z * x * one_c - y * s, z * y * one_c + x * s, c + z * z * one_c]),
            ],
            dim=0,
        )

    def _rotate_points_with_matrix(self, points, rotation_matrix, pivot=None):
        points = torch.as_tensor(points, dtype=rotation_matrix.dtype, device=rotation_matrix.device)
        if pivot is None:
            pivot = torch.zeros(3, dtype=rotation_matrix.dtype, device=rotation_matrix.device)
        else:
            pivot = torch.as_tensor(pivot, dtype=rotation_matrix.dtype, device=rotation_matrix.device)
        return (points - pivot.unsqueeze(0)) @ rotation_matrix.T + pivot.unsqueeze(0)

    def _gaussian_quaternion_multiply_wxyz(self, lhs, rhs):
        lhs = torch.as_tensor(lhs, dtype=torch.float32, device=cfg.device)
        rhs = torch.as_tensor(rhs, dtype=torch.float32, device=cfg.device)
        lhs_shape = lhs.shape
        rhs_shape = rhs.shape
        lhs = lhs.reshape(-1, 4)
        rhs = rhs.reshape(-1, 4)
        if lhs.shape[0] == 1 and rhs.shape[0] > 1:
            lhs = lhs.expand(rhs.shape[0], 4)
        if rhs.shape[0] == 1 and lhs.shape[0] > 1:
            rhs = rhs.expand(lhs.shape[0], 4)
        w1, x1, y1, z1 = lhs.unbind(dim=1)
        w2, x2, y2, z2 = rhs.unbind(dim=1)
        product = torch.stack(
            [
                w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2,
                w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2,
                w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2,
                w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2,
            ],
            dim=1,
        )
        if len(lhs_shape) == 1 and len(rhs_shape) == 1:
            return product[0]
        return product

    def _axis_angle_to_gaussian_quaternion_wxyz(self, axis, angle, device=None, dtype=torch.float32):
        if device is None:
            device = cfg.device
        axis = torch.as_tensor(axis, dtype=dtype, device=device)
        axis = axis / torch.linalg.norm(axis).clamp_min(1e-6)
        half_angle = 0.5 * torch.as_tensor(angle, dtype=dtype, device=device)
        sin_half = torch.sin(half_angle)
        return torch.stack(
            [
                torch.cos(half_angle),
                axis[0] * sin_half,
                axis[1] * sin_half,
                axis[2] * sin_half,
            ],
            dim=0,
        )

    def _rotate_gaussian_quaternions_about_axis(self, quaternions, axis, angle):
        quaternions = torch.as_tensor(quaternions, dtype=torch.float32, device=cfg.device)
        rotation_quaternion = self._axis_angle_to_gaussian_quaternion_wxyz(
            axis,
            angle,
            device=quaternions.device,
            dtype=quaternions.dtype,
        )
        rotated = self._gaussian_quaternion_multiply_wxyz(
            rotation_quaternion.unsqueeze(0),
            quaternions,
        )
        return F.normalize(rotated, dim=-1)

    def _is_finite_tensor(self, tensor):
        return bool(torch.isfinite(torch.as_tensor(tensor)).all().item())

    def _compute_live_controller_alignment(
        self,
        live_left_anchor,
        live_right_anchor,
        recorded_left_anchor,
        recorded_right_anchor,
        w2c,
        basis_override=None,
    ):
        live_left_anchor = torch.as_tensor(
            np.asarray(live_left_anchor, dtype=np.float32),
            dtype=torch.float32,
            device=cfg.device,
        )
        live_right_anchor = torch.as_tensor(
            np.asarray(live_right_anchor, dtype=np.float32),
            dtype=torch.float32,
            device=cfg.device,
        )
        recorded_left_anchor = torch.as_tensor(
            recorded_left_anchor,
            dtype=torch.float32,
            device=cfg.device,
        )
        recorded_right_anchor = torch.as_tensor(
            recorded_right_anchor,
            dtype=torch.float32,
            device=cfg.device,
        )
        basis = (
            basis_override
            if basis_override is not None
            else self._controller_camera_basis(w2c)
        )
        return {
            "basis": basis,
            "translation_scale": torch.tensor(
                self._live_controller_case_profile()["controller_translation_scale"],
                dtype=torch.float32,
                device=cfg.device,
            ),
            "reference_live_left": live_left_anchor,
            "reference_live_right": live_right_anchor,
            "reference_scene_left": recorded_left_anchor,
            "reference_scene_right": recorded_right_anchor,
        }

    def _compute_single_controller_alignment(
        self,
        live_anchor,
        recorded_anchor,
        w2c,
        basis_override=None,
    ):
        live_anchor = torch.as_tensor(
            np.asarray(live_anchor, dtype=np.float32),
            dtype=torch.float32,
            device=cfg.device,
        )
        recorded_anchor = torch.as_tensor(
            recorded_anchor,
            dtype=torch.float32,
            device=cfg.device,
        )
        basis = (
            basis_override
            if basis_override is not None
            else self._controller_camera_basis(w2c)
        )
        return {
            "basis": basis,
            "translation_scale": torch.tensor(
                self._live_controller_case_profile()["controller_translation_scale"],
                dtype=torch.float32,
                device=cfg.device,
            ),
            "reference_live_left": live_anchor,
            "reference_live_right": live_anchor,
            "reference_scene_left": recorded_anchor,
            "reference_scene_right": recorded_anchor,
        }

    def _update_live_controller_alignment(
        self,
        alignment,
        alignment_mode,
        live_sample,
        recorded_anchor_centers,
        w2c,
        basis_override=None,
        pose_role="selected",
    ):
        left_anchor = controller_pose_position(live_sample.left, pose_role)
        right_anchor = controller_pose_position(live_sample.right, pose_role)

        if left_anchor is not None and right_anchor is not None:
            if alignment_mode != "dual":
                alignment = self._compute_live_controller_alignment(
                    left_anchor,
                    right_anchor,
                    recorded_anchor_centers[0],
                    recorded_anchor_centers[1],
                    w2c,
                    basis_override=basis_override,
                )
                alignment_mode = "dual"
            return alignment, alignment_mode

        if left_anchor is not None:
            if alignment_mode != "single_left":
                alignment = self._compute_single_controller_alignment(
                    left_anchor,
                    recorded_anchor_centers[0],
                    w2c,
                    basis_override=basis_override,
                )
                alignment_mode = "single_left"
            return alignment, alignment_mode

        if right_anchor is not None:
            if alignment_mode != "single_right":
                alignment = self._compute_single_controller_alignment(
                    right_anchor,
                    recorded_anchor_centers[1],
                    w2c,
                    basis_override=basis_override,
                )
                alignment_mode = "single_right"
            return alignment, alignment_mode

        return alignment, alignment_mode

    def _transform_live_controller_delta(self, delta, alignment):
        transformed = alignment["basis"] @ delta
        return transformed * alignment["translation_scale"]

    def _transform_live_controller_direction(self, direction, alignment):
        transformed = alignment["basis"] @ direction
        norm = torch.linalg.norm(transformed)
        if float(norm.item()) < 1e-6:
            return None
        return transformed / norm

    def _convert_live_controller_to_world(
        self,
        source,
        controller_sample,
        alignment,
        position_pose_role="selected",
        ray_pose_role=None,
    ):
        if alignment is None or controller_sample is None or not controller_sample.active:
            return None

        if ray_pose_role is None:
            ray_pose_role = position_pose_role

        position_np = controller_pose_position(controller_sample, position_pose_role)
        if position_np is None:
            return None

        ray_origin_np = controller_pose_position(controller_sample, ray_pose_role)
        if ray_origin_np is None:
            ray_origin_np = position_np

        direction_np = controller_pose_forward(controller_sample, ray_pose_role)
        if direction_np is None:
            direction_np = controller_pose_forward(controller_sample, position_pose_role)
        if direction_np is None:
            return None

        position = torch.from_numpy(np.asarray(position_np, dtype=np.float32)).to(
            device=cfg.device, dtype=torch.float32
        )
        ray_origin = torch.from_numpy(np.asarray(ray_origin_np, dtype=np.float32)).to(
            device=cfg.device, dtype=torch.float32
        )
        direction = torch.from_numpy(np.asarray(direction_np, dtype=np.float32)).to(
            device=cfg.device, dtype=torch.float32
        )
        if source == "left":
            reference_live = alignment["reference_live_left"]
            reference_scene = alignment["reference_scene_left"]
        else:
            reference_live = alignment["reference_live_right"]
            reference_scene = alignment["reference_scene_right"]
        world_position = reference_scene + self._transform_live_controller_delta(
            position - reference_live,
            alignment,
        )
        world_ray_origin = reference_scene + self._transform_live_controller_delta(
            ray_origin - reference_live,
            alignment,
        )
        world_ray_direction = self._transform_live_controller_direction(direction, alignment)
        if world_ray_direction is None:
            return None

        return {
            "source": controller_sample.source,
            "position": world_position,
            "direction": world_ray_direction,
            "ray_origin": world_ray_origin,
            "ray_direction": world_ray_direction,
            "select_available": controller_sample.select_available,
            "select_pressed": controller_sample.select_pressed,
            "select_value": controller_sample.select_value,
            "select_source": controller_sample.select_source,
            "anchor_cycle_available": controller_sample.anchor_cycle_available,
            "anchor_cycle_pressed": controller_sample.anchor_cycle_pressed,
            "anchor_cycle_source": controller_sample.anchor_cycle_source,
            "anchor_reset_available": getattr(controller_sample, "anchor_reset_available", False),
            "anchor_reset_pressed": getattr(controller_sample, "anchor_reset_pressed", False),
            "anchor_reset_source": getattr(controller_sample, "anchor_reset_source", "none"),
            "snap_assist_available": controller_sample.snap_assist_available,
            "snap_assist_pressed": controller_sample.snap_assist_pressed,
            "snap_assist_source": controller_sample.snap_assist_source,
            "exit_available": getattr(controller_sample, "exit_available", False),
            "exit_pressed": getattr(controller_sample, "exit_pressed", False),
            "exit_source": getattr(controller_sample, "exit_source", "none"),
            "position_pose_role": position_pose_role,
            "ray_pose_role": ray_pose_role,
            "grip_pose_valid": bool(
                controller_sample.grip_active
                and controller_sample.grip_position_valid
                and controller_sample.grip_orientation_valid
            )
            ,
            "aim_pose_valid": bool(
                controller_sample.aim_active
                and controller_sample.aim_position_valid
                and controller_sample.aim_orientation_valid
            )
            ,
        }

    def _quaternion_xyzw_to_rotation_matrix(self, quaternion):
        x, y, z, w = [float(v) for v in quaternion]
        xx = x * x
        yy = y * y
        zz = z * z
        xy = x * y
        xz = x * z
        yz = y * z
        wx = w * x
        wy = w * y
        wz = w * z
        return np.array(
            [
                [1.0 - 2.0 * (yy + zz), 2.0 * (xy - wz), 2.0 * (xz + wy)],
                [2.0 * (xy + wz), 1.0 - 2.0 * (xx + zz), 2.0 * (yz - wx)],
                [2.0 * (xz - wy), 2.0 * (yz + wx), 1.0 - 2.0 * (xx + yy)],
            ],
            dtype=np.float32,
        )

    def _controller_alignment_reference_centers(self, alignment):
        if alignment is None:
            return None, None
        live_center = 0.5 * (
            alignment["reference_live_left"] + alignment["reference_live_right"]
        )
        scene_center = 0.5 * (
            alignment["reference_scene_left"] + alignment["reference_scene_right"]
        )
        return live_center, scene_center

    def _controller_basis_with_lateral_flip(self, basis, lateral_flip=False):
        basis_t = torch.as_tensor(
            basis,
            dtype=torch.float32,
            device=cfg.device,
        ).clone()
        if lateral_flip:
            basis_t[:, 0] = -basis_t[:, 0]
        return basis_t

    def _make_immersive_controller_basis_state(self, head_basis, intrinsic):
        intrinsic_np = (
            intrinsic.detach().cpu().numpy()
            if torch.is_tensor(intrinsic)
            else np.asarray(intrinsic, dtype=np.float32)
        )
        head_basis_t = self._controller_basis_with_lateral_flip(
            head_basis,
            lateral_flip=False,
        )
        return {
            "state": "pending",
            "resolved": False,
            "resolved_from": "none",
            "basis": head_basis_t.clone(),
            "head_basis": head_basis_t,
            "lateral_flip_applied": False,
            "screen_center_x": float(intrinsic_np[0, 2]),
            "validation_mode": "pending",
            "validation_sample_id": None,
            "live_lateral_delta_x": None,
            "single_source_name": None,
            "single_source_live_x": None,
            "single_source_projected_offset_x": None,
            "provisional_left_body_x": None,
            "provisional_right_body_x": None,
            "provisional_left_ray_x": None,
            "provisional_right_ray_x": None,
            "final_left_body_x": None,
            "final_right_body_x": None,
            "final_left_ray_x": None,
            "final_right_ray_x": None,
            "candidate_flip": None,
            "candidate_validation_mode": None,
            "candidate_streak": 0,
            "resolution_start_sample": None,
            "resolution_deadline_sample": None,
            "lock_reason": None,
            "lock_sample_id": None,
            "seen_sources_ever": [],
            "current_stable_sources": [],
            "source_present_counts": {"left": 0, "right": 0},
            "source_absent_counts": {"left": 0, "right": 0},
            "pending_revalidation": False,
            "pending_revalidation_reason": None,
            "late_controller_seen_after_lock": [],
            "locked_active_sources": [],
        }

    def _project_controller_world_field_to_startup_screen_x(
        self,
        controller_world,
        field_name,
        intrinsic,
        w2c,
    ):
        if controller_world is None:
            return None, None, False
        point_world = controller_world.get(field_name)
        if point_world is None:
            return None, None, False
        return self._project_world_point_to_startup_screen_x(
            point_world,
            intrinsic,
            w2c,
        )

    def _compute_live_controller_alignment_from_sample(
        self,
        latest_controller_sample,
        current_alignment,
        current_alignment_mode,
        controller_source_anchor_centers,
        w2c,
        basis_override=None,
        pose_role="selected",
    ):
        if latest_controller_sample is None:
            return current_alignment, current_alignment_mode

        left_anchor = controller_pose_position(latest_controller_sample.left, pose_role)
        right_anchor = controller_pose_position(latest_controller_sample.right, pose_role)
        if left_anchor is not None and right_anchor is not None:
            return (
                self._compute_live_controller_alignment(
                    left_anchor,
                    right_anchor,
                    controller_source_anchor_centers[0],
                    controller_source_anchor_centers[1],
                    w2c,
                    basis_override=basis_override,
                ),
                "dual",
            )
        if left_anchor is not None:
            return (
                self._compute_single_controller_alignment(
                    left_anchor,
                    controller_source_anchor_centers[0],
                    w2c,
                    basis_override=basis_override,
                ),
                "single_left",
            )
        if right_anchor is not None:
            return (
                self._compute_single_controller_alignment(
                    right_anchor,
                    controller_source_anchor_centers[1],
                    w2c,
                    basis_override=basis_override,
                ),
                "single_right",
            )
        return current_alignment, current_alignment_mode

    def _copy_live_controller_runtime_metadata(
        self,
        recomputed_controller_world,
        original_controller_world,
    ):
        if recomputed_controller_world is None or original_controller_world is None:
            return recomputed_controller_world
        for key in (
            "sample_id",
            "select_start_edge",
            "select_hold_active",
            "select_release_ready",
            "select_release_frames",
            "select_start_active",
        ):
            if key in original_controller_world:
                recomputed_controller_world[key] = original_controller_world[key]
        return recomputed_controller_world

    def _recompute_live_controller_runtime_state_for_basis(
        self,
        latest_controller_sample,
        controller_runtime_state,
        controller_source_anchor_centers,
        w2c,
        basis_override,
        alignment_pose_role="selected",
        controller_position_pose_role="selected",
        controller_ray_pose_role=None,
    ):
        if latest_controller_sample is None or controller_runtime_state is None:
            return controller_runtime_state

        recomputed_alignment, recomputed_alignment_mode = (
            self._compute_live_controller_alignment_from_sample(
                latest_controller_sample,
                controller_runtime_state.get("alignment"),
                controller_runtime_state.get("alignment_mode", "unset"),
                controller_source_anchor_centers,
                w2c,
                basis_override=basis_override,
                pose_role=alignment_pose_role,
            )
        )
        recomputed_left_controller = self._convert_live_controller_to_world(
            "left",
            latest_controller_sample.left,
            recomputed_alignment,
            position_pose_role=controller_position_pose_role,
            ray_pose_role=controller_ray_pose_role,
        )
        recomputed_right_controller = self._convert_live_controller_to_world(
            "right",
            latest_controller_sample.right,
            recomputed_alignment,
            position_pose_role=controller_position_pose_role,
            ray_pose_role=controller_ray_pose_role,
        )
        recomputed_left_controller = self._copy_live_controller_runtime_metadata(
            recomputed_left_controller,
            controller_runtime_state.get("left_controller"),
        )
        recomputed_right_controller = self._copy_live_controller_runtime_metadata(
            recomputed_right_controller,
            controller_runtime_state.get("right_controller"),
        )
        recomputed_runtime_state = dict(controller_runtime_state)
        recomputed_runtime_state["alignment"] = recomputed_alignment
        recomputed_runtime_state["alignment_mode"] = recomputed_alignment_mode
        recomputed_runtime_state["left_controller"] = recomputed_left_controller
        recomputed_runtime_state["right_controller"] = recomputed_right_controller
        return recomputed_runtime_state

    def _log_immersive_controller_handedness_resolution(self, controller_basis_state):
        def _fmt(value):
            return "none" if value is None else f"{float(value):.2f}"

        basis_lateral = (
            controller_basis_state["basis"][:, 0]
            .detach()
            .cpu()
            .numpy()
            .tolist()
        )
        self._log_live_openxr_controller_info(
            "[live_openxr_controller] immersive controller handedness validation: "
            f"sample={controller_basis_state['validation_sample_id']} "
            f"state={controller_basis_state.get('state', 'unknown')} "
            f"mode={controller_basis_state['validation_mode']} "
            f"resolved_from={controller_basis_state.get('resolved_from', 'none')} "
            f"candidate_streak={int(controller_basis_state.get('candidate_streak', 0))} "
            f"lock_reason={controller_basis_state.get('lock_reason')} "
            "stable_sources="
            f"{controller_basis_state.get('current_stable_sources', [])} "
            "seen_sources_ever="
            f"{controller_basis_state.get('seen_sources_ever', [])} "
            "pending_revalidation="
            f"{int(bool(controller_basis_state.get('pending_revalidation', False)))} "
            f"screen_center_x={controller_basis_state['screen_center_x']:.2f} "
            f"live_lateral_delta_x={_fmt(controller_basis_state['live_lateral_delta_x'])} "
            f"single_source={controller_basis_state.get('single_source_name')} "
            f"single_source_live_x={_fmt(controller_basis_state.get('single_source_live_x'))} "
            "single_source_projected_offset_x="
            f"{_fmt(controller_basis_state.get('single_source_projected_offset_x'))} "
            f"provisional_left_body_x={_fmt(controller_basis_state['provisional_left_body_x'])} "
            f"provisional_right_body_x={_fmt(controller_basis_state['provisional_right_body_x'])} "
            f"provisional_left_ray_x={_fmt(controller_basis_state['provisional_left_ray_x'])} "
            f"provisional_right_ray_x={_fmt(controller_basis_state['provisional_right_ray_x'])} "
            f"flip={int(bool(controller_basis_state['lateral_flip_applied']))} "
            f"final_left_body_x={_fmt(controller_basis_state['final_left_body_x'])} "
            f"final_right_body_x={_fmt(controller_basis_state['final_right_body_x'])} "
            f"final_left_ray_x={_fmt(controller_basis_state['final_left_ray_x'])} "
            f"final_right_ray_x={_fmt(controller_basis_state['final_right_ray_x'])} "
            f"controller_basis_lateral={basis_lateral}",
            flush=True,
        )

    def _controller_basis_active_sources(self, controller_runtime_state):
        if controller_runtime_state is None:
            return []
        active_sources = []
        for source in ("left", "right"):
            if controller_runtime_state.get(f"{source}_controller") is not None:
                active_sources.append(source)
        return active_sources

    def _update_immersive_controller_source_presence_state(
        self,
        controller_runtime_state,
        controller_basis_state,
        sample_id,
    ):
        updated_controller_basis_state = dict(controller_basis_state)
        present_counts = dict(
            updated_controller_basis_state.get(
                "source_present_counts",
                {"left": 0, "right": 0},
            )
        )
        absent_counts = dict(
            updated_controller_basis_state.get(
                "source_absent_counts",
                {"left": 0, "right": 0},
            )
        )
        stable_sources = set(
            updated_controller_basis_state.get("current_stable_sources", [])
        )
        seen_sources_ever = list(
            updated_controller_basis_state.get("seen_sources_ever", [])
        )
        seen_sources_ever_set = set(seen_sources_ever)
        raw_active_sources = set(
            self._controller_basis_active_sources(controller_runtime_state)
        )
        first_time_join_sources = []
        reconnect_sources = []

        for source in ("left", "right"):
            if source in raw_active_sources:
                present_counts[source] = int(present_counts.get(source, 0)) + 1
                absent_counts[source] = 0
                if (
                    source not in stable_sources
                    and present_counts[source]
                    >= int(self.IMMERSIVE_CONTROLLER_SOURCE_PRESENT_CONFIRM_SAMPLES)
                ):
                    stable_sources.add(source)
                    if source in seen_sources_ever_set:
                        reconnect_sources.append(source)
                        event = "reconnect"
                    else:
                        first_time_join_sources.append(source)
                        seen_sources_ever.append(source)
                        seen_sources_ever_set.add(source)
                        event = "first_join"
                    ordered_stable_sources = [
                        candidate
                        for candidate in ("left", "right")
                        if candidate in stable_sources
                    ]
                    self._log_live_openxr_controller_info(
                        "[live_openxr_controller] immersive controller source presence: "
                        f"sample={sample_id} source={source} event={event} "
                        f"stable_sources={ordered_stable_sources} "
                        f"seen_sources_ever={seen_sources_ever}",
                    )
            else:
                absent_counts[source] = int(absent_counts.get(source, 0)) + 1
                present_counts[source] = 0
                if (
                    source in stable_sources
                    and absent_counts[source]
                    >= int(self.IMMERSIVE_CONTROLLER_SOURCE_ABSENT_CONFIRM_SAMPLES)
                ):
                    stable_sources.remove(source)
                    ordered_stable_sources = [
                        candidate
                        for candidate in ("left", "right")
                        if candidate in stable_sources
                    ]
                    self._log_live_openxr_controller_info(
                        "[live_openxr_controller] immersive controller source presence: "
                        f"sample={sample_id} source={source} event=absent "
                        f"stable_sources={ordered_stable_sources} "
                        f"seen_sources_ever={seen_sources_ever}",
                    )

        updated_controller_basis_state["source_present_counts"] = present_counts
        updated_controller_basis_state["source_absent_counts"] = absent_counts
        updated_controller_basis_state["current_stable_sources"] = [
            source for source in ("left", "right") if source in stable_sources
        ]
        updated_controller_basis_state["seen_sources_ever"] = seen_sources_ever
        return (
            updated_controller_basis_state,
            first_time_join_sources,
            reconnect_sources,
        )

    def _reopen_immersive_controller_basis_state(
        self,
        controller_basis_state,
        sample_id,
        reason,
    ):
        updated_controller_basis_state = dict(controller_basis_state)
        updated_controller_basis_state["state"] = "pending"
        updated_controller_basis_state["resolved"] = False
        updated_controller_basis_state["validation_mode"] = f"pending_{reason}"
        updated_controller_basis_state["validation_sample_id"] = int(sample_id)
        updated_controller_basis_state["candidate_flip"] = None
        updated_controller_basis_state["candidate_validation_mode"] = None
        updated_controller_basis_state["candidate_streak"] = 0
        updated_controller_basis_state["resolution_start_sample"] = int(sample_id)
        updated_controller_basis_state["resolution_deadline_sample"] = (
            int(sample_id)
            + int(self.IMMERSIVE_CONTROLLER_HANDNESS_MAX_VALID_SAMPLES)
        )
        updated_controller_basis_state["lock_reason"] = None
        updated_controller_basis_state["lock_sample_id"] = None
        updated_controller_basis_state["pending_revalidation"] = False
        updated_controller_basis_state["pending_revalidation_reason"] = None
        updated_controller_basis_state["live_lateral_delta_x"] = None
        updated_controller_basis_state["single_source_name"] = None
        updated_controller_basis_state["single_source_live_x"] = None
        updated_controller_basis_state["single_source_projected_offset_x"] = None
        updated_controller_basis_state["provisional_left_body_x"] = None
        updated_controller_basis_state["provisional_right_body_x"] = None
        updated_controller_basis_state["provisional_left_ray_x"] = None
        updated_controller_basis_state["provisional_right_ray_x"] = None
        updated_controller_basis_state["final_left_body_x"] = None
        updated_controller_basis_state["final_right_body_x"] = None
        updated_controller_basis_state["final_left_ray_x"] = None
        updated_controller_basis_state["final_right_ray_x"] = None
        updated_controller_basis_state["resolved_from"] = "none"
        self._log_live_openxr_controller_info(
            "[live_openxr_controller] immersive controller handedness reopen: "
            f"sample={sample_id} reason={reason} "
            "sticky_basis_reused_until_revalidated=1",
        )
        return updated_controller_basis_state

    def _single_controller_handedness_candidate(
        self,
        source,
        live_grip_position,
        projected_body_x,
        projected_body_valid,
        projected_ray_x,
        projected_ray_valid,
        screen_center_x,
    ):
        live_x = float(np.asarray(live_grip_position, dtype=np.float32)[0])
        if abs(live_x) < float(self.IMMERSIVE_CONTROLLER_SINGLE_LATERAL_MIN_M):
            return None, None, live_x, None

        projected_x = None
        validation_mode = None
        if projected_body_valid and projected_body_x is not None:
            projected_x = float(projected_body_x)
            validation_mode = f"single_{source}_body"
        elif projected_ray_valid and projected_ray_x is not None:
            projected_x = float(projected_ray_x)
            validation_mode = f"single_{source}_ray"
        if projected_x is None:
            return None, validation_mode, live_x, None

        projected_offset_x = float(projected_x - screen_center_x)
        if (
            abs(projected_offset_x)
            < float(self.IMMERSIVE_CONTROLLER_SINGLE_PROJECTED_OFFSET_MIN_PX)
        ):
            return None, validation_mode, live_x, projected_offset_x
        return (live_x * projected_offset_x) < 0.0, validation_mode, live_x, projected_offset_x

    def _controller_basis_interaction_started(
        self,
        controller_runtime_state,
        controller_interaction_state,
    ):
        if controller_runtime_state is not None:
            for source in ("left", "right"):
                controller_world = controller_runtime_state.get(f"{source}_controller")
                if controller_world is None:
                    continue
                if bool(controller_world.get("select_start_edge", False)):
                    return True
                if bool(controller_world.get("select_hold_active", False)):
                    return True
        if controller_interaction_state is not None:
            for source in ("left", "right"):
                if controller_interaction_state.get(source) is not None:
                    return True
        return False

    def _lock_immersive_controller_basis_state(
        self,
        controller_basis_state,
        sample_id,
        lock_reason,
        validation_mode=None,
        basis=None,
        lateral_flip_applied=None,
        resolved_from=None,
        controller_runtime_state=None,
    ):
        updated_controller_basis_state = dict(controller_basis_state)
        updated_controller_basis_state["state"] = "locked"
        updated_controller_basis_state["resolved"] = True
        updated_controller_basis_state["lock_reason"] = lock_reason
        updated_controller_basis_state["lock_sample_id"] = int(sample_id)
        updated_controller_basis_state["validation_sample_id"] = int(sample_id)
        updated_controller_basis_state["locked_active_sources"] = (
            self._controller_basis_active_sources(controller_runtime_state)
        )
        if validation_mode is not None:
            updated_controller_basis_state["validation_mode"] = validation_mode
        if basis is not None:
            updated_controller_basis_state["basis"] = basis
        if lateral_flip_applied is not None:
            updated_controller_basis_state["lateral_flip_applied"] = bool(
                lateral_flip_applied
            )
        if resolved_from is not None:
            updated_controller_basis_state["resolved_from"] = str(resolved_from)
        updated_controller_basis_state["pending_revalidation"] = False
        updated_controller_basis_state["pending_revalidation_reason"] = None
        return updated_controller_basis_state

    def _maybe_note_late_controller_seen_after_lock(
        self,
        controller_runtime_state,
        controller_basis_state,
    ):
        if (
            controller_runtime_state is None
            or controller_basis_state is None
            or controller_basis_state.get("state") != "locked"
        ):
            return controller_basis_state
        updated_controller_basis_state = dict(controller_basis_state)
        seen_after_lock = list(
            updated_controller_basis_state.get("late_controller_seen_after_lock", [])
        )
        locked_active_sources = set(
            updated_controller_basis_state.get("locked_active_sources", [])
        )
        for source in self._controller_basis_active_sources(controller_runtime_state):
            if source in locked_active_sources or source in seen_after_lock:
                continue
            seen_after_lock.append(source)
            self._log_live_openxr_controller_info(
                "[live_openxr_controller] "
                f"immersive late_controller_seen_after_lock source={source} "
                "basis_reused=1",
            )
        updated_controller_basis_state["late_controller_seen_after_lock"] = (
            seen_after_lock
        )
        return updated_controller_basis_state

    def _maybe_resolve_immersive_controller_handedness(
        self,
        latest_controller_sample,
        controller_runtime_state,
        controller_basis_state,
        controller_source_anchor_centers,
        intrinsic,
        w2c,
        controller_interaction_state=None,
        alignment_pose_role="selected",
        controller_position_pose_role="selected",
        controller_ray_pose_role=None,
    ):
        if (
            latest_controller_sample is None
            or controller_runtime_state is None
            or controller_basis_state is None
        ):
            return controller_runtime_state, controller_basis_state
        sample_id = int(latest_controller_sample.sample)
        (
            updated_controller_basis_state,
            first_time_join_sources,
            reconnect_sources,
        ) = self._update_immersive_controller_source_presence_state(
            controller_runtime_state,
            controller_basis_state,
            sample_id,
        )
        interaction_active = self._controller_basis_interaction_started(
            controller_runtime_state,
            controller_interaction_state,
        )
        stable_sources = list(
            updated_controller_basis_state.get("current_stable_sources", [])
        )
        canonical_basis = updated_controller_basis_state["head_basis"].clone()

        if updated_controller_basis_state.get("state") == "locked":
            if reconnect_sources:
                self._log_live_openxr_controller_info(
                    "[live_openxr_controller] immersive controller reconnect reusing "
                    f"canonical sticky basis: sample={sample_id} sources={reconnect_sources} "
                    f"stable_sources={stable_sources} "
                    "resolved_from=canonical_global no_per_source_flip=1",
                )
            if first_time_join_sources:
                join_reason = (
                    "during_active_interaction"
                    if interaction_active
                    else "while_idle"
                )
                self._log_live_openxr_controller_info(
                    "[live_openxr_controller] immersive controller first-time join "
                    "reusing canonical global basis: "
                    f"sample={sample_id} sources={first_time_join_sources} "
                    f"stable_sources={stable_sources} reason={join_reason} "
                    "no_per_source_flip=1",
                )
            return controller_runtime_state, updated_controller_basis_state

        if updated_controller_basis_state.get("resolution_start_sample") is None:
            updated_controller_basis_state["resolution_start_sample"] = sample_id
            updated_controller_basis_state["resolution_deadline_sample"] = (
                sample_id + int(self.IMMERSIVE_CONTROLLER_HANDNESS_MAX_VALID_SAMPLES)
            )

        def _lock_timeout_default():
            timed_out_state = self._lock_immersive_controller_basis_state(
                updated_controller_basis_state,
                sample_id=sample_id,
                lock_reason="timeout_default",
                validation_mode="canonical_timeout_default",
                basis=canonical_basis,
                lateral_flip_applied=False,
                resolved_from="canonical_global",
                controller_runtime_state=controller_runtime_state,
            )
            self._log_immersive_controller_handedness_resolution(
                timed_out_state
            )
            return controller_runtime_state, timed_out_state

        left_grip_position = controller_pose_position(
            latest_controller_sample.left,
            alignment_pose_role,
        )
        right_grip_position = controller_pose_position(
            latest_controller_sample.right,
            alignment_pose_role,
        )
        live_lateral_delta_x = None
        if left_grip_position is not None and right_grip_position is not None:
            live_lateral_delta_x = float(
                np.asarray(right_grip_position, dtype=np.float32)[0]
                - np.asarray(left_grip_position, dtype=np.float32)[0]
            )

        provisional_left_body_x, _, provisional_left_body_valid = (
            self._project_controller_world_field_to_startup_screen_x(
                controller_runtime_state.get("left_controller"),
                "position",
                intrinsic,
                w2c,
            )
        )
        provisional_right_body_x, _, provisional_right_body_valid = (
            self._project_controller_world_field_to_startup_screen_x(
                controller_runtime_state.get("right_controller"),
                "position",
                intrinsic,
                w2c,
            )
        )
        provisional_left_ray_x, _, provisional_left_ray_valid = (
            self._project_controller_world_field_to_startup_screen_x(
                controller_runtime_state.get("left_controller"),
                "ray_origin",
                intrinsic,
                w2c,
            )
        )
        provisional_right_ray_x, _, provisional_right_ray_valid = (
            self._project_controller_world_field_to_startup_screen_x(
                controller_runtime_state.get("right_controller"),
                "ray_origin",
                intrinsic,
                w2c,
            )
        )

        updated_controller_basis_state.update(
            {
                "live_lateral_delta_x": live_lateral_delta_x,
                "single_source_name": None,
                "single_source_live_x": None,
                "single_source_projected_offset_x": None,
                "provisional_left_body_x": provisional_left_body_x,
                "provisional_right_body_x": provisional_right_body_x,
                "provisional_left_ray_x": provisional_left_ray_x,
                "provisional_right_ray_x": provisional_right_ray_x,
            }
        )
        if not stable_sources:
            if sample_id >= int(updated_controller_basis_state["resolution_deadline_sample"]):
                return _lock_timeout_default()
            return controller_runtime_state, updated_controller_basis_state
        basis_changed = not torch.allclose(
            canonical_basis,
            updated_controller_basis_state["basis"],
            rtol=1e-6,
            atol=1e-6,
        )
        if basis_changed:
            controller_runtime_state = self._recompute_live_controller_runtime_state_for_basis(
                latest_controller_sample,
                controller_runtime_state,
                controller_source_anchor_centers,
                w2c,
                canonical_basis,
                alignment_pose_role=alignment_pose_role,
                controller_position_pose_role=controller_position_pose_role,
                controller_ray_pose_role=controller_ray_pose_role,
            )

        final_left_body_x, _, _ = self._project_controller_world_field_to_startup_screen_x(
            controller_runtime_state.get("left_controller"),
            "position",
            intrinsic,
            w2c,
        )
        final_right_body_x, _, _ = self._project_controller_world_field_to_startup_screen_x(
            controller_runtime_state.get("right_controller"),
            "position",
            intrinsic,
            w2c,
        )
        final_left_ray_x, _, _ = self._project_controller_world_field_to_startup_screen_x(
            controller_runtime_state.get("left_controller"),
            "ray_origin",
            intrinsic,
            w2c,
        )
        final_right_ray_x, _, _ = self._project_controller_world_field_to_startup_screen_x(
            controller_runtime_state.get("right_controller"),
            "ray_origin",
            intrinsic,
            w2c,
        )
        updated_controller_basis_state["final_left_body_x"] = final_left_body_x
        updated_controller_basis_state["final_right_body_x"] = final_right_body_x
        updated_controller_basis_state["final_left_ray_x"] = final_left_ray_x
        updated_controller_basis_state["final_right_ray_x"] = final_right_ray_x
        updated_controller_basis_state = self._lock_immersive_controller_basis_state(
            updated_controller_basis_state,
            sample_id=sample_id,
            lock_reason="canonical_global_locked",
            validation_mode="canonical_global_basis",
            basis=canonical_basis,
            lateral_flip_applied=False,
            resolved_from="canonical_global",
            controller_runtime_state=controller_runtime_state,
        )
        self._log_immersive_controller_handedness_resolution(
            updated_controller_basis_state
        )
        return controller_runtime_state, updated_controller_basis_state

    def _immersive_live_forward_from_sample(self, sample):
        if sample is None:
            return None

        eye_forwards = []
        for eye_sample in (sample.left_eye, sample.right_eye):
            if eye_sample is None or not eye_sample.pose_valid:
                continue
            rotation_local = self._quaternion_xyzw_to_rotation_matrix(
                eye_sample.orientation
            )
            eye_forwards.append(rotation_local @ np.array([0.0, 0.0, -1.0], dtype=np.float32))
        if not eye_forwards:
            return None
        return self._normalize_numpy_vector(
            np.mean(np.stack(eye_forwards, axis=0), axis=0),
            fallback=np.array([0.0, 0.0, -1.0], dtype=np.float32),
        )

    def _immersive_sample_has_valid_eye_pose(self, sample):
        return bool(
            sample is not None
            and (
                (sample.left_eye is not None and sample.left_eye.pose_valid)
                or (sample.right_eye is not None and sample.right_eye.pose_valid)
            )
        )

    def _immersive_live_head_center_from_sample(self, sample):
        if sample is None:
            return None

        eye_positions = []
        for eye_sample in (sample.left_eye, sample.right_eye):
            if eye_sample is None or not eye_sample.pose_valid:
                continue
            eye_positions.append(
                torch.from_numpy(np.asarray(eye_sample.position, dtype=np.float32)).to(
                    device=cfg.device,
                    dtype=torch.float32,
                )
            )
        if not eye_positions:
            return None
        return torch.stack(eye_positions, dim=0).mean(dim=0)

    def _compute_immersive_head_alignment(self, sample):
        live_head_origin = self._immersive_live_head_center_from_sample(sample)
        if live_head_origin is None:
            return None

        local_up = np.array([0.0, 1.0, 0.0], dtype=np.float32)
        live_forward = self._immersive_live_forward_from_sample(sample)
        if live_forward is None:
            return None
        live_forward_horizontal = live_forward - float(np.dot(live_forward, local_up)) * local_up
        live_forward_horizontal = self._normalize_numpy_vector(
            live_forward_horizontal,
            fallback=np.array([0.0, 0.0, -1.0], dtype=np.float32),
        )
        live_back = -live_forward_horizontal
        live_right = self._normalize_numpy_vector(
            np.cross(local_up, live_back),
            fallback=np.array([1.0, 0.0, 0.0], dtype=np.float32),
        )
        live_back = self._normalize_numpy_vector(
            np.cross(live_right, local_up),
            fallback=live_back,
        )
        live_basis = np.stack([live_right, local_up, live_back], axis=1)

        scene_up = self._scene_world_up_vector_np()
        scene_forward = self._scene_world_forward_vector_np()
        scene_back = -scene_forward
        scene_right = self._normalize_numpy_vector(
            np.cross(scene_up, scene_back),
            fallback=np.array([1.0, 0.0, 0.0], dtype=np.float32),
        )
        scene_back = self._normalize_numpy_vector(
            np.cross(scene_right, scene_up),
            fallback=scene_back,
        )
        scene_basis = np.stack([scene_right, scene_up, scene_back], axis=1)
        basis_np = (scene_basis @ live_basis.T).astype(np.float32)
        basis_np_t_basis = basis_np.T @ basis_np

        return {
            "basis": torch.as_tensor(basis_np, dtype=torch.float32, device=cfg.device),
            "translation_scale": torch.tensor(
                self.IMMERSIVE_LIVE_HEAD_TRANSLATION_SCALE,
                dtype=torch.float32,
                device=cfg.device,
            ),
            "reference_live_head": live_head_origin,
            "reference_scene_head": torch.zeros(
                3, dtype=torch.float32, device=cfg.device
            ),
            "scene_up": scene_up,
            "scene_forward": scene_forward,
            "scene_right": scene_right,
            "basis_det": float(np.linalg.det(basis_np)),
            "basis_orthogonality_error": float(
                np.max(np.abs(basis_np_t_basis - np.eye(3, dtype=np.float32)))
            ),
            "startup_live_forward": live_forward_horizontal,
        }

    def _map_live_delta_into_scene(self, delta, head_alignment):
        delta = torch.as_tensor(delta, dtype=torch.float32, device=cfg.device)
        return (
            head_alignment["basis"] @ delta
        ) * head_alignment["translation_scale"]

    def _map_live_head_center_into_scene(self, live_head_center, head_alignment):
        live_head_center = torch.as_tensor(
            live_head_center, dtype=torch.float32, device=cfg.device
        )
        return head_alignment["reference_scene_head"] + self._map_live_delta_into_scene(
            live_head_center - head_alignment["reference_live_head"],
            head_alignment,
        )

    def _update_immersive_head_pose_state(
        self,
        sample,
        head_alignment,
        head_pose_state,
        frame_index=0,
    ):
        if sample is None or head_alignment is None:
            return None, None, head_pose_state

        if head_pose_state is None:
            head_pose_state = {
                "smoothed_scene_head_center": None,
                "last_raw_scene_head_center": None,
                "had_valid_pose": False,
                "cached_scene_eye_offsets": {},
                "last_eye_rotations_world": {},
                "last_reset_frame_index": -1,
            }

        valid_eye_positions_live = {}
        current_scene_eye_offsets = {}
        current_eye_rotations_world = {}
        basis_np = head_alignment["basis"].detach().cpu().numpy()

        for source, eye_sample in (
            ("left", sample.left_eye),
            ("right", sample.right_eye),
        ):
            if eye_sample is None or not eye_sample.pose_valid:
                continue
            eye_position_live = torch.from_numpy(
                np.asarray(eye_sample.position, dtype=np.float32)
            ).to(device=cfg.device, dtype=torch.float32)
            valid_eye_positions_live[source] = eye_position_live
            rotation_local = self._quaternion_xyzw_to_rotation_matrix(
                eye_sample.orientation
            )
            current_eye_rotations_world[source] = (basis_np @ rotation_local).astype(
                np.float32
            )

        if not valid_eye_positions_live:
            head_pose_state["had_valid_pose"] = False
            return None, None, head_pose_state

        live_head_center = torch.stack(
            list(valid_eye_positions_live.values()), dim=0
        ).mean(dim=0)
        raw_scene_head_center = self._map_live_head_center_into_scene(
            live_head_center,
            head_alignment,
        )

        for source, eye_position_live in valid_eye_positions_live.items():
            current_scene_eye_offsets[source] = self._map_live_delta_into_scene(
                eye_position_live - live_head_center,
                head_alignment,
            )

        cached_scene_eye_offsets = dict(
            head_pose_state.get("cached_scene_eye_offsets", {})
        )
        cached_scene_eye_offsets.update(current_scene_eye_offsets)

        previous_raw_scene_head_center = head_pose_state.get(
            "last_raw_scene_head_center"
        )
        raw_scene_head_jump = None
        if previous_raw_scene_head_center is not None:
            raw_scene_head_jump = float(
                torch.linalg.norm(
                    raw_scene_head_center - previous_raw_scene_head_center
                ).item()
            )

        reset_reason = None
        if head_pose_state.get("smoothed_scene_head_center") is None:
            reset_reason = "startup"
        elif not head_pose_state.get("had_valid_pose", False):
            reset_reason = "tracking_reacquired"
        elif (
            raw_scene_head_jump is not None
            and raw_scene_head_jump > self.IMMERSIVE_HEAD_RESET_JUMP_THRESHOLD
        ):
            reset_reason = f"jump_{raw_scene_head_jump:.3f}"

        if reset_reason is not None:
            smoothed_scene_head_center = raw_scene_head_center.clone()
        else:
            alpha = float(self.IMMERSIVE_HEAD_TRANSLATION_EMA_ALPHA)
            smoothed_scene_head_center = (
                alpha * raw_scene_head_center
                + (1.0 - alpha) * head_pose_state["smoothed_scene_head_center"]
            )
        last_reset_frame_index = int(
            head_pose_state.get("last_reset_frame_index", -1)
        )
        if reset_reason is not None:
            last_reset_frame_index = int(frame_index)

        last_eye_rotations_world = dict(
            head_pose_state.get("last_eye_rotations_world", {})
        )
        last_eye_rotations_world.update(current_eye_rotations_world)

        head_pose_state.update(
            {
                "smoothed_scene_head_center": smoothed_scene_head_center,
                "last_raw_scene_head_center": raw_scene_head_center.clone(),
                "had_valid_pose": True,
                "cached_scene_eye_offsets": cached_scene_eye_offsets,
                "last_eye_rotations_world": last_eye_rotations_world,
                "last_reset_frame_index": last_reset_frame_index,
            }
        )

        eye_pose_world = {}
        debug_offsets = {}
        for source, eye_sample in (
            ("left", sample.left_eye),
            ("right", sample.right_eye),
        ):
            eye_offset_world = current_scene_eye_offsets.get(
                source,
                cached_scene_eye_offsets.get(source),
            )
            rotation_world = current_eye_rotations_world.get(
                source,
                last_eye_rotations_world.get(source),
            )
            debug_offsets[source] = (
                None
                if eye_offset_world is None
                else eye_offset_world.detach().cpu().numpy().tolist()
            )
            if eye_offset_world is None or rotation_world is None:
                eye_pose_world[source] = None
                continue
            pose = np.eye(4, dtype=np.float32)
            pose[:3, :3] = rotation_world
            pose[:3, 3] = (
                smoothed_scene_head_center + eye_offset_world
            ).detach().cpu().numpy()
            eye_pose_world[source] = pose

        if (
            reset_reason is not None
            or frame_index == 0
            or (
                self.IMMERSIVE_HEAD_DEBUG_LOG_INTERVAL > 0
                and frame_index % self.IMMERSIVE_HEAD_DEBUG_LOG_INTERVAL == 0
            )
        ):
            print(
                "[quest_display] immersive head pose: "
                f"frame={frame_index} "
                f"raw_head_center={raw_scene_head_center.detach().cpu().numpy().tolist()} "
                f"smoothed_head_center={smoothed_scene_head_center.detach().cpu().numpy().tolist()} "
                f"left_offset={debug_offsets['left']} "
                f"right_offset={debug_offsets['right']} "
                f"reset={reset_reason}",
                flush=True,
            )

        return eye_pose_world["left"], eye_pose_world["right"], head_pose_state

    def _format_controller_pose_startup_state(self, controller_sample):
        if controller_sample is None:
            return "missing"
        return (
            f"active={int(bool(controller_sample.active))} "
            f"position_valid={int(bool(controller_sample.position_valid))} "
            f"orientation_valid={int(bool(controller_sample.orientation_valid))} "
            f"position_tracked={int(bool(controller_sample.position_tracked))} "
            f"orientation_tracked={int(bool(controller_sample.orientation_tracked))}"
        )

    def _format_eye_pose_startup_state(self, eye_sample):
        if eye_sample is None:
            return "missing"
        return (
            f"pose_valid={int(bool(eye_sample.pose_valid))} "
            f"pose_tracked={int(bool(eye_sample.pose_tracked))}"
        )

    def _format_immersive_sample_startup_state(self, sample):
        if sample is None:
            return "no immersive sample received yet"
        return (
            f"left_eye({self._format_eye_pose_startup_state(sample.left_eye)}) "
            f"right_eye({self._format_eye_pose_startup_state(sample.right_eye)}) "
            f"left_controller({self._format_controller_pose_startup_state(sample.left)}) "
            f"right_controller({self._format_controller_pose_startup_state(sample.right)})"
        )

    def _wait_for_valid_immersive_startup_sample(
        self,
        immersive_bridge,
        timeout=10.0,
        progress_callback=None,
    ):
        deadline = time.time() + timeout
        last_sample = None
        while time.time() < deadline:
            if progress_callback is not None:
                progress_callback("startup_wait_for_sample")
            sample = immersive_bridge.get_latest_sample()
            if sample is not None:
                last_sample = sample
                if self._immersive_sample_has_valid_eye_pose(sample):
                    return sample
            if (
                immersive_bridge.process is not None
                and immersive_bridge.process.poll() is not None
            ):
                diagnostics = self._format_immersive_sample_startup_state(last_sample)
                raise RuntimeError(
                    "Quest immersive bridge exited before producing a valid eye pose.\n"
                    f"last_sample: {diagnostics}\n"
                    + immersive_bridge.debug_summary()
                )
            time.sleep(0.05)

        diagnostics = self._format_immersive_sample_startup_state(last_sample)
        raise RuntimeError(
            "Timed out waiting for a valid immersive eye pose.\n"
            f"last_sample: {diagnostics}\n"
            + immersive_bridge.debug_summary()
        )

    def _immersive_bridge_process_state(self, immersive_bridge):
        if immersive_bridge is None:
            return "not_started"
        process = getattr(immersive_bridge, "process", None)
        if process is None:
            return "not_started"
        exit_code = process.poll()
        if exit_code is None:
            return "alive"
        return f"exited(code={exit_code})"

    def _make_immersive_startup_timeline(self):
        return {
            "t0": time.perf_counter(),
            "milestones": [],
            "last_milestone": None,
            "bridge_started_ms": None,
            "first_publish_done_ms": None,
        }

    def _record_immersive_startup_milestone(self, startup_timeline, name, immersive_bridge=None):
        elapsed_ms = (time.perf_counter() - startup_timeline["t0"]) * 1000.0
        bridge_state = self._immersive_bridge_process_state(immersive_bridge)
        milestone = {
            "name": str(name),
            "elapsed_ms": float(elapsed_ms),
            "bridge_state": bridge_state,
        }
        startup_timeline["milestones"].append(milestone)
        startup_timeline["last_milestone"] = str(name)
        if name == "bridge_started":
            startup_timeline["bridge_started_ms"] = float(elapsed_ms)
        elif name == "first_publish_done":
            startup_timeline["first_publish_done_ms"] = float(elapsed_ms)
            bridge_started_ms = startup_timeline.get("bridge_started_ms")
            if bridge_started_ms is not None:
                startup_timeline["startup_gap_ms"] = float(elapsed_ms - bridge_started_ms)
        print(
            "[quest_display] immersive startup milestone: "
            f"{name} elapsed_ms={elapsed_ms:.1f} bridge={bridge_state}",
            flush=True,
        )
        return milestone

    def _format_immersive_startup_timeline_failure(
        self,
        startup_timeline,
        immersive_bridge=None,
    ):
        if startup_timeline is None:
            return ""
        bridge_state = self._immersive_bridge_process_state(immersive_bridge)
        bridge_started_ms = startup_timeline.get("bridge_started_ms")
        last_milestone = startup_timeline.get("last_milestone")
        elapsed_ms = (time.perf_counter() - startup_timeline["t0"]) * 1000.0
        parts = [
            "immersive startup timeline failure: "
            f"last_completed_milestone={last_milestone} "
            f"elapsed_ms={elapsed_ms:.1f} "
            f"bridge={bridge_state}"
        ]
        if bridge_started_ms is not None:
            parts.append(
                f"elapsed_since_bridge_started_ms={elapsed_ms - bridge_started_ms:.1f}"
            )
        return " ".join(parts)

    def _load_immersive_tutorial_slide_frame(
        self,
        slide_path,
        *,
        eye_width,
        eye_height,
    ):
        slide_path = Path(slide_path).resolve()
        if not slide_path.exists():
            raise FileNotFoundError(
                f"Immersive tutorial slide image not found: {slide_path}"
            )
        with Image.open(slide_path) as image_handle:
            image_rgba = image_handle.convert("RGBA")
            source_width, source_height = image_rgba.size
            if source_width <= 0 or source_height <= 0:
                raise ValueError(
                    f"Immersive tutorial slide has invalid size: {slide_path}"
                )
            safe_width = max(
                1,
                int(
                    round(
                        float(eye_width)
                        * float(self.IMMERSIVE_TUTORIAL_SAFE_WIDTH_FRACTION)
                    )
                ),
            )
            safe_height = max(
                1,
                int(
                    round(
                        float(eye_height)
                        * float(self.IMMERSIVE_TUTORIAL_SAFE_HEIGHT_FRACTION)
                    )
                ),
            )
            fit_scale = min(
                float(safe_width) / float(source_width),
                float(safe_height) / float(source_height),
                1.0,
            )
            resized_width = max(1, int(round(float(source_width) * fit_scale)))
            resized_height = max(1, int(round(float(source_height) * fit_scale)))
            resampling = getattr(Image, "Resampling", Image)
            resized_rgba = image_rgba.resize(
                (resized_width, resized_height),
                resample=resampling.LANCZOS,
            )
            background_rgba = Image.new(
                "RGBA",
                (int(eye_width), int(eye_height)),
                tuple(int(value) for value in self.IMMERSIVE_TUTORIAL_BACKGROUND_RGBA),
            )
            offset_x = max(0, (int(eye_width) - resized_width) // 2)
            offset_y = max(0, (int(eye_height) - resized_height) // 2)
            background_rgba.alpha_composite(
                resized_rgba,
                dest=(offset_x, offset_y),
            )
        frame_np = np.asarray(background_rgba, dtype=np.uint8).copy()
        return torch.from_numpy(frame_np).to(device=cfg.device, dtype=torch.uint8)

    def _load_immersive_startup_tutorial_frames(self, eye_width, eye_height):
        slide_paths = list(getattr(cfg, "demo_tutorial_slide_paths", []) or [])
        if not slide_paths:
            return []
        tutorial_frames = []
        for slide_path in slide_paths:
            tutorial_frames.append(
                self._load_immersive_tutorial_slide_frame(
                    slide_path,
                    eye_width=int(eye_width),
                    eye_height=int(eye_height),
                )
            )
        return tutorial_frames

    def _launch_immersive_scene_renderer_prewarm(
        self,
        *,
        scene_assets_root,
        scene_width,
        scene_height,
        immersive_render_options,
        active_scene_stereo_mode,
        immersive_bridge=None,
        startup_timeline=None,
    ):
        self._record_immersive_startup_milestone(
            startup_timeline,
            "scene_renderer_construct_begin",
            immersive_bridge,
        )
        balanced_render_backend = (
            "pyrender"
            if active_scene_stereo_mode == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
            else "auto"
        )
        executor = concurrent.futures.ThreadPoolExecutor(
            max_workers=1,
            thread_name_prefix="immersive_scene_prewarm",
        )
        future = executor.submit(
            SimpleLabSceneRenderer,
            scene_assets_root=scene_assets_root,
            width=scene_width,
            height=scene_height,
            lighting_mode=immersive_render_options["lighting_mode"],
            balanced_render_backend=balanced_render_backend,
        )
        print(
            "[quest_display] immersive scene renderer prewarm launched: "
            f"scene_resolution={scene_width}x{scene_height} "
            f"lighting_mode={immersive_render_options['lighting_mode']} "
            f"balanced_render_backend={balanced_render_backend}",
            flush=True,
        )
        return {
            "executor": executor,
            "future": future,
            "balanced_render_backend": balanced_render_backend,
        }

    def _await_immersive_scene_renderer_prewarm(
        self,
        prewarm_state,
        *,
        immersive_bridge,
        keepalive_state,
        latest_sample,
        startup_timeline=None,
    ):
        if prewarm_state is None:
            return None, latest_sample

        executor = prewarm_state.get("executor")
        future = prewarm_state.get("future")
        if future is None:
            if executor is not None:
                executor.shutdown(wait=False)
            return None, latest_sample

        wait_logged = False
        try:
            while not future.done():
                if not wait_logged:
                    print(
                        "[quest_display] immersive scene renderer prewarm still running; "
                        "keeping tutorial slide visible until startup can continue",
                        flush=True,
                    )
                    wait_logged = True
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    keepalive_state,
                    reason="scene_renderer_prewarm_wait",
                    startup_timeline=startup_timeline,
                )
                min_sample_id = int(getattr(latest_sample, "sample", -1))
                sample = immersive_bridge.wait_for_newer_sample(
                    min_sample_id=min_sample_id,
                    timeout_s=float(self.IMMERSIVE_TUTORIAL_SAMPLE_POLL_INTERVAL_SECONDS),
                )
                if sample is not None:
                    latest_sample = sample
            scene_renderer = future.result()
        except Exception as exc:
            failure_details = self._format_immersive_startup_timeline_failure(
                startup_timeline,
                immersive_bridge,
            )
            raise RuntimeError(
                "Immersive scene renderer prewarm failed during startup.\n"
                + (failure_details + "\n" if failure_details else "")
                + f"{type(exc).__name__}: {exc}"
            ) from exc
        finally:
            if executor is not None:
                executor.shutdown(wait=False)

        self._record_immersive_startup_milestone(
            startup_timeline,
            "scene_renderer_construct_done",
            immersive_bridge,
        )
        return scene_renderer, latest_sample

    def _progress_immersive_startup_bootstrap(
        self,
        bootstrap_state,
        *,
        latest_sample,
        force,
        startup_context,
    ):
        if bootstrap_state is None:
            bootstrap_state = {}
        bootstrap_output = bootstrap_state.setdefault("output", {})
        if latest_sample is not None:
            bootstrap_output["initial_sample"] = latest_sample
        current_sample = bootstrap_output.get("initial_sample")
        if current_sample is None:
            return latest_sample
        if bool(bootstrap_state.get("complete", False)):
            return current_sample
        return self._progress_immersive_startup_bootstrap_substages(
            bootstrap_state,
            force=force,
            startup_context=startup_context,
        )

    def _progress_immersive_startup_bootstrap_substages(
        self,
        bootstrap_state,
        *,
        force,
        startup_context,
    ):
        bootstrap_output = bootstrap_state.setdefault("output", {})
        current_sample = bootstrap_output.get("initial_sample")
        if current_sample is None:
            return None

        immersive_bridge = startup_context["immersive_bridge"]
        startup_keepalive_state = startup_context["startup_keepalive_state"]
        startup_timeline = startup_context.get("startup_timeline")
        scene_renderer_prewarm_state = startup_context["scene_renderer_prewarm_state"]
        intrinsic = startup_context["intrinsic"]
        w2c = startup_context["w2c"]
        gaussians = startup_context["gaussians"]
        render_pipe = startup_context["render_pipe"]
        background_black = startup_context["background_black"]
        background_white = startup_context["background_white"]
        diagnostic_view_render_path = startup_context["diagnostic_view_render_path"]
        scene_width = int(startup_context["scene_width"])
        scene_height = int(startup_context["scene_height"])
        eye_width = int(startup_context["eye_width"])
        eye_height = int(startup_context["eye_height"])
        immersive_render_options = startup_context["immersive_render_options"]
        profile_enabled = bool(startup_context["profile_enabled"])
        scene_assets_root = startup_context["scene_assets_root"]
        immersive_static_scene_mode = startup_context["immersive_static_scene_mode"]
        immersive_support_entry_overlay_enabled = bool(
            startup_context["immersive_support_entry_overlay_enabled"]
        )
        static_scene_overlap_requested = bool(
            startup_context["static_scene_overlap_requested"]
        )
        scene_depth_reproject_requested = bool(
            startup_context["scene_depth_reproject_requested"]
        )
        framegen_requested = bool(startup_context["framegen_requested"])
        immersive_framegen_mode = startup_context["immersive_framegen_mode"]
        immersive_gaussian_render_mode = startup_context["immersive_gaussian_render_mode"]
        presentation_backend_enabled = bool(
            startup_context["presentation_backend_enabled"]
        )
        presentation_backend_kind = startup_context["presentation_backend_kind"]
        immersive_present_pipeline_enabled = bool(
            startup_context["immersive_present_pipeline_enabled"]
        )
        controller_select_state_cache = startup_context["controller_select_state_cache"]
        controller_select_hold_state = startup_context["controller_select_hold_state"]
        controller_select_hold_state_cache = startup_context[
            "controller_select_hold_state_cache"
        ]
        controller_anchor_cycle_state_cache = startup_context[
            "controller_anchor_cycle_state_cache"
        ]
        controller_anchor_reset_state_cache = startup_context[
            "controller_anchor_reset_state_cache"
        ]
        controller_snap_state_cache = startup_context["controller_snap_state_cache"]
        controller_snap_edge_cache = startup_context["controller_snap_edge_cache"]
        controller_exit_hold_state = startup_context["controller_exit_hold_state"]
        controller_interaction_state = startup_context["controller_interaction_state"]
        live_controller_case_profile = startup_context["live_controller_case_profile"]
        shared_scene_compose_cache = startup_context["shared_scene_compose_cache"]
        shared_scene_reproject_caches = startup_context["shared_scene_reproject_caches"]

        bootstrap_output.setdefault(
            "head_pose_state",
            startup_context["head_pose_state"],
        )
        bootstrap_output.setdefault(
            "controller_predefined_anchor_defs",
            startup_context["controller_predefined_anchor_defs"],
        )
        bootstrap_output.setdefault(
            "obj_init_vertices",
            startup_context["obj_init_vertices"],
        )
        bootstrap_output.setdefault(
            "recorded_base_target",
            startup_context["recorded_base_target"],
        )
        bootstrap_output.setdefault(
            "recorded_anchor_centers",
            startup_context["recorded_anchor_centers"],
        )
        bootstrap_output.setdefault(
            "original_controller_source_anchor_centers",
            startup_context["original_controller_source_anchor_centers"],
        )
        bootstrap_output.setdefault(
            "original_controller_source_masks",
            startup_context["original_controller_source_masks"],
        )
        bootstrap_output.setdefault(
            "trained_spring_Y_for_sim",
            startup_context["trained_spring_Y_for_sim"],
        )
        bootstrap_output.setdefault(
            "active_scene_stereo_mode",
            startup_context["active_scene_stereo_mode"],
        )
        bootstrap_output.setdefault(
            "scene_depth_reproject_enabled",
            startup_context["scene_depth_reproject_enabled"],
        )
        bootstrap_output.setdefault(
            "balanced_eye_workers",
            startup_context["balanced_eye_workers"],
        )
        bootstrap_output.setdefault(
            "balanced_eye_parallel_enabled",
            startup_context["balanced_eye_parallel_enabled"],
        )
        bootstrap_output.setdefault(
            "static_scene_worker",
            startup_context["static_scene_worker"],
        )
        bootstrap_output.setdefault(
            "static_scene_overlap_enabled",
            startup_context["static_scene_overlap_enabled"],
        )
        bootstrap_output.setdefault(
            "static_scene_layer_cache",
            startup_context["static_scene_layer_cache"],
        )

        bootstrap_substages = (
            "await_scene_renderer_prewarm",
            "compute_live_head_alignment_and_initial_eye_state",
            "build_layout",
            "apply_scene_layout_and_check_readback_mode",
            "validate_table_alignment_and_log_layout",
            "apply_spawn_shift",
            "build_center_view_and_resolve_rope_endpoints",
            "assign_controller_sources_and_default_anchor_names",
            "build_two_point_runtime_and_batch_buffers",
            "init_simulator",
            "build_rotation_cache",
            "prime_live_controller_runtime_and_handedness",
            "prepare_balanced_runtime_state",
            "warmup_balanced_paths_and_seed_layer_cache",
            "start_eye_workers_if_enabled",
            "start_static_scene_worker_if_enabled",
            "prepare_colliders_support_boxes_idle_lock_and_cuda_graph",
            "settle_scene_rest_chunk",
            "restore_settled_state_and_build_anchor_templates",
            "validate_startup_scene_mode",
            "startup_validation_prepare",
            "startup_validation_scene_frames",
            "startup_validation_left_eye",
            "startup_validation_right_eye",
            "startup_validation_finalize",
        )
        coarse_stage_to_substage_index = {
            0: 0,
            1: 1,
            2: 9,
            3: 17,
            4: 20,
            5: len(bootstrap_substages),
        }
        coarse_stage_index = int(bootstrap_state.get("stage_index", 0))
        substage_index = int(
            bootstrap_state.get(
                "substage_index",
                coarse_stage_to_substage_index.get(coarse_stage_index, 0),
            )
        )
        settle_state = bootstrap_state.setdefault(
            "settle_state",
            {
                "step_idx": 0,
                "last_state": None,
                "done": False,
                "initialized": False,
                "completion_notified": False,
            },
        )
        validation_state = bootstrap_state.get("validation_state")

        def _refresh_substage_cursor():
            bootstrap_state["substage_index"] = substage_index
            bootstrap_state["substage_name"] = (
                "complete"
                if substage_index >= len(bootstrap_substages)
                else bootstrap_substages[substage_index]
            )

        def _complete_substage(name, *, stage_index=None):
            nonlocal substage_index
            print(
                "[quest_display] immersive startup bootstrap substage complete: "
                f"{name}",
                flush=True,
            )
            bootstrap_state["last_completed_substage"] = str(name)
            self._maybe_publish_immersive_startup_keepalive(
                immersive_bridge,
                startup_keepalive_state,
                reason=f"bootstrap_{name}",
                startup_timeline=startup_timeline,
                force=not force,
            )
            substage_index += 1
            if stage_index is not None:
                bootstrap_state["stage_index"] = int(stage_index)
            _refresh_substage_cursor()

        _refresh_substage_cursor()
        while substage_index < len(bootstrap_substages):
            current_sample = bootstrap_output.get("initial_sample")
            if current_sample is None:
                return None
            substage_name = bootstrap_substages[substage_index]

            if substage_name == "await_scene_renderer_prewarm":
                prewarm_future = None
                if scene_renderer_prewarm_state is not None:
                    prewarm_future = scene_renderer_prewarm_state.get("future")
                if prewarm_future is not None and not prewarm_future.done() and not force:
                    return current_sample
                scene_renderer, current_sample = self._await_immersive_scene_renderer_prewarm(
                    scene_renderer_prewarm_state,
                    immersive_bridge=immersive_bridge,
                    keepalive_state=startup_keepalive_state,
                    latest_sample=current_sample,
                    startup_timeline=startup_timeline,
                )
                bootstrap_output["scene_renderer"] = scene_renderer
                bootstrap_output["initial_sample"] = current_sample
                bootstrap_output["scene_analysis_cache_debug"] = (
                    scene_renderer.scene_analysis_cache_debug()
                )
                scene_analysis_cache_debug = bootstrap_output["scene_analysis_cache_debug"]
                print(
                    "[quest_display] immersive scene analysis cache: "
                    f"status={scene_analysis_cache_debug.get('status')} "
                    f"reason={scene_analysis_cache_debug.get('reason')} "
                    f"schema={scene_analysis_cache_debug.get('schema')} "
                    f"input_hash={scene_analysis_cache_debug.get('input_hash')} "
                    f"path={scene_analysis_cache_debug.get('path')}",
                    flush=True,
                )
                print(
                    "[quest_display] immersive bridge target eye resolution="
                    f"{eye_width}x{eye_height}",
                    flush=True,
                )
                print(
                    "[quest_display] immersive render config: "
                    f"preset={immersive_render_options['preset']} "
                    f"scene_render_scale={immersive_render_options['scene_render_scale']:.3f} "
                    f"scene_resolution={scene_width}x{scene_height} "
                    f"scene_stereo_mode={bootstrap_output['active_scene_stereo_mode']} "
                    f"overlay_mode={immersive_render_options['overlay_mode']} "
                    f"lighting_mode={immersive_render_options['lighting_mode']}",
                    flush=True,
                )
                if bootstrap_output["active_scene_stereo_mode"] == "mono_head_center":
                    print(
                        "[quest_display] immersive scene stereo approximation active: "
                        "mono_head_center reuses one room render across both eyes and is known "
                        "to produce near-geometry stereo artifacts",
                        flush=True,
                    )
                elif bootstrap_output["active_scene_stereo_mode"] == "reproject_from_center":
                    print(
                        "[quest_display] immersive scene stereo approximation active: "
                        "reproject_from_center renders the room once and reprojects it into "
                        "left/right eyes",
                        flush=True,
                    )
                elif (
                    bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                ):
                    print(
                        "[quest_display] immersive scene stereo approximation active: "
                        "balanced renders the room background separately for each eye and "
                        "renders only a per-eye table ROI to keep the table crisp",
                        flush=True,
                    )
                print(
                    "[quest_display] runtime recommended eye sizes: "
                    f"left={current_sample.left_eye.recommended_width}x{current_sample.left_eye.recommended_height} "
                    f"right={current_sample.right_eye.recommended_width}x{current_sample.right_eye.recommended_height}",
                    flush=True,
                )
                print(
                    "[quest_display] immersive startup sample: "
                    + self._format_immersive_sample_startup_state(current_sample),
                    flush=True,
                )
                _complete_substage(substage_name, stage_index=1)
                if not force:
                    return current_sample
                continue

            if substage_name == "compute_live_head_alignment_and_initial_eye_state":
                live_head_alignment = self._compute_immersive_head_alignment(current_sample)
                if live_head_alignment is None:
                    raise RuntimeError(
                        "Immersive mode did not receive a valid eye pose for startup.\n"
                        f"last_sample: {self._format_immersive_sample_startup_state(current_sample)}"
                    )
                print(
                    "[quest_display] immersive scene frame: "
                    f"up={live_head_alignment['scene_up'].tolist()} "
                    f"forward={live_head_alignment['scene_forward'].tolist()} "
                    f"right={live_head_alignment['scene_right'].tolist()} "
                    f"det={live_head_alignment['basis_det']:.5f} "
                    f"ortho_err={live_head_alignment['basis_orthogonality_error']:.6f}",
                    flush=True,
                )
                immersive_controller_basis_state = (
                    self._make_immersive_controller_basis_state(
                        live_head_alignment["basis"],
                        intrinsic,
                    )
                )
                self._log_live_openxr_controller_info(
                    "[live_openxr_controller] immersive controller handedness validation "
                    "pending until both controllers have valid grip poses",
                )
                (
                    initial_left_eye_pose_world,
                    initial_right_eye_pose_world,
                    head_pose_state,
                ) = self._update_immersive_head_pose_state(
                    current_sample,
                    live_head_alignment,
                    bootstrap_output["head_pose_state"],
                    frame_index=0,
                )
                valid_eye_poses = [
                    pose
                    for pose in (
                        initial_left_eye_pose_world,
                        initial_right_eye_pose_world,
                    )
                    if pose is not None
                ]
                if not valid_eye_poses:
                    raise RuntimeError(
                        "Immersive mode needs at least one valid eye pose from the Quest runtime."
                    )
                initial_left_intrinsic = (
                    self._eye_sample_intrinsic(current_sample.left_eye, eye_width, eye_height)
                    if current_sample.left_eye is not None
                    and current_sample.left_eye.pose_valid
                    else None
                )
                initial_right_intrinsic = (
                    self._eye_sample_intrinsic(current_sample.right_eye, eye_width, eye_height)
                    if current_sample.right_eye is not None
                    and current_sample.right_eye.pose_valid
                    else None
                )
                bootstrap_output.update(
                    {
                        "head_pose_state": head_pose_state,
                        "live_head_alignment": live_head_alignment,
                        "immersive_controller_basis_state": immersive_controller_basis_state,
                        "initial_left_eye_pose_world": initial_left_eye_pose_world,
                        "initial_right_eye_pose_world": initial_right_eye_pose_world,
                        "initial_left_intrinsic": initial_left_intrinsic,
                        "initial_right_intrinsic": initial_right_intrinsic,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "build_layout":
                valid_eye_poses = [
                    pose
                    for pose in (
                        bootstrap_output["initial_left_eye_pose_world"],
                        bootstrap_output["initial_right_eye_pose_world"],
                    )
                    if pose is not None
                ]
                head_position = np.mean(
                    [pose[:3, 3] for pose in valid_eye_poses], axis=0
                ).astype(np.float32)
                head_forward = np.mean(
                    [self._eye_forward_world(pose) for pose in valid_eye_poses],
                    axis=0,
                ).astype(np.float32)
                forward_norm = float(np.linalg.norm(head_forward))
                if forward_norm < 1e-5:
                    head_forward = np.array([0.0, 1.0, 0.0], dtype=np.float32)
                else:
                    head_forward /= forward_norm
                layout = make_simple_lab_layout(
                    head_position,
                    head_forward,
                    scene_up=bootstrap_output["live_head_alignment"]["scene_up"],
                )
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "layout_ready",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="layout_ready",
                    startup_timeline=startup_timeline,
                    force=True,
                )
                bootstrap_output["layout"] = layout
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "apply_scene_layout_and_check_readback_mode":
                scene_renderer = bootstrap_output["scene_renderer"]
                layout = bootstrap_output["layout"]
                scene_renderer.set_layout(layout)
                scene_execute_renderer = scene_renderer
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "scene_layout_applied",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="scene_layout_applied",
                    startup_timeline=startup_timeline,
                )
                main_renderer_readback_mode = str(scene_renderer.pyrender_readback_mode())
                main_renderer_readback_reason = scene_renderer.pyrender_readback_reason()
                print(
                    f"[quest_display] main_renderer_readback_mode={main_renderer_readback_mode}",
                    flush=True,
                )
                if main_renderer_readback_reason:
                    print(
                        f"[quest_display] main_renderer_readback_reason={main_renderer_readback_reason}",
                        flush=True,
                    )
                if main_renderer_readback_mode != "gl_cuda_interop":
                    raise RuntimeError(
                        "Quest immersive runtime requires pyrender_readback_mode=gl_cuda_interop "
                        "so scene/background/table compose stays tensor-only."
                    )
                bootstrap_output["scene_execute_renderer"] = scene_execute_renderer
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "validate_table_alignment_and_log_layout":
                scene_renderer = bootstrap_output["scene_renderer"]
                layout = bootstrap_output["layout"]
                table_alignment_debug = scene_renderer.table_alignment_debug()
                table_surface_center_world = self._scene_table_surface_center_world(layout)
                if table_alignment_debug is not None:
                    collider_top_plane_height = float(
                        table_alignment_debug["collider_top_plane_height"]
                    )
                    world_surface_plane_height = float(
                        table_alignment_debug["world_surface_plane_height"]
                    )
                    table_surface_center_world = np.asarray(
                        table_alignment_debug["world_surface_center"],
                        dtype=np.float32,
                    )
                    if (
                        abs(world_surface_plane_height - collider_top_plane_height)
                        > self.IMMERSIVE_STARTUP_PLANE_EPS
                    ):
                        raise RuntimeError(
                            "Immersive scene table alignment validation failed: "
                            f"{table_alignment_debug}"
                        )
                    print(
                        "[quest_display] table alignment: "
                        f"asset_transform={table_alignment_debug['asset_transform']} "
                        f"surface_normal={table_alignment_debug['world_surface_normal']} "
                        f"normal_alignment={table_alignment_debug['surface_normal_alignment']:.4f} "
                        f"surface_center={table_alignment_debug['world_surface_center']} "
                        f"surface_plane={world_surface_plane_height:.4f} "
                        f"collider_plane={collider_top_plane_height:.4f} "
                        f"active_table_patches={table_alignment_debug.get('active_table_support_patch_count', 'n/a')} "
                        f"support_slabs={table_alignment_debug.get('support_slab_count', 'n/a')} "
                        f"blocker_boxes={table_alignment_debug.get('blocker_box_count', 'n/a')} "
                        f"collider_boxes={table_alignment_debug.get('collider_box_count', 'n/a')}",
                        flush=True,
                    )
                    print(
                        "[quest_display] table timewarp partition: "
                        f"table_component_ids={table_alignment_debug.get('table_render_component_ids', [])} "
                        "background_excludes_active_table="
                        f"{int(bool(table_alignment_debug.get('background_excludes_active_table', False)))} "
                        "table_bounds_source="
                        f"{table_alignment_debug.get('table_render_bounds_source', 'unknown')} "
                        "table_render_bounds="
                        f"{table_alignment_debug.get('table_render_world_bounds', 'n/a')}",
                        flush=True,
                    )
                print(
                    "[quest_display] immersive layout: "
                    f"head_position={np.mean([pose[:3, 3] for pose in [bootstrap_output['initial_left_eye_pose_world'], bootstrap_output['initial_right_eye_pose_world']] if pose is not None], axis=0).astype(np.float32).tolist()} "
                    f"table_top_center={layout.table_top_center.tolist()}",
                    flush=True,
                )
                bootstrap_output["table_surface_center_world"] = table_surface_center_world
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "apply_spawn_shift":
                obj_init_vertices = bootstrap_output["obj_init_vertices"]
                spawn_shift = self._compute_scene_spawn_shift(
                    obj_init_vertices,
                    bootstrap_output["table_surface_center_world"],
                )
                spawn_shift = spawn_shift.to(device=cfg.device, dtype=torch.float32)
                obj_init_vertices = obj_init_vertices + spawn_shift
                recorded_base_target = bootstrap_output["recorded_base_target"] + spawn_shift
                gaussians._xyz = gaussians._xyz + spawn_shift
                recorded_anchor_centers = [
                    center + spawn_shift
                    for center in bootstrap_output["recorded_anchor_centers"]
                ]
                original_controller_source_anchor_centers = [
                    center + spawn_shift
                    for center in bootstrap_output["original_controller_source_anchor_centers"]
                ]
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "spawn_shift_done",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="spawn_shift_done",
                    startup_timeline=startup_timeline,
                )
                bootstrap_output.update(
                    {
                        "spawn_shift": spawn_shift,
                        "obj_init_vertices": obj_init_vertices,
                        "recorded_base_target": recorded_base_target,
                        "recorded_anchor_centers": recorded_anchor_centers,
                        "original_controller_source_anchor_centers": original_controller_source_anchor_centers,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "build_center_view_and_resolve_rope_endpoints":
                immersive_center_eye_pose_world, immersive_center_intrinsic = (
                    self._build_immersive_center_scene_view(
                        bootstrap_output["initial_left_eye_pose_world"],
                        bootstrap_output["initial_right_eye_pose_world"],
                        bootstrap_output["initial_left_intrinsic"],
                        bootstrap_output["initial_right_intrinsic"],
                    )
                )
                immersive_center_w2c = self._camera_pose_world_to_cv_w2c(
                    immersive_center_eye_pose_world
                )
                controller_predefined_anchor_defs, rope_endpoint_naming_debug = (
                    self._resolve_rope_endpoint_anchor_defs(
                        bootstrap_output["controller_predefined_anchor_defs"],
                        immersive_center_intrinsic,
                        immersive_center_w2c,
                    )
                )
                if self._is_rope_family_case(rope_endpoint_naming_debug.get("case_name")):
                    print(
                        "[quest_display] immersive rope endpoint naming: "
                        f"endpoint_projected_x={rope_endpoint_naming_debug['endpoint_projected_x']} "
                        f"naming_valid={int(bool(rope_endpoint_naming_debug['naming_valid']))} "
                        f"fallback={int(bool(rope_endpoint_naming_debug['fallback_used']))}",
                        flush=True,
                    )
                bootstrap_output.update(
                    {
                        "controller_predefined_anchor_defs": controller_predefined_anchor_defs,
                        "immersive_center_intrinsic": immersive_center_intrinsic,
                        "immersive_center_w2c": immersive_center_w2c,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "assign_controller_sources_and_default_anchor_names":
                startup_controller_source_assignment = (
                    self._assign_startup_controller_sources_by_screen_x(
                        bootstrap_output["original_controller_source_masks"],
                        bootstrap_output["original_controller_source_anchor_centers"],
                        bootstrap_output["immersive_center_intrinsic"],
                        bootstrap_output["immersive_center_w2c"],
                        recorded_anchor_centers=bootstrap_output["recorded_anchor_centers"],
                        assignment_camera="immersive_center_view",
                    )
                )
                original_controller_source_masks = startup_controller_source_assignment[
                    "controller_source_masks"
                ]
                original_controller_source_anchor_centers = (
                    startup_controller_source_assignment[
                        "controller_source_anchor_centers"
                    ]
                )
                recorded_anchor_centers = startup_controller_source_assignment[
                    "recorded_anchor_centers"
                ]
                self._log_startup_controller_source_assignment(
                    "[quest_display] immersive",
                    startup_controller_source_assignment,
                )
                startup_predefined_anchor_states = (
                    self._compute_predefined_interaction_anchor_states(
                        bootstrap_output["controller_predefined_anchor_defs"],
                        bootstrap_output["obj_init_vertices"],
                    )
                )
                resolved_default_anchor_names, anchor_mapping_debug = (
                    self._resolve_case_default_controller_anchor_names(
                        startup_predefined_anchor_states,
                        original_controller_source_anchor_centers,
                        bootstrap_output["immersive_center_intrinsic"],
                        bootstrap_output["immersive_center_w2c"],
                    )
                )
                self._log_case_controller_anchor_mapping(
                    "[quest_display] immersive",
                    anchor_mapping_debug,
                )
                self._log_live_openxr_controller_info(
                    "[live_openxr_controller] immersive controller case profile: "
                    f"case={live_controller_case_profile['case_name']} "
                    "default_translation_scale="
                    f"{live_controller_case_profile['controller_translation_scale_default']:.2f} "
                    "translation_scale_multiplier="
                    f"{live_controller_case_profile['controller_translation_scale_multiplier']:.2f} "
                    "effective_translation_scale="
                    f"{live_controller_case_profile['controller_translation_scale']:.2f} "
                    f"post_select_grab_mode={live_controller_case_profile['post_select_grab_mode']}",
                )
                bootstrap_output.update(
                    {
                        "original_controller_source_masks": original_controller_source_masks,
                        "original_controller_source_anchor_centers": original_controller_source_anchor_centers,
                        "recorded_anchor_centers": recorded_anchor_centers,
                        "resolved_default_anchor_names": resolved_default_anchor_names,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "build_two_point_runtime_and_batch_buffers":
                two_point_runtime = self._build_two_point_live_controller_runtime(
                    bootstrap_output["obj_init_vertices"],
                    bootstrap_output["trained_spring_Y_for_sim"],
                    bootstrap_output["original_controller_source_masks"],
                    bootstrap_output["original_controller_source_anchor_centers"],
                    bootstrap_output["controller_predefined_anchor_defs"],
                    default_anchor_names=bootstrap_output["resolved_default_anchor_names"],
                )
                controller_runtime_base_target = two_point_runtime[
                    "controller_rest_points"
                ].clone()
                controller_source_masks = two_point_runtime["controller_source_masks"]
                controller_source_anchor_centers = two_point_runtime[
                    "controller_source_anchor_centers"
                ]
                init_springs_for_sim = two_point_runtime["init_springs"]
                init_rest_lengths_for_sim = two_point_runtime["init_rest_lengths"]
                trained_spring_Y_for_sim = two_point_runtime["spring_y"]
                controller_attachment_metadata = self._build_controller_attachment_metadata(
                    init_springs_for_sim,
                    init_rest_lengths_for_sim,
                    self.num_all_points,
                    controller_source_masks,
                )
                for source, runtime_meta in two_point_runtime["source_runtime"].items():
                    controller_attachment_metadata[source].update(runtime_meta)
                controller_attachment_metadata = (
                    self._canonicalize_rope_family_controller_attachment_metadata(
                        controller_attachment_metadata,
                        default_anchor_names=bootstrap_output["resolved_default_anchor_names"],
                    )
                )
                ctrl_init_vertices = controller_runtime_base_target
                n_vert_single_obj = bootstrap_output["obj_init_vertices"].shape[0]
                n_vert_single_ctrl = ctrl_init_vertices.shape[0]
                n_springs_single_obj = int(self.num_object_springs)
                n_spring_single_ctrl = int(
                    init_springs_for_sim.shape[0] - self.num_object_springs
                )
                base_ctrl_vert_offset = n_vert_single_obj
                self.batch_init_vertices = torch.cat(
                    [bootstrap_output["obj_init_vertices"], ctrl_init_vertices], dim=0
                )
                self.batch_init_velocities = (
                    self.init_velocities.clone()
                    if self.init_velocities is not None
                    else None
                )
                self.batch_controller_points = controller_runtime_base_target.unsqueeze(0).repeat(
                    self.frame_len, 1, 1
                )
                bootstrap_output.update(
                    {
                        "controller_runtime_base_target": controller_runtime_base_target,
                        "controller_source_masks": controller_source_masks,
                        "controller_source_anchor_centers": controller_source_anchor_centers,
                        "trained_spring_Y_for_sim": trained_spring_Y_for_sim,
                        "init_springs_for_sim": init_springs_for_sim,
                        "init_rest_lengths_for_sim": init_rest_lengths_for_sim,
                        "controller_attachment_metadata": controller_attachment_metadata,
                        "base_ctrl_vert_offset": base_ctrl_vert_offset,
                        "n_vert_single_obj": n_vert_single_obj,
                        "n_vert_single_ctrl": n_vert_single_ctrl,
                        "n_springs_single_obj": n_springs_single_obj,
                        "n_spring_single_ctrl": n_spring_single_ctrl,
                    }
                )
                _complete_substage(substage_name, stage_index=2)
                if not force:
                    return current_sample
                continue

            if substage_name == "init_simulator":
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "sim_init_begin",
                    immersive_bridge,
                )
                self.simulator = SpringMassSystemWarp(
                    init_springs=bootstrap_output["init_springs_for_sim"],
                    init_rest_lengths=bootstrap_output["init_rest_lengths_for_sim"],
                    init_masses=startup_context["init_masses_for_sim"],
                    init_masks=self.init_masks,
                    init_vertices=self.batch_init_vertices,
                    init_velocities=self.batch_init_velocities,
                    dt=cfg.dt,
                    num_substeps=cfg.num_substeps,
                    dashpot_damping=cfg.dashpot_damping,
                    drag_damping=cfg.drag_damping,
                    collision_dist=cfg.collision_dist,
                    reverse_z=cfg.reverse_z,
                    spring_Y_max=cfg.spring_Y_max,
                    spring_Y_min=cfg.spring_Y_min,
                    self_collision=cfg.self_collision,
                    collide_elas=startup_context["trained_collide_elas"],
                    collide_fric=startup_context["trained_collide_fric"],
                    collide_object_elas=startup_context["trained_collide_object_elas"],
                    collide_object_fric=startup_context["trained_collide_object_fric"],
                    spring_Y=bootstrap_output["trained_spring_Y_for_sim"],
                    object_massnodes_total=int(bootstrap_output["base_ctrl_vert_offset"]),
                    object_massnodes_single=int(bootstrap_output["n_vert_single_obj"]),
                    object_springs_total=int(bootstrap_output["n_springs_single_obj"]),
                    object_springs_single=int(bootstrap_output["n_springs_single_obj"]),
                    controller_massnodes_single=int(bootstrap_output["n_vert_single_ctrl"]),
                    controller_springs_single=int(bootstrap_output["n_spring_single_ctrl"]),
                    controller_rest_location=self.batch_controller_points[0],
                    number_of_instance=1,
                    use_ground_plane=False,
                )
                self.simulator.set_init_state(
                    self.simulator.wp_init_vertices, self.simulator.wp_init_velocities
                )
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "sim_init_done",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="sim_init_done",
                    startup_timeline=startup_timeline,
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "build_rotation_cache":
                prev_x = wp.to_torch(
                    self.simulator.wp_states[0].wp_x, requires_grad=False
                ).clone()
                current_pos = gaussians.get_xyz
                current_rot = gaussians.get_rotation
                relations_single = get_topk_indices(prev_x, K=3)
                weights_single, weights_indices_single = knn_weights_sparse(
                    prev_x,
                    current_pos,
                    K=3,
                )
                rotation_cache = build_rotation_reuse_cache(
                    weights_indices=weights_indices_single,
                    weights=weights_single,
                    relations=relations_single,
                    mass_nodes_rest=prev_x,
                    gaussians_xyz_rest=current_pos,
                    gaussians_quat_rest=current_rot,
                    device=cfg.device,
                    mass_node_per_instance=int(bootstrap_output["n_vert_single_obj"]),
                    gaussians_per_instance=current_pos.shape[0],
                    number_of_instance=1,
                )
                spawn_support_center = self._validate_scene_spawn_alignment(
                    self.batch_init_vertices[: self.num_all_points],
                    bootstrap_output["layout"],
                    context="spawn shift",
                    table_surface_center_world=bootstrap_output["table_surface_center_world"],
                )
                _, _, spawn_xy_error, spawn_z_error = self._scene_spawn_alignment_metrics(
                    self.batch_init_vertices[: self.num_all_points],
                    bootstrap_output["layout"],
                    table_surface_center_world=bootstrap_output["table_surface_center_world"],
                )
                print(
                    "[quest_display] immersive spawn shift: "
                    f"shift={bootstrap_output['spawn_shift'].detach().cpu().numpy().tolist()} "
                    f"support_center={spawn_support_center.detach().cpu().numpy().tolist()} "
                    f"xy_error={spawn_xy_error:.4f} z_error={spawn_z_error:.4f}",
                    flush=True,
                )
                bootstrap_output["rotation_cache"] = rotation_cache
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "prime_live_controller_runtime_and_handedness":
                live_controller_alignment = None
                live_controller_alignment_mode = "unset"
                controller_runtime_state = self._update_live_controller_runtime_from_sample(
                    current_sample,
                    live_controller_alignment,
                    live_controller_alignment_mode,
                    bootstrap_output["controller_source_anchor_centers"],
                    w2c,
                    controller_select_state_cache,
                    controller_select_hold_state,
                    controller_select_hold_state_cache,
                    controller_anchor_cycle_state_cache,
                    controller_anchor_reset_state_cache,
                    controller_snap_state_cache,
                    controller_snap_edge_cache,
                    controller_exit_hold_state,
                    basis_override=bootstrap_output["immersive_controller_basis_state"][
                        "basis"
                    ],
                    collect_reset_edges=False,
                    collect_exit_holds=False,
                    alignment_pose_role="grip",
                    controller_position_pose_role="grip",
                    controller_ray_pose_role="aim",
                )
                (
                    controller_runtime_state,
                    immersive_controller_basis_state,
                ) = self._maybe_resolve_immersive_controller_handedness(
                    current_sample,
                    controller_runtime_state,
                    bootstrap_output["immersive_controller_basis_state"],
                    bootstrap_output["controller_source_anchor_centers"],
                    intrinsic,
                    w2c,
                    controller_interaction_state=controller_interaction_state,
                    alignment_pose_role="grip",
                    controller_position_pose_role="grip",
                    controller_ray_pose_role="aim",
                )
                live_controller_alignment = controller_runtime_state["alignment"]
                live_controller_alignment_mode = controller_runtime_state["alignment_mode"]
                if live_controller_alignment is None:
                    self._log_live_openxr_controller_info(
                        "[live_openxr_controller] immersive controller alignment still pending "
                        "after scene spawn shift",
                    )
                else:
                    self._log_live_openxr_controller_info(
                        "[live_openxr_controller] immersive controller alignment ready "
                        f"after scene spawn shift mode={live_controller_alignment_mode}",
                    )
                current_live_left_controller = controller_runtime_state["left_controller"]
                current_live_right_controller = controller_runtime_state["right_controller"]
                self._log_live_openxr_controller_info(
                    "[live_openxr_controller] immersive using shared 2D controller runtime",
                )
                last_left_eye_pose_world = bootstrap_output["initial_left_eye_pose_world"]
                last_right_eye_pose_world = bootstrap_output["initial_right_eye_pose_world"]
                if last_left_eye_pose_world is None:
                    last_left_eye_pose_world = last_right_eye_pose_world
                if last_right_eye_pose_world is None:
                    last_right_eye_pose_world = last_left_eye_pose_world
                bootstrap_output.update(
                    {
                        "immersive_controller_basis_state": immersive_controller_basis_state,
                        "current_live_left_controller": current_live_left_controller,
                        "current_live_right_controller": current_live_right_controller,
                        "live_controller_alignment": live_controller_alignment,
                        "live_controller_alignment_mode": live_controller_alignment_mode,
                        "last_left_eye_pose_world": last_left_eye_pose_world,
                        "last_right_eye_pose_world": last_right_eye_pose_world,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "prepare_balanced_runtime_state":
                bootstrap_output["worker_validation_request"] = None
                bootstrap_output["balanced_warmup_kwargs"] = None
                bootstrap_output["balanced_main_warmup_paths"] = []
                bootstrap_output["balanced_worker_warmup_paths"] = []
                if (
                    bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                ):
                    self._immersive_balanced_runtime_state = (
                        self._prepare_immersive_balanced_runtime_state(
                            bootstrap_output["layout"],
                            bootstrap_output["last_left_eye_pose_world"],
                            bootstrap_output["last_right_eye_pose_world"],
                            bootstrap_output["initial_left_intrinsic"],
                            bootstrap_output["initial_right_intrinsic"],
                            eye_width,
                            eye_height,
                            scene_width,
                            scene_height,
                            static_scene_mode=immersive_static_scene_mode,
                        )
                    )
                    self._immersive_balanced_runtime_state[
                        "support_entry_overlay_enabled"
                    ] = bool(immersive_support_entry_overlay_enabled)
                    worker_validation_request = (
                        self._build_immersive_balanced_scene_render_plan(
                            bootstrap_output["scene_renderer"],
                            None,
                            None,
                            None,
                            bootstrap_output["last_left_eye_pose_world"],
                            bootstrap_output["last_right_eye_pose_world"],
                            bootstrap_output["initial_left_intrinsic"],
                            bootstrap_output["initial_right_intrinsic"],
                            eye_width,
                            eye_height,
                            scene_width,
                            scene_height,
                            active_interaction=False,
                            render_profile_frame=None,
                        )
                    )
                    balanced_warmup_kwargs = (
                        self._build_immersive_balanced_renderer_warmup_kwargs(
                            bootstrap_output["scene_renderer"],
                            worker_validation_request,
                        )
                    )
                    bootstrap_output["worker_validation_request"] = (
                        worker_validation_request
                    )
                    bootstrap_output["balanced_warmup_kwargs"] = balanced_warmup_kwargs
                else:
                    self._immersive_balanced_runtime_state = None
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "warmup_balanced_paths_and_seed_layer_cache":
                if (
                    bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                    and bootstrap_output.get("worker_validation_request") is not None
                ):
                    balanced_main_warmup_paths = []
                    if bootstrap_output.get("balanced_warmup_kwargs") is not None:
                        balanced_main_warmup_paths = (
                            bootstrap_output["scene_renderer"].warmup_balanced_runtime_paths(
                                **bootstrap_output["balanced_warmup_kwargs"]
                            )
                        )
                    worker_validation_request = bootstrap_output["worker_validation_request"]
                    startup_layer_seed_request = {
                        eye_label: [
                            IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE,
                            IMMERSIVE_BALANCED_LAYER_FULL_BASE,
                            IMMERSIVE_BALANCED_LAYER_TABLE_BASE,
                        ]
                        for eye_label in ("left", "right")
                    }
                    if (
                        str(
                            worker_validation_request.get(
                                "static_scene_mode",
                                self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
                            )
                        ).strip().lower()
                        == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS
                    ) or (
                        str(immersive_static_scene_mode).strip().lower()
                        == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_SUPPORT_FOCUS
                    ):
                        for eye_label in ("left", "right"):
                            startup_layer_seed_request[eye_label].append(
                                IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY
                            )
                    static_scene_layer_cache = (
                        self._seed_immersive_static_scene_layer_cache(
                            renderer=bootstrap_output["scene_execute_renderer"],
                            render_plan=worker_validation_request,
                            head_pose_state=bootstrap_output["head_pose_state"],
                            requested_layers_by_eye=startup_layer_seed_request,
                        )
                    )
                    bootstrap_output["balanced_main_warmup_paths"] = (
                        balanced_main_warmup_paths
                    )
                    bootstrap_output["static_scene_layer_cache"] = (
                        static_scene_layer_cache
                    )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "start_eye_workers_if_enabled":
                balanced_eye_workers = bootstrap_output["balanced_eye_workers"]
                balanced_eye_parallel_enabled = bootstrap_output[
                    "balanced_eye_parallel_enabled"
                ]
                if (
                    bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                    and bootstrap_output.get("worker_validation_request") is not None
                    and not static_scene_overlap_requested
                ):
                    left_eye_worker = None
                    right_eye_worker = None
                    try:
                        left_eye_worker = _ImmersiveBalancedSceneEyeRenderWorker(
                            eye_label="left",
                            scene_assets_root=scene_assets_root,
                            scene_width=scene_width,
                            scene_height=scene_height,
                            lighting_mode=immersive_render_options["lighting_mode"],
                            balanced_render_backend="pyrender",
                            static_scene_mode=immersive_static_scene_mode,
                            layout=bootstrap_output["layout"],
                            cuda_device_index=int(torch.cuda.current_device()),
                        )
                        left_eye_worker.start(
                            validation_request=_build_immersive_balanced_scene_eye_request(
                                bootstrap_output["worker_validation_request"],
                                "left",
                            ),
                            warmup_kwargs=bootstrap_output["balanced_warmup_kwargs"],
                        )
                        right_eye_worker = _ImmersiveBalancedSceneEyeRenderWorker(
                            eye_label="right",
                            scene_assets_root=scene_assets_root,
                            scene_width=scene_width,
                            scene_height=scene_height,
                            lighting_mode=immersive_render_options["lighting_mode"],
                            balanced_render_backend="pyrender",
                            static_scene_mode=immersive_static_scene_mode,
                            layout=bootstrap_output["layout"],
                            cuda_device_index=int(torch.cuda.current_device()),
                        )
                        right_eye_worker.start(
                            validation_request=_build_immersive_balanced_scene_eye_request(
                                bootstrap_output["worker_validation_request"],
                                "right",
                            ),
                            warmup_kwargs=bootstrap_output["balanced_warmup_kwargs"],
                        )
                        balanced_eye_workers = {
                            "left": left_eye_worker,
                            "right": right_eye_worker,
                        }
                        balanced_eye_parallel_enabled = True
                    except Exception as exc:
                        for eye_worker in (left_eye_worker, right_eye_worker):
                            if eye_worker is None:
                                continue
                            try:
                                eye_worker.stop()
                            except Exception:
                                pass
                        balanced_eye_workers = {}
                        balanced_eye_parallel_enabled = False
                        print(
                            "[quest_display] immersive static-scene parallelism unavailable; "
                            "falling back to serial_reference: "
                            f"{type(exc).__name__}: {exc}",
                            flush=True,
                        )
                bootstrap_output["balanced_eye_workers"] = balanced_eye_workers
                bootstrap_output["balanced_eye_parallel_enabled"] = (
                    balanced_eye_parallel_enabled
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "start_static_scene_worker_if_enabled":
                static_scene_worker = bootstrap_output["static_scene_worker"]
                static_scene_overlap_enabled = bootstrap_output[
                    "static_scene_overlap_enabled"
                ]
                scene_depth_reproject_enabled = bootstrap_output[
                    "scene_depth_reproject_enabled"
                ]
                if (
                    bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                    and bootstrap_output.get("worker_validation_request") is not None
                    and static_scene_overlap_requested
                ):
                    try:
                        static_scene_worker = _ImmersiveStaticSceneRenderWorker(
                            scene_assets_root=scene_assets_root,
                            scene_width=scene_width,
                            scene_height=scene_height,
                            lighting_mode=immersive_render_options["lighting_mode"],
                            balanced_render_backend="pyrender",
                            static_scene_mode=immersive_static_scene_mode,
                            layout=bootstrap_output["layout"],
                            cuda_device_index=int(torch.cuda.current_device()),
                        )
                        worker_startup_debug = static_scene_worker.start(
                            validation_request=bootstrap_output["worker_validation_request"],
                            warmup_kwargs=bootstrap_output["balanced_warmup_kwargs"],
                        )
                        bootstrap_output["balanced_worker_warmup_paths"] = list(
                            worker_startup_debug.get("warmup_paths") or []
                        )
                        static_scene_overlap_enabled = True
                    except Exception as exc:
                        if static_scene_worker is not None:
                            try:
                                static_scene_worker.stop()
                            except Exception:
                                pass
                        static_scene_worker = None
                        static_scene_overlap_enabled = False
                        if scene_depth_reproject_requested:
                            raise RuntimeError(
                                "immersive_timewarp scene_depth_reproject requires "
                                "static-scene worker startup; "
                                f"worker_init_error={type(exc).__name__}: {exc}"
                            ) from exc
                        if framegen_requested:
                            raise RuntimeError(
                                f"immersive_framegen {immersive_framegen_mode} requires "
                                "static-scene worker startup; "
                                f"worker_init_error={type(exc).__name__}: {exc}"
                            ) from exc
                        scene_depth_reproject_enabled = False
                        print(
                            "[quest_display] immersive static-scene overlap unavailable; "
                            "falling back to serial room render: "
                            f"{type(exc).__name__}: {exc}",
                            flush=True,
                        )
                bootstrap_output["static_scene_worker"] = static_scene_worker
                bootstrap_output["static_scene_overlap_enabled"] = (
                    static_scene_overlap_enabled
                )
                bootstrap_output["scene_depth_reproject_enabled"] = (
                    scene_depth_reproject_enabled
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "prepare_colliders_support_boxes_idle_lock_and_cuda_graph":
                if bootstrap_output["active_scene_stereo_mode"] == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE:
                    print(
                        "[quest_display] immersive gaussian render: "
                        f"mode={immersive_gaussian_render_mode}",
                        flush=True,
                    )
                else:
                    print(
                        "[quest_display] immersive gaussian render: "
                        f"mode={immersive_gaussian_render_mode}",
                        flush=True,
                    )
                if (
                    static_scene_overlap_requested
                    and immersive_gaussian_render_mode == "stereo_parallel"
                ):
                    print(
                        "[quest_display] immersive gaussian render overlap path: "
                        "mode=stereo_parallel branch_b=main_thread_cuda_streams",
                        flush=True,
                    )
                if presentation_backend_enabled:
                    pipeline_source = (
                        "explicit_flag"
                        if immersive_present_pipeline_enabled
                        else "framegen_auto"
                    )
                    print(
                        "[quest_display] immersive presentation pipeline: "
                        "mode=cross_frame_present latest_wins=1 "
                        f"source={pipeline_source} backend={presentation_backend_kind}",
                        flush=True,
                    )
                self._set_scene_collider_boxes(bootstrap_output["layout"])
                if bootstrap_output["layout"].support_surface_boxes is not None:
                    support_surface_boxes_np = np.asarray(
                        bootstrap_output["layout"].support_surface_boxes,
                        dtype=np.float32,
                    )
                else:
                    support_surface_boxes_np = np.array(
                        [
                            [
                                bootstrap_output["layout"].table_box.mins,
                                bootstrap_output["layout"].table_box.maxs,
                            ],
                            [
                                bootstrap_output["layout"].floor_box.mins,
                                bootstrap_output["layout"].floor_box.maxs,
                            ],
                        ],
                        dtype=np.float32,
                    )
                support_surface_boxes_t = torch.as_tensor(
                    support_surface_boxes_np,
                    dtype=torch.float32,
                    device=cfg.device,
                )
                idle_lock_case_profile = self._idle_lock_case_profile()
                idle_lock_state = self._make_idle_lock_state()
                if self.simulator.object_collision_flag:
                    self.simulator.create_resting_case()
                self.simulator.create_cuda_graph()
                bootstrap_output.update(
                    {
                        "support_surface_boxes_t": support_surface_boxes_t,
                        "idle_lock_case_profile": idle_lock_case_profile,
                        "idle_lock_state": idle_lock_state,
                    }
                )
                _complete_substage(substage_name, stage_index=3)
                if not force:
                    return current_sample
                continue

            if substage_name == "settle_scene_rest_chunk":
                bootstrap_output.setdefault(
                    "current_target",
                    bootstrap_output["controller_runtime_base_target"].clone(),
                )
                bootstrap_output.setdefault(
                    "prev_target",
                    bootstrap_output["current_target"].clone(),
                )
                settle_state = self._advance_immersive_scene_rest_settle(
                    settle_state,
                    bootstrap_output["current_target"].clone(),
                    progress_callback=lambda reason: self._maybe_publish_immersive_startup_keepalive(
                        immersive_bridge,
                        startup_keepalive_state,
                        reason=reason,
                        startup_timeline=startup_timeline,
                    ),
                    max_steps=self.IMMERSIVE_STARTUP_SETTLE_STEPS_PER_TICK,
                )
                bootstrap_state["settle_state"] = settle_state
                if not bool(settle_state.get("done", False)):
                    return current_sample
                bootstrap_output["scene_rest_state"] = settle_state.get("last_state")
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "settled_rest_done",
                    immersive_bridge,
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "restore_settled_state_and_build_anchor_templates":
                scene_rest_state = bootstrap_output["scene_rest_state"]
                self._restore_sim_state(scene_rest_state)
                x = wp.to_torch(
                    self.simulator.wp_states[0].wp_x,
                    requires_grad=False,
                ).clone()
                current_pos, current_rot = lbs_with_rotation_reuse(
                    current_mass_nodes=x,
                    cache=bootstrap_output["rotation_cache"],
                )
                gaussians._xyz = current_pos
                gaussians._rotation = current_rot
                settled_support_center = self._validate_scene_spawn_alignment(
                    x[: self.num_all_points],
                    bootstrap_output["layout"],
                    context="settled rest state",
                    table_surface_center_world=bootstrap_output["table_surface_center_world"],
                )
                _, _, settled_xy_error, settled_z_error = self._scene_spawn_alignment_metrics(
                    x[: self.num_all_points],
                    bootstrap_output["layout"],
                    table_surface_center_world=bootstrap_output["table_surface_center_world"],
                )
                settled_bounds_min = (
                    x[: self.num_all_points].min(dim=0).values.detach().cpu().numpy().tolist()
                )
                settled_bounds_max = (
                    x[: self.num_all_points].max(dim=0).values.detach().cpu().numpy().tolist()
                )
                print(
                    "[quest_display] immersive settled rest state: "
                    f"support_center={settled_support_center.detach().cpu().numpy().tolist()} "
                    f"xy_error={settled_xy_error:.4f} z_error={settled_z_error:.4f} "
                    f"bounds_min={settled_bounds_min} bounds_max={settled_bounds_max}",
                    flush=True,
                )
                startup_support_fraction = self._scene_support_fraction(
                    x[: self.num_all_points],
                    bootstrap_output["support_surface_boxes_t"],
                    bootstrap_output["layout"].scene_up,
                )
                self._set_idle_lock_state(
                    bootstrap_output["idle_lock_state"],
                    scene_rest_state,
                    x[: self.num_all_points],
                    action="seeded",
                    reason="startup_validated",
                    support_fraction=startup_support_fraction,
                )
                controller_anchor_templates = (
                    self._build_predefined_controller_anchor_templates(
                        bootstrap_output["controller_runtime_base_target"],
                        x[: self.num_all_points],
                        bootstrap_output["controller_source_masks"],
                        bootstrap_output["controller_source_anchor_centers"],
                        bootstrap_output["controller_attachment_metadata"],
                        bootstrap_output["controller_predefined_anchor_defs"],
                    )
                )
                bootstrap_output.update(
                    {
                        "x": x,
                        "controller_anchor_templates": controller_anchor_templates,
                    }
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "validate_startup_scene_mode":
                active_scene_stereo_mode = bootstrap_output["active_scene_stereo_mode"]
                startup_scene_validation_mode = "assembled_scene"
                if active_scene_stereo_mode == "reproject_from_center":
                    reproject_valid, reproject_debug = (
                        self._validate_immersive_reprojected_scene_startup(
                            bootstrap_output["layout"],
                            bootstrap_output["scene_renderer"],
                            current_sample.left_eye,
                            current_sample.right_eye,
                            bootstrap_output["last_left_eye_pose_world"],
                            bootstrap_output["last_right_eye_pose_world"],
                            eye_width,
                            eye_height,
                            scene_width,
                            scene_height,
                            gaussians,
                            shared_scene_compose_cache=shared_scene_compose_cache,
                            reproject_caches=shared_scene_reproject_caches,
                            scene_stereo_mode=active_scene_stereo_mode,
                        )
                    )
                    print(
                        "[quest_display] immersive reprojection startup validation: "
                        + str(reproject_debug),
                        flush=True,
                    )
                    if not reproject_valid:
                        active_scene_stereo_mode = "per_eye"
                        startup_scene_validation_mode = "assembled_per_eye_fallback"
                        print(
                            "[quest_display] immersive reprojection startup validation failed; "
                            "falling back to per_eye room rendering for this run",
                            flush=True,
                        )
                    else:
                        startup_scene_validation_mode = (
                            "assembled_reproject_from_center"
                        )
                elif (
                    active_scene_stereo_mode
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                ):
                    balanced_side_wall_mode = "disabled"
                    balanced_static_scene_mode = (
                        self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS
                    )
                    if self._immersive_balanced_runtime_state is not None:
                        balanced_side_wall_mode = str(
                            self._immersive_balanced_runtime_state.get(
                                "side_wall_mode",
                                "disabled",
                            )
                        )
                        balanced_static_scene_mode = str(
                            self._immersive_balanced_runtime_state.get(
                                "static_scene_mode",
                                self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
                            )
                        )
                    if balanced_side_wall_mode == "disabled":
                        if (
                            balanced_static_scene_mode
                            == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS
                        ):
                            startup_scene_validation_mode = (
                                "assembled_balanced_per_eye_background_table_roi"
                            )
                        elif (
                            balanced_static_scene_mode
                            == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_SUPPORT_FOCUS
                        ):
                            startup_scene_validation_mode = (
                                "assembled_balanced_per_eye_background_support_roi"
                            )
                    else:
                        balanced_edge_valid, balanced_edge_debug = (
                            self._validate_immersive_balanced_edge_warp_startup(
                                bootstrap_output["scene_renderer"],
                                current_sample.left_eye,
                                current_sample.right_eye,
                                bootstrap_output["last_left_eye_pose_world"],
                                bootstrap_output["last_right_eye_pose_world"],
                                eye_width,
                                eye_height,
                                scene_width,
                                scene_height,
                                shared_scene_compose_cache=shared_scene_compose_cache,
                                reproject_caches=shared_scene_reproject_caches,
                            )
                        )
                        print(
                            "[quest_display] immersive balanced side-strip startup validation: "
                            + str(balanced_edge_debug),
                            flush=True,
                        )
                        if not balanced_edge_valid:
                            startup_scene_validation_mode = (
                                "assembled_balanced_center_background_side_strip_replace_fallback"
                            )
                        else:
                            startup_scene_validation_mode = (
                                "assembled_balanced_center_background_side_strip_replace_table_roi"
                            )
                bootstrap_output["active_scene_stereo_mode"] = active_scene_stereo_mode
                bootstrap_output["startup_scene_validation_mode"] = (
                    startup_scene_validation_mode
                )
                _complete_substage(substage_name, stage_index=4)
                if not force:
                    return current_sample
                continue

            if substage_name == "startup_validation_prepare":
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "startup_validation_begin",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_enter",
                    startup_timeline=startup_timeline,
                    force=not force,
                )
                gaussian_compose_roi_padding = (
                    int(self.IMMERSIVE_GAUSSIAN_COMPOSE_ROI_PADDING)
                    if bootstrap_output["active_scene_stereo_mode"]
                    == self.IMMERSIVE_BALANCED_INTERNAL_STEREO_MODE
                    else None
                )
                validation_state = self._make_immersive_startup_validation_state(
                    head_alignment=bootstrap_output["live_head_alignment"],
                    layout=bootstrap_output["layout"],
                    scene_renderer=bootstrap_output["scene_renderer"],
                    left_eye_sample=current_sample.left_eye,
                    right_eye_sample=current_sample.right_eye,
                    left_eye_pose_world=bootstrap_output["last_left_eye_pose_world"],
                    right_eye_pose_world=bootstrap_output["last_right_eye_pose_world"],
                    eye_width=eye_width,
                    eye_height=eye_height,
                    gaussians=gaussians,
                    scene_stereo_mode=bootstrap_output["active_scene_stereo_mode"],
                    scene_width=scene_width,
                    scene_height=scene_height,
                )
                validation_state["gaussian_compose_roi_padding"] = (
                    gaussian_compose_roi_padding
                )
                bootstrap_state["validation_state"] = validation_state
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "startup_validation_scene_frames":
                validation_state = bootstrap_state["validation_state"]
                validation_state = self._render_immersive_startup_validation_scene_frames(
                    validation_state,
                    layout=bootstrap_output["layout"],
                    scene_renderer=bootstrap_output["scene_renderer"],
                    scene_execute_renderer=bootstrap_output["scene_execute_renderer"],
                    reproject_caches=shared_scene_reproject_caches,
                )
                bootstrap_state["validation_state"] = validation_state
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_scene_frames_ready",
                    startup_timeline=startup_timeline,
                    force=not force,
                )
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "startup_validation_left_eye":
                validation_state = bootstrap_state["validation_state"]
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_eye_left_begin",
                    startup_timeline=startup_timeline,
                    force=not force,
                )
                validation_state = self._process_immersive_startup_validation_eye(
                    validation_state,
                    "left",
                    scene_renderer=bootstrap_output["scene_renderer"],
                    gaussians=gaussians,
                    render_pipe=render_pipe,
                    background_black=background_black,
                    background_white=background_white,
                    gaussian_compose_roi_padding=validation_state.get(
                        "gaussian_compose_roi_padding"
                    ),
                )
                bootstrap_state["validation_state"] = validation_state
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "startup_validation_right_eye":
                validation_state = bootstrap_state["validation_state"]
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_eye_right_begin",
                    startup_timeline=startup_timeline,
                    force=not force,
                )
                validation_state = self._process_immersive_startup_validation_eye(
                    validation_state,
                    "right",
                    scene_renderer=bootstrap_output["scene_renderer"],
                    gaussians=gaussians,
                    render_pipe=render_pipe,
                    background_black=background_black,
                    background_white=background_white,
                    gaussian_compose_roi_padding=validation_state.get(
                        "gaussian_compose_roi_padding"
                    ),
                )
                bootstrap_state["validation_state"] = validation_state
                _complete_substage(substage_name)
                if not force:
                    return current_sample
                continue

            if substage_name == "startup_validation_finalize":
                validation_state = self._finalize_immersive_startup_validation_state(
                    bootstrap_state["validation_state"],
                    debug_output_dir=diagnostic_view_render_path,
                    save_success_bundle=profile_enabled,
                )
                startup_render_debug = validation_state["startup_render_debug"]
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_complete",
                    startup_timeline=startup_timeline,
                    force=not force,
                )
                self._record_immersive_startup_milestone(
                    startup_timeline,
                    "startup_validation_done",
                    immersive_bridge,
                )
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    startup_keepalive_state,
                    reason="startup_validation_done",
                    startup_timeline=startup_timeline,
                )
                startup_render_debug["requested_scene_stereo_mode"] = (
                    immersive_render_options["scene_stereo_mode"]
                )
                startup_render_debug["active_scene_stereo_mode"] = (
                    bootstrap_output["active_scene_stereo_mode"]
                )
                startup_render_debug["startup_scene_validation_mode"] = (
                    bootstrap_output["startup_scene_validation_mode"]
                )
                immersive_compose_mode = str(
                    startup_render_debug.get("recommended_compose_mode", "depth_aware")
                )
                print(
                    "[quest_display] immersive startup render validation: "
                    + str(startup_render_debug),
                    flush=True,
                )
                if immersive_compose_mode != "depth_aware":
                    print(
                        "[quest_display] immersive startup compose validation failed; "
                        "falling back to alpha_overlay object compositing for this run",
                        flush=True,
                    )
                bootstrap_state["validation_state"] = validation_state
                bootstrap_output["startup_render_debug"] = startup_render_debug
                bootstrap_output["immersive_compose_mode"] = immersive_compose_mode
                bootstrap_state["stage_index"] = 5
                bootstrap_state["complete"] = True
                substage_index += 1
                _refresh_substage_cursor()
                return bootstrap_output["initial_sample"]

            raise RuntimeError(
                f"Unknown immersive startup bootstrap substage: {substage_name}"
            )

        bootstrap_state["stage_index"] = 5
        bootstrap_state["complete"] = True
        _refresh_substage_cursor()
        return bootstrap_output["initial_sample"]

    def _set_immersive_startup_keepalive_frames(
        self,
        keepalive_state,
        *,
        left_frame,
        right_frame=None,
        preview_frame=None,
    ):
        if keepalive_state is None:
            return
        if left_frame is None:
            return
        if left_frame.dtype != torch.uint8:
            left_frame = left_frame.clamp(0.0, 255.0).to(torch.uint8)
        if right_frame is None:
            right_frame = left_frame
        if right_frame.dtype != torch.uint8:
            right_frame = right_frame.clamp(0.0, 255.0).to(torch.uint8)
        if preview_frame is None:
            preview_frame = left_frame
        elif torch.is_tensor(preview_frame) and preview_frame.dtype != torch.uint8:
            preview_frame = preview_frame.clamp(0.0, 255.0).to(torch.uint8)
        keepalive_state["left_frame"] = left_frame.clone()
        keepalive_state["right_frame"] = right_frame.clone()
        keepalive_state["preview_frame"] = (
            None if preview_frame is None else preview_frame.clone()
        )

    def _make_immersive_startup_keepalive_state(
        self,
        eye_width,
        eye_height,
        *,
        left_frame=None,
        right_frame=None,
        preview_frame=None,
        presentation_mode="stereo_fullscreen",
    ):
        color = torch.tensor(
            self.IMMERSIVE_STARTUP_KEEPALIVE_RGBA,
            dtype=torch.uint8,
            device=cfg.device,
        )
        frame = color.view(1, 1, 4).expand(eye_height, eye_width, 4).contiguous().clone()
        keepalive_state = {
            "left_frame": frame,
            "right_frame": frame.clone(),
            "preview_frame": frame.clone(),
            "last_publish_time": None,
            "publish_count": 0,
            "enabled": True,
            "preview_present_callback": None,
            "presentation_mode": str(presentation_mode),
        }
        if left_frame is not None:
            self._set_immersive_startup_keepalive_frames(
                keepalive_state,
                left_frame=left_frame,
                right_frame=right_frame,
                preview_frame=preview_frame,
            )
        return keepalive_state

    def _immersive_controller_select_active(self, controller_sample):
        if controller_sample is None:
            return False
        if not bool(getattr(controller_sample, "select_available", False)):
            return False
        return bool(getattr(controller_sample, "select_pressed", False)) or (
            float(getattr(controller_sample, "select_value", 0.0))
            >= float(self.LIVE_CONTROLLER_SELECT_START_THRESHOLD)
        )

    def _immersive_sample_any_select_active(self, sample):
        if sample is None:
            return False
        return self._immersive_controller_select_active(
            getattr(sample, "left", None)
        ) or self._immersive_controller_select_active(getattr(sample, "right", None))

    def _run_immersive_startup_tutorial(
        self,
        immersive_bridge,
        keepalive_state,
        initial_sample,
        tutorial_frames,
        *,
        startup_timeline=None,
        progress_callback=None,
    ):
        tutorial_frames = [frame for frame in tutorial_frames if torch.is_tensor(frame)]
        if immersive_bridge is None or keepalive_state is None or not tutorial_frames:
            return initial_sample

        last_sample = initial_sample
        previous_select_active = self._immersive_sample_any_select_active(initial_sample)
        slide_index = 0
        total_slide_count = len(tutorial_frames)
        self._set_immersive_startup_keepalive_frames(
            keepalive_state,
            left_frame=tutorial_frames[slide_index],
        )
        print(
            "[quest_display] immersive tutorial slide: "
            f"index={slide_index + 1}/{total_slide_count}",
            flush=True,
        )
        self._maybe_publish_immersive_startup_keepalive(
            immersive_bridge,
            keepalive_state,
            reason=f"tutorial_slide_{slide_index + 1}",
            startup_timeline=startup_timeline,
            force=True,
        )

        while True:
            min_sample_id = int(getattr(last_sample, "sample", -1))
            sample = immersive_bridge.wait_for_newer_sample(
                min_sample_id=min_sample_id,
                timeout_s=float(self.IMMERSIVE_TUTORIAL_SAMPLE_POLL_INTERVAL_SECONDS),
            )
            if sample is None:
                if progress_callback is not None:
                    progressed_sample = progress_callback(last_sample, force=False)
                    if progressed_sample is not None:
                        last_sample = progressed_sample
                self._maybe_publish_immersive_startup_keepalive(
                    immersive_bridge,
                    keepalive_state,
                    reason=f"tutorial_keepalive_{slide_index + 1}",
                    startup_timeline=startup_timeline,
                )
                continue

            last_sample = sample
            select_active = self._immersive_sample_any_select_active(sample)
            select_edge = bool(select_active and not previous_select_active)
            previous_select_active = select_active
            if not select_edge:
                if progress_callback is not None:
                    progressed_sample = progress_callback(last_sample, force=False)
                    if progressed_sample is not None:
                        last_sample = progressed_sample
                continue
            if slide_index >= total_slide_count - 1:
                break

            slide_index += 1
            self._set_immersive_startup_keepalive_frames(
                keepalive_state,
                left_frame=tutorial_frames[slide_index],
            )
            print(
                "[quest_display] immersive tutorial slide: "
                f"index={slide_index + 1}/{total_slide_count}",
                flush=True,
            )
            self._maybe_publish_immersive_startup_keepalive(
                immersive_bridge,
                keepalive_state,
                reason=f"tutorial_slide_{slide_index + 1}",
                startup_timeline=startup_timeline,
                force=True,
            )

        print(
            "[quest_display] immersive tutorial complete: "
            f"slides={total_slide_count}",
            flush=True,
        )
        return last_sample

    def _maybe_publish_immersive_startup_keepalive(
        self,
        immersive_bridge,
        keepalive_state,
        *,
        reason,
        startup_timeline=None,
        force=False,
    ):
        if keepalive_state is None or not keepalive_state.get("enabled", False):
            return False
        now = time.perf_counter()
        last_publish_time = keepalive_state.get("last_publish_time")
        if (
            not force
            and last_publish_time is not None
            and (now - last_publish_time)
            < self.IMMERSIVE_STARTUP_KEEPALIVE_INTERVAL_SECONDS
        ):
            return False
        publish_ok, publish_stats = immersive_bridge.publish_stereo_frames(
            keepalive_state["left_frame"],
            keepalive_state["right_frame"],
            presentation_mode=keepalive_state.get(
                "presentation_mode",
                "stereo_fullscreen",
            ),
        )
        keepalive_state["last_publish_time"] = now
        preview_present_callback = keepalive_state.get("preview_present_callback")
        preview_frame = keepalive_state.get("preview_frame")
        if publish_ok:
            keepalive_state["publish_count"] = int(keepalive_state.get("publish_count", 0)) + 1
            if preview_present_callback is not None and preview_frame is not None:
                preview_present_callback(preview_frame)
        bridge_state = self._immersive_bridge_process_state(immersive_bridge)
        total_wall_ms = float(publish_stats.get("total_wall", 0.0)) * 1000.0
        print(
            "[quest_display] immersive startup keepalive: "
            f"reason={reason} publish_ok={int(bool(publish_ok))} "
            f"count={keepalive_state.get('publish_count', 0)} "
            f"bridge={bridge_state} publish_wall_ms={total_wall_ms:.2f}",
            flush=True,
        )
        if not publish_ok:
            failure_details = self._format_immersive_startup_timeline_failure(
                startup_timeline,
                immersive_bridge,
            )
            raise RuntimeError(
                "Quest immersive bridge stopped accepting stereo frames during startup keepalive.\n"
                + (failure_details + "\n" if failure_details else "")
                + immersive_bridge.debug_summary()
            )
        return True

    def _sample_received_monotonic_s(self, sample):
        if sample is None:
            return None
        received_s = getattr(sample, "received_monotonic_s", None)
        if received_s is None:
            return None
        received_s = float(received_s)
        if not np.isfinite(received_s):
            return None
        return received_s

    def _copy_immersive_packet_value(self, value):
        if torch.is_tensor(value):
            return value.clone()
        if isinstance(value, np.ndarray):
            return value.copy()
        if isinstance(value, dict):
            return {
                key: self._copy_immersive_packet_value(subvalue)
                for key, subvalue in value.items()
            }
        if isinstance(value, list):
            return [self._copy_immersive_packet_value(item) for item in value]
        if isinstance(value, tuple):
            return tuple(self._copy_immersive_packet_value(item) for item in value)
        return copy.deepcopy(value)

    def _publish_immersive_stable_cover_frame(
        self,
        immersive_bridge,
        *,
        left_eye_frame,
        right_eye_frame,
        preview_frame=None,
        reject_source,
        backend_kind,
    ):
        if (
            immersive_bridge is None
            or not torch.is_tensor(left_eye_frame)
            or not torch.is_tensor(right_eye_frame)
        ):
            return {
                "cache_hit": False,
                "cache_missing": True,
                "publish_wall_ms": 0.0,
                "publish_stats": {},
                "preview_frame": preview_frame,
                "reject_source": str(reject_source).strip().lower(),
                "backend_kind": str(backend_kind).strip().lower(),
            }
        if left_eye_frame.dtype != torch.uint8:
            left_eye_frame = left_eye_frame.clamp(0.0, 255.0).to(torch.uint8)
        if right_eye_frame.dtype != torch.uint8:
            right_eye_frame = right_eye_frame.clamp(0.0, 255.0).to(torch.uint8)
        if preview_frame is None:
            preview_frame = left_eye_frame
        elif torch.is_tensor(preview_frame) and preview_frame.dtype != torch.uint8:
            preview_frame = preview_frame.clamp(0.0, 255.0).to(torch.uint8)
        publish_start = time.perf_counter()
        publish_ok, publish_stats = immersive_bridge.publish_stereo_frames(
            left_eye_frame,
            right_eye_frame,
        )
        publish_wall_ms = 1000.0 * (time.perf_counter() - publish_start)
        if not publish_ok:
            raise RuntimeError(
                "Quest immersive bridge stopped accepting stereo frames during "
                f"stable cover publish ({str(backend_kind).strip().lower()} / "
                f"{str(reject_source).strip().lower()}).\n"
                + immersive_bridge.debug_summary()
            )
        return {
            "cache_hit": True,
            "cache_missing": False,
            "publish_wall_ms": float(publish_wall_ms),
            "publish_stats": publish_stats,
            "preview_frame": preview_frame,
            "reject_source": str(reject_source).strip().lower(),
            "backend_kind": str(backend_kind).strip().lower(),
        }

    @torch.no_grad()
    def _compute_immersive_idle_fullframe_flash_eye_metrics(self, frame):
        if not torch.is_tensor(frame) or frame.ndim != 3 or int(frame.shape[-1]) < 3:
            return None
        rgb = frame[..., :3].detach()
        if rgb.dtype != torch.float32:
            rgb = rgb.to(dtype=torch.float32)
        max_rgb = rgb.max(dim=-1).values
        near_black_ratio = float(
            (
                max_rgb
                <= float(self.IMMERSIVE_IDLE_FULLFRAME_FLASH_NEAR_BLACK_MAX_RGB)
            )
            .to(dtype=torch.float32)
            .mean()
            .item()
        )
        mean_luma = float(
            (
                rgb[..., 0] * 0.2126
                + rgb[..., 1] * 0.7152
                + rgb[..., 2] * 0.0722
            )
            .mean()
            .item()
        )
        return {
            "near_black_ratio": float(near_black_ratio),
            "mean_luma": float(mean_luma),
        }

    @torch.no_grad()
    def _evaluate_immersive_idle_fullframe_flash_guard(
        self,
        *,
        left_eye_frame,
        right_eye_frame,
        committed_safe_cover_left_frame,
        committed_safe_cover_right_frame,
        committed_safe_cover_frame_count,
        interaction_context=None,
        backend_kind,
    ):
        interaction_context = (
            {} if interaction_context is None else copy.deepcopy(interaction_context)
        )
        interaction_window_active = bool(
            interaction_context.get("interaction_window_active", False)
        ) or bool(interaction_context.get("post_release_window_active", False))
        guard_mode = "interaction" if interaction_window_active else "idle"
        reject_source = f"{guard_mode}_fullframe_flash"
        decision = {
            "armed": False,
            "reject_publish": False,
            "reason": "uninitialized",
            "guard_mode": str(guard_mode),
            "reject_source": str(reject_source),
            "backend_kind": str(backend_kind).strip().lower(),
            "baseline_frame_count": int(max(committed_safe_cover_frame_count, 0)),
            "interaction_context": interaction_context,
            "near_black_ratio_threshold": float(
                self.IMMERSIVE_IDLE_FULLFRAME_FLASH_MIN_NEAR_BLACK_RATIO
            ),
            "luma_ratio_threshold": float(
                self.IMMERSIVE_IDLE_FULLFRAME_FLASH_MAX_LUMA_RATIO
            ),
            "metrics_by_eye": {},
            "rejected_eyes": [],
            "trigger_reasons": [],
        }
        if int(committed_safe_cover_frame_count) < int(
            self.IMMERSIVE_IDLE_FULLFRAME_FLASH_ARM_SAFE_COVER_FRAMES
        ):
            decision["reason"] = "baseline_not_armed"
            return decision
        current_frames = {
            "left": left_eye_frame,
            "right": right_eye_frame,
        }
        baseline_frames = {
            "left": committed_safe_cover_left_frame,
            "right": committed_safe_cover_right_frame,
        }
        baseline_valid = True
        rejected_eyes = []
        for eye_label in ("left", "right"):
            current_metrics = self._compute_immersive_idle_fullframe_flash_eye_metrics(
                current_frames[eye_label]
            )
            baseline_metrics = self._compute_immersive_idle_fullframe_flash_eye_metrics(
                baseline_frames[eye_label]
            )
            decision["metrics_by_eye"][eye_label] = {
                "current": copy.deepcopy(current_metrics),
                "baseline": copy.deepcopy(baseline_metrics),
                "luma_ratio_to_baseline": None,
                "reject": False,
            }
            if current_metrics is None or baseline_metrics is None:
                baseline_valid = False
                continue
            baseline_near_black = bool(
                float(baseline_metrics.get("near_black_ratio", 1.0))
                >= float(self.IMMERSIVE_IDLE_FULLFRAME_FLASH_MIN_NEAR_BLACK_RATIO)
            )
            baseline_luma = max(
                float(baseline_metrics.get("mean_luma", 0.0)),
                1e-6,
            )
            luma_ratio = float(current_metrics.get("mean_luma", 0.0)) / baseline_luma
            decision["metrics_by_eye"][eye_label][
                "luma_ratio_to_baseline"
            ] = float(luma_ratio)
            eye_reject = bool(
                (not baseline_near_black)
                and float(current_metrics.get("near_black_ratio", 0.0))
                >= float(self.IMMERSIVE_IDLE_FULLFRAME_FLASH_MIN_NEAR_BLACK_RATIO)
                and luma_ratio
                < float(self.IMMERSIVE_IDLE_FULLFRAME_FLASH_MAX_LUMA_RATIO)
            )
            decision["metrics_by_eye"][eye_label]["reject"] = bool(eye_reject)
            if baseline_near_black:
                baseline_valid = False
            if eye_reject:
                rejected_eyes.append(str(eye_label))
        if not baseline_valid:
            decision["reason"] = "baseline_invalid"
            return decision
        decision["armed"] = True
        decision["rejected_eyes"] = list(rejected_eyes)
        if len(rejected_eyes) == 2:
            decision["reject_publish"] = True
            decision["reason"] = "wholeframe_near_black_collapse"
            decision["trigger_reasons"] = [str(reject_source)]
        else:
            decision["reason"] = "frame_ok"
        return decision

    def _format_immersive_idle_fullframe_flash_guard_summary(self, decision):
        if not decision:
            return ""
        parts = [
            f"backend={str(decision.get('backend_kind', '')).strip().lower()}",
            f"mode={str(decision.get('guard_mode', '')).strip().lower()}",
            f"reason={str(decision.get('reason', '')).strip().lower()}",
            f"baseline_frames={int(decision.get('baseline_frame_count', 0))}",
        ]
        for eye_label in ("left", "right"):
            eye_metrics = (decision.get("metrics_by_eye") or {}).get(eye_label) or {}
            current_metrics = eye_metrics.get("current") or {}
            baseline_metrics = eye_metrics.get("baseline") or {}
            luma_ratio = eye_metrics.get("luma_ratio_to_baseline")
            if current_metrics:
                parts.append(
                    f"{eye_label}_near_black={float(current_metrics.get('near_black_ratio', 0.0)):.3f}"
                )
                parts.append(
                    f"{eye_label}_mean_luma={float(current_metrics.get('mean_luma', 0.0)):.2f}"
                )
            if baseline_metrics:
                parts.append(
                    f"{eye_label}_baseline_near_black={float(baseline_metrics.get('near_black_ratio', 0.0)):.3f}"
                )
                parts.append(
                    f"{eye_label}_baseline_luma={float(baseline_metrics.get('mean_luma', 0.0)):.2f}"
                )
            if luma_ratio is not None:
                parts.append(f"{eye_label}_luma_ratio={float(luma_ratio):.3f}")
        return " ".join(parts)

    def _predict_immersive_eye_poses_for_sample(
        self,
        sample,
        live_head_alignment,
        head_pose_state,
        frame_index,
    ):
        if sample is None or live_head_alignment is None:
            return None, None
        state_copy = None if head_pose_state is None else copy.deepcopy(head_pose_state)
        left_eye_pose_world, right_eye_pose_world, predicted_head_pose_state = (
            self._update_immersive_head_pose_state(
                sample,
                live_head_alignment,
                state_copy,
                frame_index=frame_index,
            )
        )
        return left_eye_pose_world, right_eye_pose_world, predicted_head_pose_state

    def _resolve_immersive_scene_publish_state(
        self,
        immersive_bridge,
        *,
        scene_depth_reproject_enabled,
        scene_source_sample_id,
        scene_source_left_eye_pose_world,
        scene_source_right_eye_pose_world,
        scene_source_left_intrinsic,
        scene_source_right_intrinsic,
        default_left_overlay_eye_render_state,
        default_right_overlay_eye_render_state,
        live_head_alignment,
        head_pose_state,
        frame_index,
        eye_width,
        eye_height,
        publish_sample_override=None,
    ):
        resolved = {
            "publish_sample": None,
            "publish_sample_id": int(scene_source_sample_id),
            "apply_timewarp": False,
            "publish_left_eye_pose_world": scene_source_left_eye_pose_world,
            "publish_right_eye_pose_world": scene_source_right_eye_pose_world,
            "publish_left_intrinsic": np.asarray(
                scene_source_left_intrinsic, dtype=np.float32
            ).copy(),
            "publish_right_intrinsic": np.asarray(
                scene_source_right_intrinsic, dtype=np.float32
            ).copy(),
            "left_overlay_eye_render_state": default_left_overlay_eye_render_state,
            "right_overlay_eye_render_state": default_right_overlay_eye_render_state,
            "head_pose_reset": False,
        }
        if not scene_depth_reproject_enabled:
            return resolved
        publish_sample = (
            publish_sample_override
            if publish_sample_override is not None
            else immersive_bridge.get_latest_sample()
        )
        resolved["publish_sample"] = publish_sample
        if (
            publish_sample is None
            or not self._immersive_sample_has_valid_eye_pose(publish_sample)
            or int(publish_sample.sample) <= int(scene_source_sample_id)
        ):
            return resolved

        (
            predicted_left_eye_pose_world,
            predicted_right_eye_pose_world,
            predicted_head_pose_state,
        ) = self._predict_immersive_eye_poses_for_sample(
            publish_sample,
            live_head_alignment,
            head_pose_state,
            frame_index,
        )
        if head_pose_state is not None and predicted_head_pose_state is not None:
            resolved["head_pose_reset"] = bool(
                int(predicted_head_pose_state.get("last_reset_frame_index", -1))
                != int(head_pose_state.get("last_reset_frame_index", -1))
            )
        publish_left_eye_pose_world = scene_source_left_eye_pose_world
        publish_right_eye_pose_world = scene_source_right_eye_pose_world
        if predicted_left_eye_pose_world is not None:
            publish_left_eye_pose_world = predicted_left_eye_pose_world
        if predicted_right_eye_pose_world is not None:
            publish_right_eye_pose_world = predicted_right_eye_pose_world

        publish_left_intrinsic = np.asarray(
            scene_source_left_intrinsic,
            dtype=np.float32,
        ).copy()
        publish_right_intrinsic = np.asarray(
            scene_source_right_intrinsic,
            dtype=np.float32,
        ).copy()
        if publish_sample.left_eye is not None and publish_sample.left_eye.pose_valid:
            publish_left_intrinsic = self._eye_sample_intrinsic(
                publish_sample.left_eye,
                eye_width,
                eye_height,
            )
        if publish_sample.right_eye is not None and publish_sample.right_eye.pose_valid:
            publish_right_intrinsic = self._eye_sample_intrinsic(
                publish_sample.right_eye,
                eye_width,
                eye_height,
            )

        resolved.update(
            {
                "publish_sample": publish_sample,
                "publish_sample_id": int(publish_sample.sample),
                "apply_timewarp": True,
                "publish_left_eye_pose_world": publish_left_eye_pose_world,
                "publish_right_eye_pose_world": publish_right_eye_pose_world,
                "publish_left_intrinsic": publish_left_intrinsic,
                "publish_right_intrinsic": publish_right_intrinsic,
                "left_overlay_eye_render_state": (
                    self._prepare_immersive_overlay_eye_render_state(
                        publish_left_eye_pose_world,
                        publish_left_intrinsic,
                        eye_height,
                        eye_width,
                    )
                ),
                "right_overlay_eye_render_state": (
                    self._prepare_immersive_overlay_eye_render_state(
                        publish_right_eye_pose_world,
                        publish_right_intrinsic,
                        eye_height,
                        eye_width,
                    )
                ),
            }
        )
        return resolved

    def _compute_immersive_synthetic_framegen_age_metrics(
        self,
        *,
        scene_source_ready_wall_time_s,
        synthetic_source_ready_wall_time_s=None,
        now_s=None,
    ):
        scene_ready_s = float(scene_source_ready_wall_time_s)
        synthetic_ready_s = (
            scene_ready_s
            if synthetic_source_ready_wall_time_s is None
            else float(synthetic_source_ready_wall_time_s)
        )
        now_s = time.perf_counter() if now_s is None else float(now_s)
        return {
            "synthetic_candidate_age_ms": max(
                0.0,
                (now_s - synthetic_ready_s) * 1000.0,
            ),
            "synthetic_total_scene_age_ms": max(
                0.0,
                (now_s - scene_ready_s) * 1000.0,
            ),
            "synthetic_handoff_delay_ms": max(
                0.0,
                (synthetic_ready_s - scene_ready_s) * 1000.0,
            ),
        }

    def _evaluate_immersive_synthetic_framegen_admission(
        self,
        *,
        framegen_mode,
        publish_state,
        scene_source_ready_wall_time_s,
        synthetic_source_ready_wall_time_s=None,
        source_sample_id,
        source_left_eye_pose_world,
        source_right_eye_pose_world,
        synthetic_emitted,
        stale_packet,
    ):
        decision = {
            "apply": False,
            "reason": "off",
            "source_age_ms": 0.0,
            "total_scene_age_ms": 0.0,
            "handoff_delay_ms": 0.0,
            "translation_m": 0.0,
            "rotation_deg": 0.0,
        }
        mode = str(framegen_mode).strip().lower()
        if mode not in {"static", "adaptive"}:
            return decision
        if bool(synthetic_emitted):
            decision["reason"] = "already_emitted"
            return decision
        if bool(stale_packet):
            decision["reason"] = "stale_packet"
            return decision
        age_metrics = self._compute_immersive_synthetic_framegen_age_metrics(
            scene_source_ready_wall_time_s=scene_source_ready_wall_time_s,
            synthetic_source_ready_wall_time_s=synthetic_source_ready_wall_time_s,
        )
        decision["source_age_ms"] = float(age_metrics["synthetic_candidate_age_ms"])
        decision["total_scene_age_ms"] = float(
            age_metrics["synthetic_total_scene_age_ms"]
        )
        decision["handoff_delay_ms"] = float(
            age_metrics["synthetic_handoff_delay_ms"]
        )
        publish_sample = None if publish_state is None else publish_state.get("publish_sample")
        if publish_sample is None or int(getattr(publish_sample, "sample", -1)) <= int(source_sample_id):
            decision["reason"] = "no_new_sample"
            return decision
        max_source_age_ms = (
            float(self.IMMERSIVE_SYNTHETIC_FRAMEGEN_STATIC_MAX_SOURCE_AGE_MS)
            if mode == "static"
            else float(self.IMMERSIVE_SYNTHETIC_FRAMEGEN_ADAPTIVE_MAX_SOURCE_AGE_MS)
        )
        if decision["source_age_ms"] > max_source_age_ms:
            decision["reason"] = "source_age"
            return decision
        if bool(publish_state.get("head_pose_reset", False)):
            decision["reason"] = "invalid_pose"
            return decision
        publish_left_eye_pose_world = publish_state.get("publish_left_eye_pose_world")
        publish_right_eye_pose_world = publish_state.get("publish_right_eye_pose_world")
        publish_left_intrinsic = publish_state.get("publish_left_intrinsic")
        publish_right_intrinsic = publish_state.get("publish_right_intrinsic")
        if (
            publish_left_eye_pose_world is None
            or publish_right_eye_pose_world is None
            or publish_left_intrinsic is None
            or publish_right_intrinsic is None
        ):
            decision["reason"] = "invalid_pose"
            return decision

        source_center = self._immersive_eye_pair_center_world(
            source_left_eye_pose_world,
            source_right_eye_pose_world,
        )
        publish_center = self._immersive_eye_pair_center_world(
            publish_left_eye_pose_world,
            publish_right_eye_pose_world,
        )
        if source_center is not None and publish_center is not None:
            decision["translation_m"] = float(
                np.linalg.norm(publish_center - source_center)
            )

        rotation_deltas_deg = []
        for source_pose_world, publish_pose_world in (
            (source_left_eye_pose_world, publish_left_eye_pose_world),
            (source_right_eye_pose_world, publish_right_eye_pose_world),
        ):
            rotation_delta_deg = self._immersive_pose_rotation_delta_deg(
                source_pose_world,
                publish_pose_world,
            )
            if rotation_delta_deg is not None:
                rotation_deltas_deg.append(rotation_delta_deg)
        if rotation_deltas_deg:
            decision["rotation_deg"] = float(max(rotation_deltas_deg))

        if mode == "adaptive":
            if (
                decision["translation_m"]
                > float(self.IMMERSIVE_SYNTHETIC_FRAMEGEN_ADAPTIVE_MAX_TRANSLATION_M)
            ):
                decision["reason"] = "translation"
                return decision
            if (
                decision["rotation_deg"]
                > float(self.IMMERSIVE_SYNTHETIC_FRAMEGEN_ADAPTIVE_MAX_ROTATION_DEG)
            ):
                decision["reason"] = "rotation"
                return decision
        decision["apply"] = True
        decision["reason"] = "applied"
        return decision

    def _immersive_eye_pair_center_world(
        self,
        left_eye_pose_world,
        right_eye_pose_world,
    ):
        eye_positions = []
        for eye_pose_world in (left_eye_pose_world, right_eye_pose_world):
            if eye_pose_world is None:
                continue
            eye_positions.append(
                np.asarray(eye_pose_world[:3, 3], dtype=np.float32)
            )
        if not eye_positions:
            return None
        return np.mean(np.stack(eye_positions, axis=0), axis=0)

    def _immersive_pose_rotation_delta_deg(
        self,
        source_pose_world,
        target_pose_world,
    ):
        if source_pose_world is None or target_pose_world is None:
            return None
        source_rot = np.asarray(source_pose_world[:3, :3], dtype=np.float64)
        target_rot = np.asarray(target_pose_world[:3, :3], dtype=np.float64)
        delta_rot = target_rot @ source_rot.T
        cos_theta = float(np.clip((np.trace(delta_rot) - 1.0) * 0.5, -1.0, 1.0))
        return float(np.degrees(np.arccos(cos_theta)))

    def _make_immersive_static_scene_reuse_cache_entry(
        self,
        *,
        render_plan,
        render_sample,
        head_pose_state,
        left_eye_pose_world,
        right_eye_pose_world,
        left_intrinsic,
        right_intrinsic,
        left_scene_color,
        left_scene_depth,
        right_scene_color,
        right_scene_depth,
    ):
        return {
            "left_scene_color": left_scene_color,
            "left_scene_depth": left_scene_depth,
            "right_scene_color": right_scene_color,
            "right_scene_depth": right_scene_depth,
            "source_render_plan": copy.deepcopy(render_plan),
            "static_scene_signature": self._build_immersive_static_scene_signature(
                render_plan
            ),
            "source_sample_id": -1 if render_sample is None else int(render_sample.sample),
            "source_sample_received_monotonic_s": self._sample_received_monotonic_s(
                render_sample
            ),
            "source_left_eye_pose_world": None
            if left_eye_pose_world is None
            else np.asarray(left_eye_pose_world, dtype=np.float32).copy(),
            "source_right_eye_pose_world": None
            if right_eye_pose_world is None
            else np.asarray(right_eye_pose_world, dtype=np.float32).copy(),
            "source_left_intrinsic": np.asarray(left_intrinsic, dtype=np.float32).copy(),
            "source_right_intrinsic": np.asarray(right_intrinsic, dtype=np.float32).copy(),
            "head_pose_reset_frame_index": -1
            if head_pose_state is None
            else int(head_pose_state.get("last_reset_frame_index", -1)),
            "age_displayed_frames": 0,
        }

    def _make_immersive_static_scene_layer_cache_entry(
        self,
        *,
        layer_name,
        layer_output,
        layer_signature,
        head_pose_state,
        eye_pose_world,
        eye_intrinsic,
    ):
        return {
            "layer_name": str(layer_name).strip().lower(),
            "color": layer_output["color"],
            "depth": layer_output["depth"],
            "render_info": copy.deepcopy(layer_output.get("render_info")),
            "render_wall_s": float(layer_output.get("render_wall_s", 0.0)),
            "layer_signature": layer_signature,
            "source_eye_pose_world": None
            if eye_pose_world is None
            else np.asarray(eye_pose_world, dtype=np.float32).copy(),
            "source_eye_intrinsic": np.asarray(eye_intrinsic, dtype=np.float32).copy(),
            "head_pose_reset_frame_index": -1
            if head_pose_state is None
            else int(head_pose_state.get("last_reset_frame_index", -1)),
            "age_displayed_frames": 0,
        }

    def _immersive_static_scene_framegen_max_age_frames(self, framegen_mode):
        mode = str(framegen_mode).strip().lower()
        if self._immersive_stable_present_policy_enabled():
            if mode == "adaptive":
                return int(self.IMMERSIVE_STABLE_PRESENT_ADAPTIVE_MAX_AGE_FRAMES)
            if mode == "static":
                return int(self.IMMERSIVE_STABLE_PRESENT_STATIC_MAX_AGE_FRAMES)
        if mode == "adaptive":
            return int(self.IMMERSIVE_FRAMEGEN_ADAPTIVE_MAX_AGE_FRAMES)
        if mode == "static":
            return int(self.IMMERSIVE_FRAMEGEN_STATIC_MAX_AGE_FRAMES)
        return 0

    def _immersive_stable_present_policy_enabled(self):
        return bool(
            getattr(self, "_immersive_stable_present_policy_active", False)
        )

    def _immersive_active_render_preset_name(self):
        return str(
            getattr(
                self,
                "_immersive_active_render_preset_name_value",
                "balanced",
            )
        ).strip().lower()

    def _immersive_framegen_translation_guard_m(self):
        if self._immersive_stable_present_policy_enabled():
            return float(self.IMMERSIVE_STABLE_PRESENT_TRANSLATION_GUARD_M)
        return float(self.IMMERSIVE_FRAMEGEN_ADAPTIVE_TRANSLATION_GUARD_M)

    def _immersive_framegen_rotation_guard_deg(self):
        if self._immersive_stable_present_policy_enabled():
            return float(self.IMMERSIVE_STABLE_PRESENT_ROTATION_GUARD_DEG)
        return float(self.IMMERSIVE_FRAMEGEN_ADAPTIVE_ROTATION_GUARD_DEG)

    def _evaluate_immersive_scene_timewarp_admission(
        self,
        *,
        apply_requested,
        queue_wait_ms,
        source_age_ms,
        static_scene_reuse_age_frames,
        stale_packet,
    ):
        decision = {
            "apply": bool(apply_requested),
            "skipped": False,
            "skip_queue_wait": False,
            "skip_source_age": False,
            "skip_reuse_age": False,
            "skip_stale_packet": False,
        }
        if not bool(apply_requested):
            return decision
        if not self._immersive_stable_present_policy_enabled():
            return decision
        queue_wait_ms = float(queue_wait_ms)
        source_age_ms = float(source_age_ms)
        static_scene_reuse_age_frames = float(static_scene_reuse_age_frames)
        decision["skip_queue_wait"] = (
            queue_wait_ms > float(self.IMMERSIVE_STABLE_PRESENT_TIMEWARP_MAX_QUEUE_WAIT_MS)
        )
        decision["skip_source_age"] = (
            source_age_ms > float(self.IMMERSIVE_STABLE_PRESENT_TIMEWARP_MAX_SOURCE_AGE_MS)
        )
        decision["skip_reuse_age"] = (
            static_scene_reuse_age_frames
            > float(self.IMMERSIVE_STABLE_PRESENT_TIMEWARP_MAX_REUSE_AGE_FRAMES)
        )
        decision["skip_stale_packet"] = bool(stale_packet)
        decision["skipped"] = bool(
            decision["skip_queue_wait"]
            or decision["skip_source_age"]
            or decision["skip_reuse_age"]
            or decision["skip_stale_packet"]
        )
        decision["apply"] = not bool(decision["skipped"])
        return decision

    def _record_immersive_scene_timewarp_skip_profile_metrics(
        self,
        render_profile_frame,
        decision,
    ):
        if render_profile_frame is None:
            return
        render_profile_frame["scene_timewarp_skipped_ratio"] = (
            1.0 if bool(decision.get("skipped", False)) else 0.0
        )
        render_profile_frame["scene_timewarp_skip_queue_wait_ratio"] = (
            1.0 if bool(decision.get("skip_queue_wait", False)) else 0.0
        )
        render_profile_frame["scene_timewarp_skip_source_age_ratio"] = (
            1.0 if bool(decision.get("skip_source_age", False)) else 0.0
        )
        render_profile_frame["scene_timewarp_skip_reuse_age_ratio"] = (
            1.0 if bool(decision.get("skip_reuse_age", False)) else 0.0
        )
        render_profile_frame["scene_timewarp_skip_stale_packet_ratio"] = (
            1.0 if bool(decision.get("skip_stale_packet", False)) else 0.0
        )

    def _resolve_and_apply_immersive_real_publish_state(
        self,
        immersive_bridge,
        *,
        left_eye_frame,
        left_eye_frame_depth,
        right_eye_frame,
        right_eye_frame_depth,
        scene_depth_reproject_enabled,
        scene_source_sample_id,
        scene_source_left_eye_pose_world,
        scene_source_right_eye_pose_world,
        scene_source_left_intrinsic,
        scene_source_right_intrinsic,
        default_left_overlay_eye_render_state,
        default_right_overlay_eye_render_state,
        live_head_alignment,
        head_pose_state,
        frame_index,
        eye_width,
        eye_height,
        queue_wait_ms,
        source_ready_wall_time_s,
        static_scene_reuse_age_frames,
        stale_packet,
        reproject_caches,
        render_profile_frame=None,
        latewarp_render_profile_frame=None,
        scene_source_received_monotonic_s=None,
        publish_sample_override=None,
        left_stream=None,
        right_stream=None,
        control_stream=None,
        left_latewarp_eye_label="left",
        right_latewarp_eye_label="right",
    ):
        publish_state = self._resolve_immersive_scene_publish_state(
            immersive_bridge,
            scene_depth_reproject_enabled=bool(scene_depth_reproject_enabled),
            scene_source_sample_id=int(scene_source_sample_id),
            scene_source_left_eye_pose_world=scene_source_left_eye_pose_world,
            scene_source_right_eye_pose_world=scene_source_right_eye_pose_world,
            scene_source_left_intrinsic=scene_source_left_intrinsic,
            scene_source_right_intrinsic=scene_source_right_intrinsic,
            default_left_overlay_eye_render_state=default_left_overlay_eye_render_state,
            default_right_overlay_eye_render_state=default_right_overlay_eye_render_state,
            live_head_alignment=live_head_alignment,
            head_pose_state=head_pose_state,
            frame_index=int(frame_index),
            eye_width=int(eye_width),
            eye_height=int(eye_height),
            publish_sample_override=publish_sample_override,
        )
        publish_sample = publish_state["publish_sample"]
        scene_pose_sample = publish_sample if publish_state["apply_timewarp"] else None
        publish_sample_id = int(publish_state["publish_sample_id"])
        left_overlay_eye_render_state = publish_state["left_overlay_eye_render_state"]
        right_overlay_eye_render_state = publish_state["right_overlay_eye_render_state"]
        scene_timewarp_applied = 0.0
        scene_timewarp_fallback_left_used = 0.0
        scene_timewarp_fallback_right_used = 0.0
        scene_pose_received_monotonic_s = scene_source_received_monotonic_s
        left_real_timewarp_validity = {
            "eye_label": "left",
            "accepted": False,
            "reason": "not_requested",
        }
        right_real_timewarp_validity = {
            "eye_label": "right",
            "accepted": False,
            "reason": "not_requested",
        }

        timewarp_source_age_ms = max(
            0.0,
            (time.perf_counter() - float(source_ready_wall_time_s)) * 1000.0,
        )
        timewarp_decision = self._evaluate_immersive_scene_timewarp_admission(
            apply_requested=bool(publish_state["apply_timewarp"]),
            queue_wait_ms=float(queue_wait_ms),
            source_age_ms=timewarp_source_age_ms,
            static_scene_reuse_age_frames=float(static_scene_reuse_age_frames),
            stale_packet=bool(stale_packet),
        )
        self._record_immersive_scene_timewarp_skip_profile_metrics(
            render_profile_frame,
            timewarp_decision,
        )

        def _apply_eye_timewarp(
            *,
            eye_label,
            latewarp_eye_label,
            original_eye_frame,
            original_eye_depth,
            render_eye_pose_world,
            publish_eye_pose_world,
            render_intrinsic,
            publish_intrinsic,
            stats_out,
        ):
            try:
                (
                    warped_eye_frame,
                    warped_eye_depth,
                    warped_valid_mask,
                ) = self._latewarp_immersive_scene_eye(
                    original_eye_frame,
                    original_eye_depth,
                    render_eye_pose_world,
                    publish_eye_pose_world,
                    render_intrinsic,
                    publish_intrinsic,
                    eye_height,
                    eye_width,
                    latewarp_eye_label,
                    reproject_caches=reproject_caches,
                    render_profile_frame=latewarp_render_profile_frame,
                    stats_out=stats_out,
                )
                (
                    resolved_eye_frame,
                    resolved_eye_depth,
                    resolved_validity,
                ) = self._evaluate_immersive_real_timewarp_eye_result(
                    eye_label=eye_label,
                    original_eye_frame=original_eye_frame,
                    original_eye_depth=original_eye_depth,
                    warped_eye_frame=warped_eye_frame,
                    warped_eye_depth=warped_eye_depth,
                    warped_valid_mask=warped_valid_mask,
                    warped_stats=stats_out,
                    target_height=eye_height,
                    target_width=eye_width,
                )
                fallback_used = 0.0
                if not bool(resolved_validity.get("accepted", False)):
                    fallback_used = 1.0
                return (
                    resolved_eye_frame,
                    resolved_eye_depth,
                    fallback_used,
                    resolved_validity,
                )
            except Exception as exc:
                return (
                    original_eye_frame,
                    original_eye_depth,
                    1.0,
                    {
                        "eye_label": str(eye_label),
                        "accepted": False,
                        "reason": f"exception:{type(exc).__name__}",
                    },
                )

        if bool(timewarp_decision["apply"]):
            publish_sample_id = int(publish_state["publish_sample_id"])
            left_timewarp_stats = {}
            right_timewarp_stats = {}
            timewarp_span = None
            if control_stream is None:
                timewarp_span = self._render_profile_begin_cuda_span(
                    render_profile_frame,
                    "scene_timewarp_gpu_ms",
                )
            else:
                with torch.cuda.stream(control_stream):
                    timewarp_span = self._render_profile_begin_cuda_span(
                        render_profile_frame,
                        "scene_timewarp_gpu_ms",
                    )

            if left_stream is None:
                (
                    left_eye_frame,
                    left_eye_frame_depth,
                    scene_timewarp_fallback_left_used,
                    left_real_timewarp_validity,
                ) = _apply_eye_timewarp(
                    eye_label="left",
                    latewarp_eye_label=left_latewarp_eye_label,
                    original_eye_frame=left_eye_frame,
                    original_eye_depth=left_eye_frame_depth,
                    render_eye_pose_world=scene_source_left_eye_pose_world,
                    publish_eye_pose_world=publish_state["publish_left_eye_pose_world"],
                    render_intrinsic=scene_source_left_intrinsic,
                    publish_intrinsic=publish_state["publish_left_intrinsic"],
                    stats_out=left_timewarp_stats,
                )
            else:
                with torch.cuda.stream(left_stream):
                    (
                        left_eye_frame,
                        left_eye_frame_depth,
                        scene_timewarp_fallback_left_used,
                        left_real_timewarp_validity,
                    ) = _apply_eye_timewarp(
                        eye_label="left",
                        latewarp_eye_label=left_latewarp_eye_label,
                        original_eye_frame=left_eye_frame,
                        original_eye_depth=left_eye_frame_depth,
                        render_eye_pose_world=scene_source_left_eye_pose_world,
                        publish_eye_pose_world=publish_state["publish_left_eye_pose_world"],
                        render_intrinsic=scene_source_left_intrinsic,
                        publish_intrinsic=publish_state["publish_left_intrinsic"],
                        stats_out=left_timewarp_stats,
                    )

            if right_stream is None:
                (
                    right_eye_frame,
                    right_eye_frame_depth,
                    scene_timewarp_fallback_right_used,
                    right_real_timewarp_validity,
                ) = _apply_eye_timewarp(
                    eye_label="right",
                    latewarp_eye_label=right_latewarp_eye_label,
                    original_eye_frame=right_eye_frame,
                    original_eye_depth=right_eye_frame_depth,
                    render_eye_pose_world=scene_source_right_eye_pose_world,
                    publish_eye_pose_world=publish_state["publish_right_eye_pose_world"],
                    render_intrinsic=scene_source_right_intrinsic,
                    publish_intrinsic=publish_state["publish_right_intrinsic"],
                    stats_out=right_timewarp_stats,
                )
            else:
                with torch.cuda.stream(right_stream):
                    (
                        right_eye_frame,
                        right_eye_frame_depth,
                        scene_timewarp_fallback_right_used,
                        right_real_timewarp_validity,
                    ) = _apply_eye_timewarp(
                        eye_label="right",
                        latewarp_eye_label=right_latewarp_eye_label,
                        original_eye_frame=right_eye_frame,
                        original_eye_depth=right_eye_frame_depth,
                        render_eye_pose_world=scene_source_right_eye_pose_world,
                        publish_eye_pose_world=publish_state["publish_right_eye_pose_world"],
                        render_intrinsic=scene_source_right_intrinsic,
                        publish_intrinsic=publish_state["publish_right_intrinsic"],
                        stats_out=right_timewarp_stats,
                    )

            if control_stream is None:
                self._render_profile_end_cuda_span(
                    render_profile_frame,
                    timewarp_span,
                )
            else:
                with torch.cuda.stream(control_stream):
                    if left_stream is not None:
                        control_stream.wait_stream(left_stream)
                    if right_stream is not None:
                        control_stream.wait_stream(right_stream)
                    self._render_profile_end_cuda_span(
                        render_profile_frame,
                        timewarp_span,
                    )

            if bool(left_real_timewarp_validity.get("accepted", False)) or bool(
                right_real_timewarp_validity.get("accepted", False)
            ):
                scene_timewarp_applied = 1.0
                if scene_pose_sample is not None:
                    pose_received = self._sample_received_monotonic_s(scene_pose_sample)
                    if pose_received is not None:
                        scene_pose_received_monotonic_s = float(pose_received)
            else:
                publish_sample = None
                scene_pose_sample = None
                publish_sample_id = int(scene_source_sample_id)
                left_overlay_eye_render_state = default_left_overlay_eye_render_state
                right_overlay_eye_render_state = default_right_overlay_eye_render_state
        else:
            publish_sample = None
            scene_pose_sample = None
            publish_sample_id = int(scene_source_sample_id)
            left_overlay_eye_render_state = default_left_overlay_eye_render_state
            right_overlay_eye_render_state = default_right_overlay_eye_render_state

        return {
            "left_eye_frame": left_eye_frame,
            "left_eye_frame_depth": left_eye_frame_depth,
            "right_eye_frame": right_eye_frame,
            "right_eye_frame_depth": right_eye_frame_depth,
            "publish_state": publish_state,
            "publish_sample": publish_sample,
            "publish_sample_id": int(publish_sample_id),
            "left_overlay_eye_render_state": left_overlay_eye_render_state,
            "right_overlay_eye_render_state": right_overlay_eye_render_state,
            "scene_timewarp_applied": float(scene_timewarp_applied),
            "scene_timewarp_fallback_left_used": float(
                scene_timewarp_fallback_left_used
            ),
            "scene_timewarp_fallback_right_used": float(
                scene_timewarp_fallback_right_used
            ),
            "scene_pose_sample": scene_pose_sample,
            "scene_pose_received_monotonic_s": scene_pose_received_monotonic_s,
            "left_real_timewarp_validity": left_real_timewarp_validity,
            "right_real_timewarp_validity": right_real_timewarp_validity,
            "timewarp_decision": timewarp_decision,
        }

    def _build_immersive_static_scene_signature(self, render_plan):
        if render_plan is None:
            return None

        def _roi_signature(bounds):
            if bounds is None:
                return None
            return tuple(int(v) for v in bounds)

        def _matrix_signature(matrix):
            if matrix is None:
                return None
            matrix_np = np.asarray(matrix, dtype=np.float32)
            return tuple(
                round(float(v), 5) for v in matrix_np.reshape(-1).tolist()
            )

        def _eye_signature(eye_plan):
            eye_plan = {} if eye_plan is None else eye_plan
            return (
                int(eye_plan.get("eye_width", 0)),
                int(eye_plan.get("eye_height", 0)),
                _matrix_signature(eye_plan.get("eye_intrinsic")),
                _matrix_signature(eye_plan.get("base_scene_intrinsic")),
                str(eye_plan.get("support_render_kind", "none")).strip().lower(),
                _roi_signature(eye_plan.get("support_roi_bounds")),
                bool(eye_plan.get("support_fullframe_fallback", False)),
                _roi_signature(eye_plan.get("table_roi_bounds")),
                bool(eye_plan.get("table_fullframe_fallback", False)),
            )

        active_support = render_plan.get("active_support") or {}
        active_support_id = active_support.get("support_id")
        if active_support_id is not None:
            active_support_id = int(active_support_id)
        render_preset = self._immersive_active_render_preset_name()
        return (
            str(
                render_plan.get(
                    "static_scene_mode",
                    self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
                )
            )
            .strip()
            .lower(),
            int(render_plan.get("scene_width", 0)),
            int(render_plan.get("scene_height", 0)),
            render_preset,
            active_support_id,
            str(active_support.get("kind", "none")).strip().lower(),
            _eye_signature(render_plan.get("left")),
            _eye_signature(render_plan.get("right")),
        )

    def _build_immersive_static_scene_layer_signatures(self, render_plan):
        if render_plan is None:
            return {"left": {}, "right": {}}

        def _roi_signature(bounds):
            if bounds is None:
                return None
            return tuple(int(v) for v in bounds)

        def _matrix_signature(matrix):
            if matrix is None:
                return None
            matrix_np = np.asarray(matrix, dtype=np.float32)
            return tuple(
                round(float(v), 5) for v in matrix_np.reshape(-1).tolist()
            )

        static_scene_mode = str(
            render_plan.get(
                "static_scene_mode",
                self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
            )
        ).strip().lower()
        active_support = render_plan.get("active_support") or {}
        active_support_id = active_support.get("support_id")
        if active_support_id is not None:
            active_support_id = int(active_support_id)
        render_preset = self._immersive_active_render_preset_name()

        signatures = {"left": {}, "right": {}}
        for eye_label in ("left", "right"):
            eye_plan = render_plan.get(eye_label) or {}
            eye_width = int(eye_plan.get("eye_width", 0))
            eye_height = int(eye_plan.get("eye_height", 0))
            base_intrinsic_signature = _matrix_signature(
                eye_plan.get("base_scene_intrinsic")
            )
            eye_intrinsic_signature = _matrix_signature(eye_plan.get("eye_intrinsic"))
            signatures[eye_label][
                IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE
            ] = (
                static_scene_mode,
                IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE,
                int(render_plan.get("scene_width", 0)),
                int(render_plan.get("scene_height", 0)),
                render_preset,
                base_intrinsic_signature,
            )
            signatures[eye_label][IMMERSIVE_BALANCED_LAYER_FULL_BASE] = (
                static_scene_mode,
                IMMERSIVE_BALANCED_LAYER_FULL_BASE,
                int(render_plan.get("scene_width", 0)),
                int(render_plan.get("scene_height", 0)),
                render_preset,
                base_intrinsic_signature,
            )
            signatures[eye_label][IMMERSIVE_BALANCED_LAYER_TABLE_BASE] = (
                static_scene_mode,
                IMMERSIVE_BALANCED_LAYER_TABLE_BASE,
                int(render_plan.get("scene_width", 0)),
                int(render_plan.get("scene_height", 0)),
                render_preset,
                base_intrinsic_signature,
            )
            if static_scene_mode == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS:
                table_render_scale = float(
                    render_plan.get("table_roi_render_scale", 1.0)
                )
                signatures[eye_label][
                    IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY
                ] = (
                    static_scene_mode,
                    IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY,
                    eye_width,
                    eye_height,
                    render_preset,
                    eye_intrinsic_signature,
                    _roi_signature(eye_plan.get("table_roi_bounds")),
                    bool(eye_plan.get("table_fullframe_fallback", False)),
                    round(float(table_render_scale), 5),
                )
                continue

            support_render_kind = str(
                eye_plan.get("support_render_kind", "none")
            ).strip().lower()
            support_render_scale = float(
                render_plan.get("support_roi_render_scale", 1.0)
            )
            signatures[eye_label][IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY] = (
                static_scene_mode,
                IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY,
                eye_width,
                eye_height,
                render_preset,
                eye_intrinsic_signature,
                support_render_kind,
                _roi_signature(eye_plan.get("support_roi_bounds")),
                bool(eye_plan.get("support_fullframe_fallback", False)),
                round(float(support_render_scale), 5),
            )
            signatures[eye_label][IMMERSIVE_BALANCED_LAYER_SUPPORT_OVERLAY] = (
                static_scene_mode,
                IMMERSIVE_BALANCED_LAYER_SUPPORT_OVERLAY,
                eye_width,
                eye_height,
                render_preset,
                eye_intrinsic_signature,
                support_render_kind,
                active_support_id,
                str(active_support.get("kind", "none")).strip().lower(),
                _roi_signature(eye_plan.get("support_roi_bounds")),
                bool(eye_plan.get("support_fullframe_fallback", False)),
                round(float(support_render_scale), 5),
            )
        return signatures

    def _collect_immersive_balanced_required_layers(self, render_plan):
        static_scene_mode = str(
            render_plan.get(
                "static_scene_mode",
                self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
            )
        ).strip().lower()
        required_layers = {"left": [], "right": []}
        for eye_label in ("left", "right"):
            if static_scene_mode == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS:
                required_layers[eye_label] = [
                    IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE,
                    IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY,
                ]
                continue
            support_render_kind = str(
                (render_plan.get(eye_label) or {}).get("support_render_kind", "none")
            ).strip().lower()
            if support_render_kind == "focus":
                required_layers[eye_label] = [
                    IMMERSIVE_BALANCED_LAYER_FULL_BASE,
                    IMMERSIVE_BALANCED_LAYER_SUPPORT_OVERLAY,
                ]
            elif support_render_kind == "table":
                required_layers[eye_label] = [
                    IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE,
                    IMMERSIVE_BALANCED_LAYER_TABLE_OVERLAY,
                ]
            else:
                required_layers[eye_label] = [
                    IMMERSIVE_BALANCED_LAYER_BACKGROUND_BASE,
                    IMMERSIVE_BALANCED_LAYER_TABLE_BASE,
                ]
        return required_layers

    def _immersive_eye_pose_translation_m(
        self,
        source_eye_pose_world,
        target_eye_pose_world,
    ):
        if source_eye_pose_world is None or target_eye_pose_world is None:
            return None
        source_position = np.asarray(source_eye_pose_world[:3, 3], dtype=np.float32)
        target_position = np.asarray(target_eye_pose_world[:3, 3], dtype=np.float32)
        return float(np.linalg.norm(target_position - source_position))

    def _record_immersive_static_scene_reuse_profile_metrics(
        self,
        render_profile_frame,
        *,
        fresh_render,
        reason,
        max_age_hit,
        cache_invalidation_count,
        signature_change_count,
    ):
        if render_profile_frame is None:
            return
        reason_metric_keys = {
            "cache_miss": "static_scene_reuse_reason_cache_miss_ratio",
            "signature_unavailable": "static_scene_reuse_reason_signature_unavailable_ratio",
            "signature_change": "static_scene_reuse_reason_signature_change_ratio",
            "age_limit": "static_scene_reuse_reason_age_limit_ratio",
            "head_reset": "static_scene_reuse_reason_head_reset_ratio",
            "translation_guard": "static_scene_reuse_reason_translation_guard_ratio",
            "rotation_guard": "static_scene_reuse_reason_rotation_guard_ratio",
            "invalid_eye_pose": "static_scene_reuse_reason_invalid_eye_pose_ratio",
            "static_cadence": "static_scene_reuse_reason_static_cadence_ratio",
            "adaptive_guardrails_passed": "static_scene_reuse_reason_adaptive_pass_ratio",
            "worker_failure": "static_scene_reuse_reason_worker_failure_ratio",
        }
        render_profile_frame["static_scene_fresh_render_ratio"] = (
            1.0 if fresh_render else 0.0
        )
        render_profile_frame["static_scene_reuse_max_age_hit_ratio"] = (
            1.0 if max_age_hit else 0.0
        )
        render_profile_frame["static_scene_cache_invalidation_count"] = float(
            cache_invalidation_count
        )
        render_profile_frame["static_scene_signature_change_count"] = float(
            signature_change_count
        )
        for metric_key in reason_metric_keys.values():
            render_profile_frame[metric_key] = 0.0
        metric_key = reason_metric_keys.get(str(reason).strip().lower())
        if metric_key is not None:
            render_profile_frame[metric_key] = 1.0

    def _record_immersive_static_scene_layer_reuse_profile_metrics(
        self,
        render_profile_frame,
        *,
        category,
        refreshed,
        reasons,
        max_age_hit,
        signature_change_count,
    ):
        if render_profile_frame is None:
            return
        category = str(category).strip().lower()
        prefix = f"static_scene_{category}"
        reason_metric_keys = {
            "cache_miss": f"{prefix}_reuse_reason_cache_miss_ratio",
            "signature_unavailable": f"{prefix}_reuse_reason_signature_unavailable_ratio",
            "signature_change": f"{prefix}_reuse_reason_signature_change_ratio",
            "age_limit": f"{prefix}_reuse_reason_age_limit_ratio",
            "head_reset": f"{prefix}_reuse_reason_head_reset_ratio",
            "translation_guard": f"{prefix}_reuse_reason_translation_guard_ratio",
            "rotation_guard": f"{prefix}_reuse_reason_rotation_guard_ratio",
            "invalid_eye_pose": f"{prefix}_reuse_reason_invalid_eye_pose_ratio",
            "static_cadence": f"{prefix}_reuse_reason_static_cadence_ratio",
            "adaptive_guardrails_passed": f"{prefix}_reuse_reason_adaptive_pass_ratio",
            "worker_failure": f"{prefix}_reuse_reason_worker_failure_ratio",
        }
        render_profile_frame[f"{prefix}_refresh_ratio"] = 1.0 if refreshed else 0.0
        render_profile_frame[f"{prefix}_reuse_max_age_hit_ratio"] = (
            1.0 if max_age_hit else 0.0
        )
        render_profile_frame[f"{prefix}_signature_change_count"] = float(
            signature_change_count
        )
        for metric_key in reason_metric_keys.values():
            render_profile_frame[metric_key] = 0.0
        for reason in reasons:
            metric_key = reason_metric_keys.get(str(reason).strip().lower())
            if metric_key is not None:
                render_profile_frame[metric_key] = 1.0

    def _evaluate_immersive_static_scene_layer_reuse(
        self,
        *,
        framegen_mode,
        layer_cache,
        render_sample,
        head_pose_state,
        eye_pose_world,
        layer_signature=None,
    ):
        decision = {
            "reuse": False,
            "reason": "off",
            "reuse_age_frames": 0.0,
            "translation_m": 0.0,
            "rotation_deg": 0.0,
            "signature_changed": False,
            "max_age_hit": False,
        }
        mode = str(framegen_mode).strip().lower()
        if mode not in {"static", "adaptive"}:
            return decision
        decision["reason"] = "cache_miss"
        if layer_cache is None:
            return decision
        if layer_signature is None:
            decision["reason"] = "signature_unavailable"
            return decision
        decision["reason"] = "invalid_eye_pose"
        if (
            render_sample is None
            or not self._immersive_sample_has_valid_eye_pose(render_sample)
            or eye_pose_world is None
        ):
            return decision
        cached_signature = layer_cache.get("layer_signature")
        if cached_signature != layer_signature:
            decision["reason"] = "signature_change"
            decision["signature_changed"] = True
            return decision
        next_age_frames = int(layer_cache.get("age_displayed_frames", 0)) + 1
        decision["reuse_age_frames"] = float(next_age_frames)
        max_age_frames = self._immersive_static_scene_framegen_max_age_frames(mode)
        if next_age_frames > max_age_frames:
            decision["reason"] = "age_limit"
            decision["max_age_hit"] = True
            return decision

        translation_m = self._immersive_eye_pose_translation_m(
            layer_cache.get("source_eye_pose_world"),
            eye_pose_world,
        )
        if translation_m is not None:
            decision["translation_m"] = float(translation_m)
        rotation_deg = self._immersive_pose_rotation_delta_deg(
            layer_cache.get("source_eye_pose_world"),
            eye_pose_world,
        )
        if rotation_deg is not None:
            decision["rotation_deg"] = float(rotation_deg)

        if mode == "static":
            decision["reuse"] = True
            decision["reason"] = "static_cadence"
            return decision

        current_reset_frame_index = -1 if head_pose_state is None else int(
            head_pose_state.get("last_reset_frame_index", -1)
        )
        if current_reset_frame_index != int(
            layer_cache.get("head_pose_reset_frame_index", -1)
        ):
            decision["reason"] = "head_reset"
            return decision
        if decision["translation_m"] > self._immersive_framegen_translation_guard_m():
            decision["reason"] = "translation_guard"
            return decision
        if decision["rotation_deg"] > self._immersive_framegen_rotation_guard_deg():
            decision["reason"] = "rotation_guard"
            return decision

        decision["reuse"] = True
        decision["reason"] = "adaptive_guardrails_passed"
        return decision

    def _empty_immersive_static_scene_layer_cache(self):
        return {"left": {}, "right": {}}

    def _update_immersive_static_scene_layer_cache(
        self,
        *,
        layer_cache,
        render_plan,
        layer_outputs,
        head_pose_state,
    ):
        if layer_cache is None:
            layer_cache = self._empty_immersive_static_scene_layer_cache()
        layer_signatures = self._build_immersive_static_scene_layer_signatures(
            render_plan
        )
        fresh_layers_by_eye = {"left": set(), "right": set()}
        for eye_label in ("left", "right"):
            eye_plan = render_plan.get(eye_label) or {}
            eye_layer_outputs = (
                {} if layer_outputs is None else layer_outputs.get(eye_label, {})
            )
            for layer_name, layer_output in eye_layer_outputs.items():
                normalized_layer_name = str(layer_name).strip().lower()
                layer_cache.setdefault(eye_label, {})[normalized_layer_name] = (
                    self._make_immersive_static_scene_layer_cache_entry(
                        layer_name=normalized_layer_name,
                        layer_output=layer_output,
                        layer_signature=layer_signatures[eye_label].get(
                            normalized_layer_name
                        ),
                        head_pose_state=head_pose_state,
                        eye_pose_world=eye_plan.get("eye_pose_world"),
                        eye_intrinsic=eye_plan.get("eye_intrinsic"),
                    )
                )
                fresh_layers_by_eye[eye_label].add(normalized_layer_name)
        return layer_cache, fresh_layers_by_eye

    def _seed_immersive_static_scene_layer_cache(
        self,
        *,
        renderer,
        render_plan,
        head_pose_state,
        requested_layers_by_eye,
    ):
        if renderer is None or render_plan is None:
            return self._empty_immersive_static_scene_layer_cache()
        layer_request = _build_immersive_balanced_scene_layer_request(
            render_plan,
            requested_layers_by_eye,
        )
        layer_outputs = _execute_immersive_balanced_scene_render_layers(
            renderer,
            layer_request,
        )
        layer_cache, _ = self._update_immersive_static_scene_layer_cache(
            layer_cache=self._empty_immersive_static_scene_layer_cache(),
            render_plan=render_plan,
            layer_outputs=layer_outputs,
            head_pose_state=head_pose_state,
        )
        return layer_cache

    def _mark_immersive_static_scene_layer_cache_usage(
        self,
        *,
        layer_cache,
        decisions_by_eye,
    ):
        if layer_cache is None:
            return
        for eye_label in ("left", "right"):
            eye_decisions = decisions_by_eye.get(eye_label, {})
            eye_cache = layer_cache.get(eye_label, {})
            for layer_name, decision in eye_decisions.items():
                if not bool(decision.get("reuse", False)):
                    continue
                layer_entry = eye_cache.get(layer_name)
                if layer_entry is None:
                    continue
                layer_entry["age_displayed_frames"] = int(
                    decision.get("reuse_age_frames", 0.0)
                )

    def _increment_immersive_static_scene_layer_cache_age(
        self,
        *,
        layer_cache,
        required_layers_by_eye,
    ):
        if layer_cache is None:
            return
        for eye_label in ("left", "right"):
            eye_cache = layer_cache.get(eye_label, {})
            for layer_name in required_layers_by_eye.get(eye_label, []):
                layer_entry = eye_cache.get(layer_name)
                if layer_entry is None:
                    continue
                layer_entry["age_displayed_frames"] = int(
                    layer_entry.get("age_displayed_frames", 0)
                ) + 1

    def _evaluate_immersive_balanced_layer_refresh_plan(
        self,
        *,
        framegen_mode,
        layer_cache,
        render_plan,
        render_sample,
        head_pose_state,
    ):
        required_layers_by_eye = self._collect_immersive_balanced_required_layers(
            render_plan
        )
        layer_signatures = self._build_immersive_static_scene_layer_signatures(
            render_plan
        )
        decisions_by_eye = {"left": {}, "right": {}}
        requested_layers_by_eye = {"left": [], "right": []}
        base_reasons = set()
        overlay_reasons = set()
        base_refresh_required = False
        overlay_refresh_required = False
        base_max_age_hit = False
        overlay_max_age_hit = False
        base_signature_changed = False
        overlay_signature_changed = False
        max_reuse_age_frames = 0.0

        for eye_label in ("left", "right"):
            eye_plan = render_plan.get(eye_label) or {}
            eye_pose_world = eye_plan.get("eye_pose_world")
            eye_cache = {} if layer_cache is None else layer_cache.get(eye_label, {})
            for layer_name in required_layers_by_eye.get(eye_label, []):
                decision = self._evaluate_immersive_static_scene_layer_reuse(
                    framegen_mode=framegen_mode,
                    layer_cache=None if eye_cache is None else eye_cache.get(layer_name),
                    render_sample=render_sample,
                    head_pose_state=head_pose_state,
                    eye_pose_world=eye_pose_world,
                    layer_signature=layer_signatures[eye_label].get(layer_name),
                )
                decisions_by_eye[eye_label][layer_name] = decision
                if bool(decision.get("reuse", False)):
                    max_reuse_age_frames = max(
                        max_reuse_age_frames,
                        float(decision.get("reuse_age_frames", 0.0)),
                    )
                    continue
                requested_layers_by_eye[eye_label].append(layer_name)
                if layer_name in IMMERSIVE_BALANCED_BASE_LAYER_NAMES:
                    base_refresh_required = True
                    base_reasons.add(str(decision.get("reason", "off")))
                    base_max_age_hit = base_max_age_hit or bool(
                        decision.get("max_age_hit", False)
                    )
                    base_signature_changed = base_signature_changed or bool(
                        decision.get("signature_changed", False)
                    )
                else:
                    overlay_refresh_required = True
                    overlay_reasons.add(str(decision.get("reason", "off")))
                    overlay_max_age_hit = overlay_max_age_hit or bool(
                        decision.get("max_age_hit", False)
                    )
                    overlay_signature_changed = overlay_signature_changed or bool(
                        decision.get("signature_changed", False)
                    )

        return {
            "required_layers_by_eye": required_layers_by_eye,
            "decisions_by_eye": decisions_by_eye,
            "requested_layers_by_eye": requested_layers_by_eye,
            "all_required_layers_reusable": not (
                base_refresh_required or overlay_refresh_required
            ),
            "base_refresh_required": bool(base_refresh_required),
            "overlay_refresh_required": bool(overlay_refresh_required),
            "base_reasons": sorted(base_reasons),
            "overlay_reasons": sorted(overlay_reasons),
            "base_max_age_hit": bool(base_max_age_hit),
            "overlay_max_age_hit": bool(overlay_max_age_hit),
            "base_signature_changed": bool(base_signature_changed),
            "overlay_signature_changed": bool(overlay_signature_changed),
            "max_reuse_age_frames": float(max_reuse_age_frames),
        }

    def _evaluate_immersive_static_scene_framegen_reuse(
        self,
        *,
        framegen_mode,
        framegen_cache,
        render_sample,
        head_pose_state,
        left_eye_pose_world,
        right_eye_pose_world,
        render_plan_signature=None,
    ):
        decision = {
            "reuse": False,
            "reason": "off",
            "reuse_age_frames": 0.0,
            "translation_m": 0.0,
            "rotation_deg": 0.0,
            "signature_changed": False,
            "max_age_hit": False,
        }
        mode = str(framegen_mode).strip().lower()
        if mode not in {"static", "adaptive"}:
            return decision
        decision["reason"] = "cache_miss"
        if framegen_cache is None:
            return decision
        if render_plan_signature is None:
            decision["reason"] = "signature_unavailable"
            return decision
        decision["reason"] = "invalid_eye_pose"
        if (
            render_sample is None
            or not self._immersive_sample_has_valid_eye_pose(render_sample)
            or left_eye_pose_world is None
            or right_eye_pose_world is None
        ):
            return decision
        cached_signature = framegen_cache.get("static_scene_signature")
        if cached_signature != render_plan_signature:
            decision["reason"] = "signature_change"
            decision["signature_changed"] = True
            return decision
        next_age_frames = int(framegen_cache.get("age_displayed_frames", 0)) + 1
        decision["reuse_age_frames"] = float(next_age_frames)
        max_age_frames = self._immersive_static_scene_framegen_max_age_frames(mode)
        if next_age_frames > max_age_frames:
            decision["reason"] = "age_limit"
            decision["max_age_hit"] = True
            return decision

        cached_center = self._immersive_eye_pair_center_world(
            framegen_cache.get("source_left_eye_pose_world"),
            framegen_cache.get("source_right_eye_pose_world"),
        )
        current_center = self._immersive_eye_pair_center_world(
            left_eye_pose_world,
            right_eye_pose_world,
        )
        if cached_center is not None and current_center is not None:
            decision["translation_m"] = float(
                np.linalg.norm(current_center - cached_center)
            )

        rotation_deltas_deg = []
        for source_eye_key, current_eye_pose_world in (
            ("source_left_eye_pose_world", left_eye_pose_world),
            ("source_right_eye_pose_world", right_eye_pose_world),
        ):
            rotation_delta_deg = self._immersive_pose_rotation_delta_deg(
                framegen_cache.get(source_eye_key),
                current_eye_pose_world,
            )
            if rotation_delta_deg is not None:
                rotation_deltas_deg.append(rotation_delta_deg)
        if rotation_deltas_deg:
            decision["rotation_deg"] = float(max(rotation_deltas_deg))

        if mode == "static":
            decision["reuse"] = True
            decision["reason"] = "static_cadence"
            return decision

        current_reset_frame_index = -1 if head_pose_state is None else int(
            head_pose_state.get("last_reset_frame_index", -1)
        )
        if current_reset_frame_index != int(
            framegen_cache.get("head_pose_reset_frame_index", -1)
        ):
            decision["reason"] = "head_reset"
            return decision
        if decision["translation_m"] > self._immersive_framegen_translation_guard_m():
            decision["reason"] = "translation_guard"
            return decision
        if decision["rotation_deg"] > self._immersive_framegen_rotation_guard_deg():
            decision["reason"] = "rotation_guard"
            return decision

        decision["reuse"] = True
        decision["reason"] = "adaptive_guardrails_passed"
        return decision

    def _build_immersive_balanced_scene_render_plan(
        self,
        scene_renderer,
        object_bounds_min_world,
        object_bounds_max_world,
        object_support_center_world,
        left_eye_pose_world,
        right_eye_pose_world,
        left_intrinsic,
        right_intrinsic,
        eye_width,
        eye_height,
        scene_width,
        scene_height,
        active_interaction=False,
        render_profile_frame=None,
    ):
        balanced_runtime_state = getattr(
            self,
            "_immersive_balanced_runtime_state",
            None,
        )
        static_scene_mode = (
            self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS
            if balanced_runtime_state is None
            else str(
                balanced_runtime_state.get(
                    "static_scene_mode",
                    self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
                )
            )
        )
        plan_scene_width = int(
            scene_width
            if balanced_runtime_state is None
            else balanced_runtime_state.get("background_width", scene_width)
        )
        plan_scene_height = int(
            scene_height
            if balanced_runtime_state is None
            else balanced_runtime_state.get("background_height", scene_height)
        )
        self._initialize_immersive_balanced_render_profile_frame(render_profile_frame)
        render_plan = {
            "static_scene_mode": static_scene_mode,
            "scene_width": int(plan_scene_width),
            "scene_height": int(plan_scene_height),
            "active_interaction": bool(active_interaction),
            "left": {
                "eye_pose_world": np.asarray(
                    left_eye_pose_world,
                    dtype=np.float32,
                ).copy(),
                "eye_intrinsic": np.asarray(left_intrinsic, dtype=np.float32).copy(),
                "eye_width": int(eye_width),
                "eye_height": int(eye_height),
                "base_scene_intrinsic": self._scale_intrinsic_for_resolution(
                    left_intrinsic,
                    eye_width,
                    eye_height,
                    plan_scene_width,
                    plan_scene_height,
                ),
            },
            "right": {
                "eye_pose_world": np.asarray(
                    right_eye_pose_world,
                    dtype=np.float32,
                ).copy(),
                "eye_intrinsic": np.asarray(right_intrinsic, dtype=np.float32).copy(),
                "eye_width": int(eye_width),
                "eye_height": int(eye_height),
                "base_scene_intrinsic": self._scale_intrinsic_for_resolution(
                    right_intrinsic,
                    eye_width,
                    eye_height,
                    plan_scene_width,
                    plan_scene_height,
                ),
            },
        }

        if static_scene_mode in {
            self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS,
            self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_SUPPORT_FOCUS,
        }:
            table_world_bounds = (
                None if scene_renderer is None else scene_renderer.table_world_bounds()
            )
            if static_scene_mode == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS:
                render_plan["active_support"] = self._copy_immersive_support_entry(
                    self._find_immersive_table_support_entry(scene_renderer)
                )
                table_roi_state = (
                    {"left": None, "right": None}
                    if balanced_runtime_state is None
                    else balanced_runtime_state.setdefault(
                        "table_roi_state",
                        {"left": None, "right": None},
                    )
                )
                table_roi_render_scale = (
                    float(self.IMMERSIVE_BALANCED_TABLE_ROI_SUPERSAMPLE_SCALE)
                    if balanced_runtime_state is None
                    else float(
                        balanced_runtime_state.get(
                            "table_roi_render_scale",
                            self.IMMERSIVE_BALANCED_TABLE_ROI_SUPERSAMPLE_SCALE,
                        )
                    )
                )
                render_plan["table_roi_render_scale"] = float(table_roi_render_scale)
                for eye_label in ("left", "right"):
                    eye_pose_world = render_plan[eye_label]["eye_pose_world"]
                    eye_intrinsic = render_plan[eye_label]["eye_intrinsic"]
                    eye_w2c_cv = self._camera_pose_world_to_cv_w2c(eye_pose_world)
                    table_roi_bounds = None
                    table_roi_ratio = 1.0
                    table_fullframe_fallback = True
                    if table_world_bounds is not None:
                        (
                            table_roi_bounds,
                            table_roi_ratio,
                            table_fullframe_fallback,
                            _,
                        ) = self._resolve_immersive_balanced_table_render_roi(
                            table_world_bounds[0],
                            table_world_bounds[1],
                            eye_intrinsic,
                            eye_w2c_cv,
                            eye_width,
                            eye_height,
                            prev_bounds=table_roi_state.get(eye_label),
                        )
                    render_plan[eye_label]["table_fullframe_fallback"] = bool(
                        table_fullframe_fallback
                    )
                    render_plan[eye_label]["table_roi_bounds"] = (
                        None
                        if table_fullframe_fallback or table_roi_bounds is None
                        else tuple(int(v) for v in table_roi_bounds)
                    )
                    render_plan[eye_label]["table_roi_ratio"] = float(table_roi_ratio)
                    table_roi_state[eye_label] = render_plan[eye_label]["table_roi_bounds"]
                    if render_profile_frame is not None:
                        render_profile_frame[
                            f"scene_table_roi_{eye_label}_ratio"
                        ] = float(table_roi_ratio)
                        render_profile_frame[
                            "scene_table_roi_supersample_scale"
                        ] = float(table_roi_render_scale)
                        render_profile_frame[
                            f"scene_table_fullframe_fallback_{eye_label}_ratio"
                        ] = 1.0 if table_fullframe_fallback else 0.0
                return render_plan

            support_roi_state = (
                {"left": None, "right": None}
                if balanced_runtime_state is None
                else balanced_runtime_state.setdefault(
                    "support_roi_state",
                    {"left": None, "right": None},
                )
            )
            support_roi_render_scale = (
                float(self.IMMERSIVE_BALANCED_TABLE_ROI_SUPERSAMPLE_SCALE)
                if balanced_runtime_state is None
                else float(
                    balanced_runtime_state.get(
                        "support_roi_render_scale",
                        self.IMMERSIVE_BALANCED_TABLE_ROI_SUPERSAMPLE_SCALE,
                    )
                )
            )
            support_occlusion_state = (
                {
                    eye_label: {
                        "suppressed": False,
                        "candidate_suppress": None,
                        "candidate_frames": 0,
                        "support_id": None,
                        "flip_count": 0,
                    }
                    for eye_label in ("left", "right")
                }
                if balanced_runtime_state is None
                else balanced_runtime_state.setdefault(
                    "support_occlusion_state",
                    {
                        eye_label: {
                            "suppressed": False,
                            "candidate_suppress": None,
                            "candidate_frames": 0,
                            "support_id": None,
                            "flip_count": 0,
                        }
                        for eye_label in ("left", "right")
                    },
                )
            )
            active_support_entry = self._select_immersive_active_support_entry(
                scene_renderer,
                object_support_center_world,
            )
            table_support_entry = self._find_immersive_table_support_entry(
                scene_renderer
            )
            render_plan["support_roi_render_scale"] = float(
                support_roi_render_scale
            )
            render_plan["active_support"] = self._copy_immersive_support_entry(
                active_support_entry
            )
            if render_profile_frame is not None:
                support_state = (
                    {}
                    if balanced_runtime_state is None
                    else balanced_runtime_state.get("active_support_state", {})
                )
                support_kind = (
                    "none"
                    if active_support_entry is None
                    else str(active_support_entry.get("kind", "support"))
                )
                render_profile_frame["scene_active_support_is_table_ratio"] = (
                    1.0 if support_kind == "table" else 0.0
                )
                render_profile_frame["scene_active_support_other_ratio"] = (
                    1.0 if support_kind == "support" else 0.0
                )
                render_profile_frame["scene_active_support_none_ratio"] = (
                    1.0 if active_support_entry is None else 0.0
                )
                render_profile_frame["scene_active_support_switch_count"] = float(
                    support_state.get("switch_count", 0)
                )
            for eye_label in ("left", "right"):
                eye_pose_world = render_plan[eye_label]["eye_pose_world"]
                eye_intrinsic = render_plan[eye_label]["eye_intrinsic"]
                eye_w2c_cv = self._camera_pose_world_to_cv_w2c(eye_pose_world)
                support_roi_bounds = None
                support_roi_ratio = 0.0
                support_fullframe_fallback = False
                support_render_kind = "none"
                occlusion_candidate_suppress = False
                occlusion_suppressed = False
                occlusion_flipped = False
                occlusion_overlap_ratio = 0.0
                occlusion_depth_gap_m = 0.0
                if active_support_entry is not None:
                    support_render_kind = (
                        "table"
                        if str(active_support_entry.get("kind", "support")) == "table"
                        else "focus"
                    )
                    (
                        support_roi_bounds,
                        support_roi_ratio,
                        support_fullframe_fallback,
                        _,
                    ) = self._resolve_immersive_balanced_support_render_roi(
                        active_support_entry.get(
                            "render_bounds_min",
                            active_support_entry["bounds_min"],
                        ),
                        active_support_entry.get(
                            "render_bounds_max",
                            active_support_entry["bounds_max"],
                        ),
                        eye_intrinsic,
                        eye_w2c_cv,
                        eye_width,
                        eye_height,
                        prev_bounds=support_roi_state.get(eye_label),
                    )
                    if support_render_kind == "focus":
                        (
                            occlusion_candidate_suppress,
                            occlusion_debug,
                        ) = self._should_suppress_immersive_support_roi_for_eye(
                            active_support_entry,
                            table_support_entry,
                            eye_intrinsic,
                            eye_w2c_cv,
                            eye_width,
                            eye_height,
                        )
                        occlusion_overlap_ratio = float(
                            occlusion_debug.get("overlap_ratio", 0.0)
                        )
                        occlusion_depth_gap_m = float(
                            occlusion_debug.get("depth_gap_m", 0.0)
                        )
                        (
                            occlusion_suppressed,
                            occlusion_flipped,
                        ) = self._update_immersive_support_occlusion_state_for_eye(
                            support_occlusion_state.setdefault(
                                eye_label,
                                {
                                    "suppressed": False,
                                    "candidate_suppress": None,
                                    "candidate_frames": 0,
                                    "support_id": None,
                                    "flip_count": 0,
                                },
                            ),
                            int(active_support_entry["support_id"]),
                            occlusion_candidate_suppress,
                        )
                        if occlusion_suppressed:
                            support_render_kind = "none"
                            support_roi_bounds = None
                            support_roi_ratio = 0.0
                            support_fullframe_fallback = False
                    else:
                        support_occlusion_state.setdefault(
                            eye_label,
                            {
                                "suppressed": False,
                                "candidate_suppress": None,
                                "candidate_frames": 0,
                                "support_id": None,
                                "flip_count": 0,
                            },
                        )
                        support_occlusion_state[eye_label]["suppressed"] = False
                        support_occlusion_state[eye_label]["candidate_suppress"] = None
                        support_occlusion_state[eye_label]["candidate_frames"] = 0
                        support_occlusion_state[eye_label]["support_id"] = int(
                            active_support_entry["support_id"]
                        )
                else:
                    support_occlusion_state.setdefault(
                        eye_label,
                        {
                            "suppressed": False,
                            "candidate_suppress": None,
                            "candidate_frames": 0,
                            "support_id": None,
                            "flip_count": 0,
                        },
                    )
                    support_occlusion_state[eye_label]["suppressed"] = False
                    support_occlusion_state[eye_label]["candidate_suppress"] = None
                    support_occlusion_state[eye_label]["candidate_frames"] = 0
                    support_occlusion_state[eye_label]["support_id"] = None
                render_plan[eye_label]["support_render_kind"] = str(
                    support_render_kind
                )
                render_plan[eye_label]["support_fullframe_fallback"] = bool(
                    support_fullframe_fallback
                )
                render_plan[eye_label]["support_roi_bounds"] = (
                    None
                    if support_fullframe_fallback or support_roi_bounds is None
                    else tuple(int(v) for v in support_roi_bounds)
                )
                render_plan[eye_label]["support_roi_ratio"] = float(
                    support_roi_ratio
                )
                support_roi_state[eye_label] = render_plan[eye_label][
                    "support_roi_bounds"
                ]
                if render_profile_frame is not None:
                    render_profile_frame[
                        f"scene_support_roi_{eye_label}_ratio"
                    ] = float(support_roi_ratio)
                    render_profile_frame[
                        f"scene_support_fullframe_fallback_{eye_label}_ratio"
                    ] = (
                        1.0
                        if active_support_entry is not None
                        and support_fullframe_fallback
                        else 0.0
                    )
                    render_profile_frame[
                        f"scene_support_occlusion_candidate_{eye_label}_ratio"
                    ] = 1.0 if occlusion_candidate_suppress else 0.0
                    render_profile_frame[
                        f"scene_support_occlusion_suppressed_{eye_label}_ratio"
                    ] = 1.0 if occlusion_suppressed else 0.0
                    render_profile_frame[
                        f"scene_support_occlusion_flip_{eye_label}_ratio"
                    ] = 1.0 if occlusion_flipped else 0.0
                    render_profile_frame[
                        f"scene_support_occlusion_overlap_{eye_label}_ratio"
                    ] = float(occlusion_overlap_ratio)
                    render_profile_frame[
                        f"scene_support_occlusion_depth_gap_{eye_label}_m"
                    ] = float(occlusion_depth_gap_m)
                    render_profile_frame[
                        f"scene_support_occlusion_flip_count_{eye_label}"
                    ] = float(
                        support_occlusion_state.get(eye_label, {}).get(
                            "flip_count",
                            0,
                        )
                    )
                    if support_render_kind == "focus":
                        render_profile_frame[
                            f"scene_focus_roi_{eye_label}_ratio"
                        ] = float(support_roi_ratio)
                        render_profile_frame[
                            "scene_focus_roi_supersample_scale"
                        ] = float(support_roi_render_scale)
                        render_profile_frame[
                            f"scene_focus_fullframe_fallback_{eye_label}_ratio"
                        ] = 1.0 if support_fullframe_fallback else 0.0
            return render_plan

        raise ValueError(f"Unsupported immersive static scene mode: {static_scene_mode}")

    def _record_immersive_balanced_scene_execute_profile(
        self,
        render_profile_frame,
        render_plan,
        render_outputs,
    ):
        if render_profile_frame is None or render_outputs is None:
            return
        static_scene_mode = str(
            render_plan.get("static_scene_mode", "balanced_focus")
        ).strip().lower()
        if static_scene_mode == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_FOCUS:
            render_profile_frame["scene_render_left_wall"] = float(
                render_outputs["left"].get("background_render_wall_s", 0.0)
            )
            render_profile_frame["scene_render_right_wall"] = float(
                render_outputs["right"].get("background_render_wall_s", 0.0)
            )
            render_profile_frame["scene_render_table_left_wall"] = float(
                render_outputs["left"].get("table_render_wall_s", 0.0)
            )
            render_profile_frame["scene_render_table_right_wall"] = float(
                render_outputs["right"].get("table_render_wall_s", 0.0)
            )
            return
        if (
            static_scene_mode
            == self.IMMERSIVE_STATIC_SCENE_MODE_BALANCED_SUPPORT_FOCUS
        ):
            render_profile_frame["scene_render_left_wall"] = float(
                render_outputs["left"].get("base_render_wall_s", 0.0)
            )
            render_profile_frame["scene_render_right_wall"] = float(
                render_outputs["right"].get("base_render_wall_s", 0.0)
            )
            for eye_label in ("left", "right"):
                support_render_kind = str(
                    render_outputs[eye_label].get("support_render_kind", "none")
                ).strip().lower()
                base_table_render_wall_s = float(
                    render_outputs[eye_label].get("base_table_render_wall_s", 0.0)
                )
                if support_render_kind == "none" and base_table_render_wall_s > 0.0:
                    render_profile_frame[
                        f"scene_render_table_base_{eye_label}_wall"
                    ] = base_table_render_wall_s
                support_render_wall_s = float(
                    render_outputs[eye_label].get("support_render_wall_s", 0.0)
                )
                if support_render_kind == "table":
                    render_profile_frame[
                        f"scene_render_table_{eye_label}_wall"
                    ] = support_render_wall_s
                elif support_render_kind == "focus":
                    render_profile_frame[
                        f"scene_render_focus_{eye_label}_wall"
                    ] = support_render_wall_s
            return
        raise ValueError(f"Unsupported immersive static scene mode: {static_scene_mode}")

